export const USAGE = """
Topaz Core Kit

  topaz-core-kit help
  topaz-core-kit --version
  topaz-core-kit hash <file>
  topaz-core-kit kit verify
  topaz-core-kit kit build [--out-dir <directory>]
  topaz-core-kit kit build-id
  topaz-core-kit kit refresh [--check]
  topaz-core-kit kit install --archive <file>
  topaz-core-kit kit install --check
  topaz-core-kit kit binary-info --file <executable> [--other <executable>]
  topaz-core-kit kit payload-assemble --build-dir <directory> --recipe <repository-file> --out-dir <new-directory>
  topaz-core-kit kit payload-compare --payload-dir <directory> --other <directory>
  topaz-core-kit kit payload-promote --payload-dir <directory> --other <directory> --out-dir <new-directory>
  topaz-core-kit kit payload-pack --payload-dir <directory> --other <directory> --out-dir <new-directory> --repository <owner/name> --tag <release> --source-commit <commit>
  topaz-core-kit kit payload-record --target <rust-target> --payload-dir <directory>
  topaz-core-kit kit payload-verify --payload-dir <directory>
  topaz-core-kit check --root <project>
  topaz-core-kit build --root <project> --out-dir <directory>
  topaz-core-kit check --source <file>
  topaz-core-kit emit-rust --source <file> --out <file>
  topaz-core-kit request --root <project> --out <file>
  topaz-core-kit request --source <file> --out <file>
  topaz-core-kit build --source <file> --out-dir <directory>

check, emit-rust and build accept exactly one of --root, --source and
--request. Project mode reads topaz.toml and resolves local modules using
the canonical compiler. request saves a complete source snapshot.
"""

export record Command {
  name: string,
  source: string,
  root: string,
  requestPath: string,
  output: string,
  target: string,
  recipe: string,
  other: string,
  destination: string,
  repository: string,
  tag: string,
  sourceCommit: string,
}

function usageError(message: string) -> Result<Command, string> {
  Err("{message}\n\n{USAGE}")
}

function emptyCommand(name: string) -> Command {
  Command {
    name: name, source: "", root: "", requestPath: "", output: "", target: "",
    recipe: "", other: "", destination: "", repository: "", tag: "", sourceCommit: "",
  }
}

function parseDistribution(args: Array<string>) -> Result<Command, string> {
  let name = args[1]
  let allowed = if name == "binary-info" { ["--file", "--other"] }
    else if name == "payload-assemble" { ["--build-dir", "--recipe", "--out-dir"] }
    else if name == "payload-promote" { ["--payload-dir", "--other", "--out-dir"] }
    else if name == "payload-pack" {
      ["--payload-dir", "--other", "--out-dir", "--repository", "--tag", "--source-commit"]
    }
    else { ["--payload-dir", "--other"] }
  let mut values: Map<string, string> = map {}
  let mut index = 2
  while index < args.length {
    let option = args[index]
    let mut admitted = false
    for expected in allowed { if option == expected { admitted = true } }
    if !admitted { return usageError("unknown {name} option `{option}`") }
    if index + 1 >= args.length || args[index + 1] == "" {
      return usageError("{option} requires a nonempty value")
    }
    if values.containsKey(option) { return usageError("{option} was specified more than once") }
    values.insert(option, args[index + 1])
    index += 2
  }
  for option in allowed {
    if name == "binary-info" && option == "--other" { continue }
    if !values.containsKey(option) { return usageError("{name} requires {option}") }
  }
  Ok(Command {
    ...emptyCommand("kit-{name}"),
    source: values.getOr(if name == "binary-info" { "--file" } else { "--build-dir" }, ""),
    output: values.getOr(if name == "payload-assemble" { "--out-dir" } else { "--payload-dir" }, ""),
    recipe: values.getOr("--recipe", "").replace("\\", "/"),
    other: values.getOr("--other", ""),
    destination: values.getOr("--out-dir", ""), repository: values.getOr("--repository", ""),
    tag: values.getOr("--tag", ""), sourceCommit: values.getOr("--source-commit", ""),
  })
}

function parseKit(args: Array<string>) -> Result<Command, string> {
  if args.length >= 2 && (args[1] == "binary-info" || args[1] == "payload-assemble" ||
    args[1] == "payload-compare" || args[1] == "payload-promote" || args[1] == "payload-pack") {
    return parseDistribution(args)
  }
  if args.length >= 2 && (args[1] == "verify" || args[1] == "build-id") {
    let name = args[1]
    if args.length != 2 { return usageError("kit {name} accepts no arguments") }
    return Ok(emptyCommand("kit-{name}"))
  }
  if args.length >= 2 && args[1] == "install" {
    if args.length == 3 && args[2] == "--check" { return Ok(emptyCommand("kit-install-check")) }
    if args.length == 4 && args[2] == "--archive" && args[3] != "" {
      return Ok(Command { ...emptyCommand("kit-install"), source: args[3] })
    }
    return usageError("kit install requires either --archive <file> or --check; use install-core-kit for an explicit download")
  }
  if args.length >= 2 && args[1] == "refresh" {
    if args.length == 2 { return Ok(emptyCommand("kit-refresh")) }
    if args.length == 3 && args[2] == "--check" { return Ok(emptyCommand("kit-refresh-check")) }
    return usageError("kit refresh accepts only an optional --check")
  }
  if args.length >= 2 && args[1] == "build" {
    if args.length == 2 { return Ok(emptyCommand("kit-build")) }
    if args.length != 4 || args[2] != "--out-dir" || args[3] == "" {
      return usageError("kit build accepts only an optional --out-dir <directory>")
    }
    return Ok(Command { ...emptyCommand("kit-build"), output: args[3] })
  }
  if args.length < 2 || (args[1] != "payload-record" && args[1] != "payload-verify") {
    return usageError("kit requires verify, build, build-id, refresh, install, binary-info or a payload command")
  }
  let name = args[1]
  let mut output = ""
  let mut target = ""
  let mut index = 2
  while index < args.length {
    let option = args[index]
    if option != "--payload-dir" && option != "--target" {
      return usageError("unknown {name} option `{option}`")
    }
    if index + 1 >= args.length || args[index + 1] == "" {
      return usageError("{option} requires a nonempty value")
    }
    if option == "--target" {
      if name == "payload-verify" { return usageError("payload-verify reads its target from payload.json") }
      if target != "" { return usageError("--target was specified more than once") }
      target = args[index + 1]
    } else {
      if output != "" { return usageError("--payload-dir was specified more than once") }
      output = args[index + 1]
    }
    index += 2
  }
  if output == "" { return usageError("{name} requires --payload-dir") }
  if name == "payload-record" && target == "" { return usageError("payload-record requires --target") }
  Ok(Command { ...emptyCommand("kit-{name}"), output: output, target: target })
}

export function parse(args: Array<string>) -> Result<Command, string> {
  let name = if args.length == 0 { "help" } else { args[0] }
  if name == "help" || name == "--help" || name == "--version" {
    if args.length > 1 { return usageError("{name} accepts no arguments") }
    return Ok(emptyCommand(name))
  }
  if name == "hash" {
    if args.length != 2 || args[1] == "" { return usageError("hash requires exactly one file path") }
    return Ok(Command { ...emptyCommand(name), source: args[1] })
  }
  if name == "kit" { return parseKit(args) }
  if name != "check" && name != "emit-rust" && name != "request" && name != "build" {
    return usageError("unknown command `{name}`")
  }
  let mut source = ""
  let mut root = ""
  let mut requestPath = ""
  let mut output = ""
  let mut index = 1
  while index < args.length {
    let option = args[index]
    if option != "--source" && option != "--root" && option != "--request" && option != "--out" && option != "--out-dir" {
      return usageError("unknown option `{option}`")
    }
    if index + 1 >= args.length || args[index + 1] == "" {
      return usageError("{option} requires a nonempty value")
    }
    let value = args[index + 1]
    if option == "--source" {
      if source != "" { return usageError("--source was specified more than once") }
      source = value
    } else if option == "--root" {
      if root != "" { return usageError("--root was specified more than once") }
      root = value
    } else if option == "--request" {
      if requestPath != "" { return usageError("--request was specified more than once") }
      requestPath = value
    } else {
      if name == "check" { return usageError("check does not accept an output option") }
      if (name == "build") != (option == "--out-dir") {
        return usageError("use --out-dir for build, and --out for emit-rust or request")
      }
      if output != "" { return usageError("the output was specified more than once") }
      output = value
    }
    index += 2
  }
  let modes = (if source != "" { 1 } else { 0 }) +
    (if root != "" { 1 } else { 0 }) + (if requestPath != "" { 1 } else { 0 })
  if modes != 1 { return usageError("choose exactly one of --source, --root and --request") }
  if name == "request" && requestPath != "" {
    return usageError("request creates a source snapshot from --source or --root")
  }
  if name != "check" && output == "" { return usageError("{name} requires an explicit output path") }
  Ok(Command { ...emptyCommand(name), source: source, root: root, requestPath: requestPath, output: output })
}

import std.bytes { Bytes }
import std.fs as files
import std.io as io
import std.json as json
import src.contracts { Native, fileMetadata }
import src.release_image { Image, MAX_IMAGE_BYTES, inspectBytes }

const SAMPLE_LIMIT = 16
const BLOCK_BYTES = 65536

record Comparison derives JSON {
  schema: string,
  left: Image,
  right: Image,
  sameBytes: bool,
  firstDifferentOffsets: Array<int>,
}

function readImage(path: string, native: Native) -> Result<Bytes, string> {
  // The mechanical metadata query bounds allocation before the complete-byte
  // filesystem API is used. A concurrent file change still gets checked after.
  let meta = fileMetadata(path, native)?
  if meta.bytes == 0 || meta.bytes > MAX_IMAGE_BYTES {
    return Err("binary inspection requires a nonempty regular file no larger than 512 MiB")
  }
  let bytes = files.readBytes(meta.path)?
  if bytes.length() != meta.bytes { return Err("binary file size changed during inspection") }
  Ok(bytes)
}

function sampledDifferences(left: Bytes, right: Bytes) -> Array<int> {
  let common = if left.length() < right.length() { left.length() } else { right.length() }
  let mut offsets: Array<int> = []
  let mut start = 0
  while start < common && offsets.length < SAMPLE_LIMIT {
    let end = if common - start > BLOCK_BYTES { start + BLOCK_BYTES } else { common }
    if left.slice(start, end) != right.slice(start, end) {
      let mut position = start
      while position < end && offsets.length < SAMPLE_LIMIT {
        if left.get(position) != right.get(position) { offsets.push(position) }
        position += 1
      }
    }
    start = end
  }
  if left.length() != right.length() && offsets.length < SAMPLE_LIMIT { offsets.push(common) }
  offsets
}

export function inspect(path: string, other: string, native: Native) -> Result<int, string> {
  let bytes = readImage(path, native)?
  let left = inspectBytes(bytes)?
  if other == "" {
    io.writeLine(json.stringify(left)?)
    return Ok(0)
  }
  let compared = readImage(other, native)?
  let right = inspectBytes(compared)?
  let report = Comparison {
    schema: "topaz.core-kit-binary-comparison/v1", left: left, right: right,
    sameBytes: bytes == compared, firstDifferentOffsets: sampledDifferences(bytes, compared),
  }
  io.writeLine(json.stringify(report)?)
  Ok(0)
}

import std.fs as files
import std.io as io
import std.json as json
import src.arguments { Command, USAGE }
import src.binary_info as binaryInfo
import src.contracts { Capture, Compile, CompilerRequest, Native, Process, Provider, VERSION }
import src.kit_build { buildKit }
import src.installation as installation
import src.native_build { build }
import src.payload { recordPayload, verifyPayload }
import src.project { Project, PROJECT_REQUEST_SCHEMA, decodeSnapshot, encodeSnapshot, prepare }
import src.project_manifest { ProjectConfig }
import src.refresh { refresh }
import src.release_payload as releasePayload
import src.release_package as releasePackage
import src.requests { encode, fromSource, fromText }
import src.responses { completed, rustSource }
import src.verification { verify }

function closedFacts(query: string) -> Result<string, string> {
  Err("source facts are incomplete; use --root for a project or provide a complete saved request")
}

record Input {
  request: CompilerRequest,
  provide: Provider,
  project: Option<Project>,
  configuration: Option<ProjectConfig>,
}

function selectInput(command: Command, repositoryRoot: string, native: Native) -> Result<Input, string> {
  if command.root != "" {
    let project = prepare(command.root, repositoryRoot,
      (root: string, path: string) => native("inspect-rooted", [root, path]))?
    return Ok(Input {
      request: project.request, provide: project.provide,
      project: Some(project), configuration: Some(project.configuration),
    })
  }
  if command.source != "" {
    return Ok(Input {
      request: fromSource(command.source, repositoryRoot)?, provide: closedFacts,
      project: None, configuration: None,
    })
  }
  let text = files.readText(command.requestPath)?
  if text.byteLength() > 134217728 { return Err("saved request exceeds 128 MiB") }
  let document = match json.parse(text) {
    case Ok(value) => value
    case Err(error) => return Err("invalid saved request JSON at {error.line}:{error.column}: {error.message}")
  }
  let schema = match document.get("schema") {
    case Some(value) => match value.asString() {
      case Some(value) => value
      case None => ""
    }
    case None => ""
  }
  if schema == PROJECT_REQUEST_SCHEMA {
    let saved = decodeSnapshot(text)?
    let request = fromText(json.stringify(saved.request)?)?
    return Ok(Input {
      request: request, provide: closedFacts,
      project: None, configuration: Some(saved.configuration),
    })
  }
  Ok(Input { request: fromText(text)?, provide: closedFacts, project: None, configuration: None })
}

export function execute(
  command: Command,
  repositoryRoot: string,
  compile: Compile,
  process: Process,
  native: Native,
  capture: Capture,
) -> Result<int, string> {
  if command.name == "help" || command.name == "--help" {
    io.writeLine(USAGE)
    return Ok(0)
  }
  if command.name == "--version" {
    io.writeLine(VERSION)
    return Ok(0)
  }
  if command.name == "hash" {
    let bytes = files.readBytes(command.source)?
    io.writeLine(bytes.sha256().toHex())
    return Ok(0)
  }
  if command.name == "kit-verify" { return verify(repositoryRoot) }
  if command.name == "kit-build-id" {
    io.writeLine(native("generated-cli-sha256", [])?)
    return Ok(0)
  }
  if command.name == "kit-install" { return installation.install(repositoryRoot, command.source, native, capture) }
  if command.name == "kit-install-check" { return installation.checkInstalled(repositoryRoot, native) }
  if command.name == "kit-build" {
    return buildKit(repositoryRoot, command.output, compile, process, native, capture)
  }
  if command.name == "kit-refresh" || command.name == "kit-refresh-check" {
    return refresh(repositoryRoot, command.name == "kit-refresh-check", compile, native)
  }
  if command.name == "kit-binary-info" { return binaryInfo.inspect(command.source, command.other, native) }
  if command.name == "kit-payload-assemble" {
    return releasePayload.assemble(repositoryRoot, command.source, command.recipe, command.output, native)
  }
  if command.name == "kit-payload-compare" {
    return releasePayload.compare(repositoryRoot, command.output, command.other, native)
  }
  if command.name == "kit-payload-promote" {
    return releasePayload.promote(repositoryRoot, command.output, command.other, command.destination, native, capture)
  }
  if command.name == "kit-payload-pack" {
    return releasePackage.pack(repositoryRoot, command.output, command.other, command.destination,
      command.repository, command.tag, command.sourceCommit, native, capture)
  }
  if command.name == "kit-payload-record" {
    return recordPayload(repositoryRoot, command.output, command.target)
  }
  if command.name == "kit-payload-verify" {
    return verifyPayload(repositoryRoot, command.output)
  }
  let selected = selectInput(command, repositoryRoot, native)?
  let terminal = if command.name == "check" || command.name == "request" { "typed" } else { "rust-source" }
  let input = encode(selected.request, terminal)?
  if command.name == "request" {
    let saved = match selected.project {
      case Some(project) => {
        // The unchanged core discovers the module graph through the Topaz
        // provider. Save the resulting closed facts and the package grants.
        completed(compile(input, selected.provide)?, "typed")?
        encodeSnapshot(project)?
      }
      case None => input
    }
    native("mkdir-parent", [command.output])?
    files.writeText(command.output, "{saved}\n")?
    io.writeLine("closed compiler request: {command.output}")
    return Ok(0)
  }
  let response = match compile(input, selected.provide) {
    case Ok(text) => completed(text, terminal)?
    case Err(message) => {
      if command.source != "" && message.contains("source facts are incomplete") {
        return Err("{message}\nsource mode supports one file with bundled std modules; use --root for local imports")
      }
      return Err(message)
    }
  }
  if command.name == "check" {
    io.writeLine("check completed")
    return Ok(0)
  }
  let source = rustSource(response)?
  if command.name == "emit-rust" {
    native("mkdir-parent", [command.output])?
    files.writeText(command.output, source)?
    io.writeLine("generated Rust: {command.output}")
    return Ok(0)
  }
  build(source, command.output, repositoryRoot, process, native, capture, selected.configuration)
}

import std.bytes { Bytes }
import std.fs as files
import std.json as json
import src.payload_files { repositoryFiles, requireRegularInput }

export const CATALOG_PATH = "core-kit/downloads.data"
export const CATALOG_SCHEMA = "topaz.core-kit-downloads/v1"
export const MAX_ARCHIVE_BYTES = 536870912
export const MAX_EXECUTABLE_BYTES = 268435456

export record Download {
  target: string,
  repository: string,
  tag: string,
  sourceCommit: string,
  inputSetSha256: string,
  assetName: string,
  assetBytes: int,
  assetSha256: string,
  executableBytes: int,
  executableSha256: string,
}

function targetName(target: string) -> Result<(), string> {
  match target {
    case "x86_64-unknown-linux-gnu" | "aarch64-unknown-linux-gnu" |
      "x86_64-pc-windows-msvc" | "aarch64-pc-windows-msvc" |
      "x86_64-apple-darwin" | "aarch64-apple-darwin" => Ok(())
    case _ => Err("download target is outside the supported platform names")
  }
}

function component(text: string, label: string) -> Result<string, string> {
  let bytes = text.encodeUtf8()
  if bytes.length() == 0 || bytes.length() > 128 || text.endsWith(".") {
    return Err("{label} must be a portable name of 1 to 128 ASCII bytes")
  }
  let mut folded: Array<int> = []
  let mut index = 0
  while index < bytes.length() {
    let byte = bytes.get(index) ?? 0
    let alphanumeric = (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122) ||
      (byte >= 48 && byte <= 57)
    if !alphanumeric && (index == 0 || (byte != 46 && byte != 95 && byte != 45)) {
      return Err("{label} contains an unsupported character")
    }
    folded.push(if byte >= 65 && byte <= 90 { byte + 32 } else { byte })
    index += 1
  }
  let lower = Bytes.fromArray(folded)?
  lower.decodeUtf8()
}

export function validatePublication(repository: string, tag: string, sourceCommit: string) -> Result<(), string> {
  let parts = repository.split("/")
  if parts.length != 2 { return Err("release repository must be owner/name") }
  component(parts[0], "repository owner")?
  component(parts[1], "repository name")?
  if component(tag, "release tag")? == "latest" {
    return Err("download catalogue must pin a named release rather than latest")
  }
  hexadecimal(sourceCommit, 40, "source commit")
}

function hexadecimal(text: string, length: int, label: string) -> Result<(), string> {
  let bytes = text.encodeUtf8()
  if bytes.length() != length { return Err("{label} must contain {length} lowercase hexadecimal characters") }
  for byte in bytes.toArray() {
    if !((byte >= 48 && byte <= 57) || (byte >= 97 && byte <= 102)) {
      return Err("{label} must use lowercase hexadecimal")
    }
  }
  Ok(())
}

function positiveDecimal(text: string, maximum: int, label: string) -> Result<int, string> {
  let bytes = text.encodeUtf8()
  if bytes.length() == 0 || bytes.length() > 10 || (bytes.get(0) ?? 0) == 48 {
    return Err("{label} must be a positive canonical decimal integer")
  }
  let mut value = 0
  for byte in bytes.toArray() {
    if byte < 48 || byte > 57 { return Err("{label} contains a nondecimal character") }
    let digit = byte - 48
    if value > (maximum - digit) / 10 { return Err("{label} exceeds {maximum} bytes") }
    value = value * 10 + digit
  }
  if value <= 0 || value > maximum { return Err("{label} exceeds its supported byte range") }
  Ok(value)
}

function validate(entry: Download) -> Result<(), string> {
  targetName(entry.target)?
  validatePublication(entry.repository, entry.tag, entry.sourceCommit)?
  hexadecimal(entry.inputSetSha256, 64, "input-set digest")?
  hexadecimal(entry.assetSha256, 64, "archive digest")?
  hexadecimal(entry.executableSha256, 64, "executable digest")?
  if entry.assetName != "topaz-core-kit-{entry.target}.tar.gz" {
    return Err("release asset name must be the fixed target-specific tar.gz name")
  }
  positiveDecimal("{entry.assetBytes}", MAX_ARCHIVE_BYTES, "archive size")?
  positiveDecimal("{entry.executableBytes}", MAX_EXECUTABLE_BYTES, "executable size")?
  Ok(())
}

function line(entry: Download) -> string {
  "{entry.target}|{entry.repository}|{entry.tag}|{entry.sourceCommit}|{entry.inputSetSha256}|{entry.assetName}|{entry.assetBytes}|{entry.assetSha256}|{entry.executableBytes}|{entry.executableSha256}"
}

export function encode(entries: Array<Download>) -> Result<string, string> {
  if entries.length > 6 { return Err("download catalogue may contain at most six platform rows") }
  let mut names: Array<string> = []
  let mut rows: Map<string, string> = map {}
  for entry in entries {
    validate(entry)?
    if rows.containsKey(entry.target) { return Err("download catalogue repeats a target") }
    rows.insert(entry.target, line(entry))
    names.push(entry.target)
  }
  names.sort()
  let mut lines = [CATALOG_SCHEMA]
  for name in names { lines.push(rows.getOr(name, "")) }
  Ok("{lines.join("\n")}\n")
}

export function parse(text: string) -> Result<Array<Download>, string> {
  if text.byteLength() == 0 || text.byteLength() > 65536 || !text.endsWith("\n") {
    return Err("download catalogue must be nonempty, LF terminated and no larger than 64 KiB")
  }
  for byte in text.encodeUtf8().toArray() {
    if byte != 10 && (byte < 32 || byte > 126) {
      return Err("download catalogue must use printable ASCII and LF line endings")
    }
  }
  let lines = text.split("\n")
  if lines[0] != CATALOG_SCHEMA || lines.length > 8 {
    return Err("download catalogue has an unsupported schema or too many rows")
  }
  let mut entries: Array<Download> = []
  let mut index = 1
  while index + 1 < lines.length {
    let fields = lines[index].split("|")
    if fields.length != 10 { return Err("download catalogue rows must contain exactly ten fields") }
    let entry = Download {
      target: fields[0], repository: fields[1], tag: fields[2], sourceCommit: fields[3],
      inputSetSha256: fields[4], assetName: fields[5],
      assetBytes: positiveDecimal(fields[6], MAX_ARCHIVE_BYTES, "archive size")?,
      assetSha256: fields[7],
      executableBytes: positiveDecimal(fields[8], MAX_EXECUTABLE_BYTES, "executable size")?,
      executableSha256: fields[9],
    }
    validate(entry)?
    entries.push(entry)
    index += 1
  }
  if text != encode(entries)? {
    return Err("download catalogue must use sorted unique target rows and one final LF")
  }
  Ok(entries)
}

export function load(root: string) -> Result<Array<Download>, string> {
  requireRegularInput(root, CATALOG_PATH)?
  parse(files.readText("{root}/{CATALOG_PATH}")?)
}

export function select(entries: Array<Download>, target: string) -> Result<Download, string> {
  targetName(target)?
  for entry in entries { if entry.target == target { return Ok(entry) } }
  Err("no verified Core Kit download is recorded for {target}; use ./bootstrap or bootstrap.cmd to build this checkout")
}

export function inputSetId(root: string) -> Result<string, string> {
  // The catalogue is transport metadata added after the artifact exists.
  // Including its final archive hash among the artifact's own inputs would
  // create a self-reference. repositoryFiles enforces its exclusion.
  let records = repositoryFiles(root)?
  let canonical = json.stringify(records)?
  Ok(canonical.encodeUtf8().sha256().toHex())
}

import std.fs as files
import std.io as io
import std.json as json
import src.contracts { Capture, Native, fileMetadata }
import src.download_catalog { CATALOG_PATH, MAX_ARCHIVE_BYTES, Download, encode, inputSetId, load, select }
import src.payload { executableFor }
import src.release_archive { ArchiveEntry, decode }
import src.release_payload { Verified, checkNative, verifyAssembled }
import src.release_package { archiveBytes }
import src.toolchain { BuildTarget }
import src.verification { validateRecordedInputs }

const RECEIPT = "installation.data"
const RECEIPT_SCHEMA = "topaz.core-kit-installation/v1"

function kind(directory: string, name: string) -> Result<string, string> {
  for entry in files.list(directory)? {
    if entry.name == name { return Ok(entry.kind) }
  }
  Ok("missing")
}

function receipt(download: Download) -> string {
  "{RECEIPT_SCHEMA}|{download.target}|{download.assetSha256}|{download.inputSetSha256}\n"
}

function selected(root: string, native: Native) -> Result<Download, string> {
  let catalogue = fileMetadata("{root}/{CATALOG_PATH}", native)?
  if catalogue.bytes == 0 || catalogue.bytes > 65536 {
    return Err("download catalogue must be nonempty and no larger than 64 KiB")
  }
  let target = json.parseAs<BuildTarget>(native("build-target", [])?)?
  let download = select(load(root)?, target.target)?
  validateRecordedInputs(root)?
  if inputSetId(root)? != download.inputSetSha256 {
    return Err("the pinned download does not match this checkout's source inputs; use its matching source revision or bootstrap locally")
  }
  Ok(download)
}

function unchanged(root: string, download: Download, native: Native) -> Result<(), string> {
  if encode([selected(root, native)?])? != encode([download])? {
    return Err("download selection changed during installation; no new installation was activated")
  }
  Ok(())
}

// Inspect every fixed component without following an existing directory link.
// No version or staging path is supplied by a downloaded archive.
function cacheDirectory(root: string, target: string, create: bool, native: Native) -> Result<string, string> {
  let mut current = root
  for name in ["out", "core-kit-installed", target] {
    let entryKind = kind(current, name)?
    if entryKind == "missing" {
      if !create { return Err("the pinned Core Kit is not installed; run install-core-kit or install-core-kit.cmd") }
      current = native("mkdir-new", ["{current}/{name}"])?
    } else if entryKind == "directory" {
      current = "{current}/{name}"
    } else {
      return Err("installation cache components must be real directories: {current}/{name}")
    }
  }
  Ok(current)
}

function verifyExecutable(directory: string, download: Download, native: Native) -> Result<(), string> {
  let name = executableFor(download.target)?
  let file = fileMetadata("{directory}/{name}", native)?
  if file.bytes != download.executableBytes { return Err("installed executable size differs from the pinned download") }
  let bytes = files.readBytes(file.path)?
  if bytes.length() != file.bytes || bytes.sha256().toHex() != download.executableSha256 {
    return Err("installed executable bytes differ from the pinned download")
  }
  Ok(())
}

function verifyVersion(root: string, directory: string, download: Download, native: Native) -> Result<Verified, string> {
  let entries = files.list(directory)?
  if entries.length != 2 || kind(directory, "payload")? != "directory" || kind(directory, RECEIPT)? != "file" {
    return Err("installed version must contain only its payload directory and completion receipt")
  }
  let recorded = fileMetadata("{directory}/{RECEIPT}", native)?
  let expected = receipt(download)
  if recorded.bytes != expected.byteLength() || files.readText(recorded.path)? != expected {
    return Err("installation receipt does not match the pinned download")
  }
  if recorded.mode != "" && recorded.mode != "0644" { return Err("installation receipt has an unexpected file mode") }
  let payload = "{directory}/payload"
  verifyExecutable(payload, download, native)?
  let verified = verifyAssembled(root, payload, native)?
  if verified.assembly.target != download.target || !verified.loaded.recipe.releaseReady {
    return Err("installed payload is not an approved candidate for the pinned platform")
  }
  // A mutable payload.json can describe a changed local candidate. Bind the
  // complete installation to the catalogue's immutable archive hash as well.
  // Canonical packaging makes this check independent of the installation path.
  let archive = archiveBytes(verified, native)?
  if archive.length() != download.assetBytes || archive.sha256().toHex() != download.assetSha256 {
    return Err("complete installed payload differs from the pinned release archive")
  }
  Ok(verified)
}

function readArchive(path: string, download: Download, native: Native) -> Result<Array<ArchiveEntry>, string> {
  let file = fileMetadata(path, native)?
  if file.bytes != download.assetBytes || file.bytes > MAX_ARCHIVE_BYTES {
    return Err("archive size differs from the pinned download")
  }
  let bytes = files.readBytes(file.path)?
  if bytes.length() != file.bytes || bytes.sha256().toHex() != download.assetSha256 {
    return Err("archive SHA-256 differs from the pinned download")
  }
  // Decode validates the complete canonical container before any file is
  // materialized. Only flat regular members and bounded bytes are admitted.
  let entries = decode(bytes)?
  let executable = executableFor(download.target)?
  let mut found = false
  for entry in entries {
    if entry.path == executable {
      if entry.bytes.length() != download.executableBytes || entry.bytes.sha256().toHex() != download.executableSha256 {
        return Err("archive executable differs from the pinned download")
      }
      found = true
    }
  }
  if !found { return Err("archive has no executable for the pinned platform") }
  Ok(entries)
}

function newStage(base: string, download: Download, native: Native) -> Result<string, string> {
  let mut occupied: Set<string> = set {}
  for entry in files.list(base)? { occupied.add(entry.name) }
  let mut sequence = 1
  while sequence <= 10000 {
    let name = "stage-{download.assetSha256}-{sequence}"
    if !occupied.contains(name) { return native("mkdir-new", ["{base}/{name}"]) }
    sequence += 1
  }
  Err("installation cache contains too many retained staging directories")
}

function materialize(root: string, stage: string, entries: Array<ArchiveEntry>, download: Download, native: Native, capture: Capture) -> Result<(), string> {
  let directory = native("mkdir-new", ["{stage}/payload"])?
  for entry in entries {
    let path = "{directory}/{entry.path}"
    files.writeBytes(path, entry.bytes)?
    native("set-file-mode", [path, entry.mode])?
  }
  verifyExecutable(directory, download, native)?
  let verified = verifyAssembled(root, directory, native)?
  if verified.assembly.target != download.target {
    return Err("archive assembly target differs from the pinned download")
  }
  checkNative(root, verified, native, capture)?
  unchanged(root, download, native)?
  files.writeText("{stage}/{RECEIPT}", receipt(download))?
  native("set-file-mode", ["{stage}/{RECEIPT}", "0644"])?
  verifyVersion(root, stage, download, native)?
  Ok(())
}

function installedVersion(root: string, base: string, download: Download, native: Native) -> Result<Option<Verified>, string> {
  let directory = "{base}/{download.assetSha256}"
  let entry = kind(base, download.assetSha256)?
  if entry == "missing" { return Ok(None) }
  if entry != "directory" {
    return Err("existing installation destination is not a real directory: {directory}\nInspect the {entry} at that path and move it aside before reinstalling.")
  }
  match verifyVersion(root, directory, download, native) {
    case Ok(version) => Ok(Some(version))
    case Err(error) => {
      // A checkout change during verification can also invalidate a good version.
      unchanged(root, download, native)?
      Err("{error}\nInspect the installed version at {directory}. If it is damaged, move only that version directory aside and rerun the installer.")
    }
  }
}

function installLocked(root: string, base: string, entries: Array<ArchiveEntry>, download: Download, native: Native, capture: Capture) -> Result<int, string> {
  let destination = "{base}/{download.assetSha256}"
  match installedVersion(root, base, download, native)? {
    case Some(version) => {
      checkNative(root, version, native, capture)?
      unchanged(root, download, native)?
      io.writeLine("The pinned Core Kit is already installed and verified at {destination}/payload")
      return Ok(0)
    }
    case None => ()
  }
  let stage = newStage(base, download, native)?
  match materialize(root, stage, entries, download, native, capture) {
    case Ok(_) => ()
    case Err(error) => return Err("{error}\nIncomplete installation retained for inspection at {stage}")
  }
  // The lock excludes concurrent Kit installers for this target. The complete
  // version becomes visible through one sibling rename; older versions remain.
  unchanged(root, download, native)?
  match native("rename-directory-new", [stage, destination]) {
    case Ok(_) => ()
    case Err(error) => return Err("{error}\nVerified installation remains staged at {stage}")
  }
  io.writeLine("Installed the pinned Core Kit at {destination}/payload")
  io.writeLine("Use this checkout's topaz or topaz.cmd launcher.")
  Ok(0)
}

export function checkInstalled(root: string, native: Native) -> Result<int, string> {
  let download = selected(root, native)?
  let base = cacheDirectory(root, download.target, false, native)?
  match installedVersion(root, base, download, native)? {
    case None => return Err("the pinned Core Kit is not installed; run install-core-kit or install-core-kit.cmd")
    case Some(_) => ()
  }
  unchanged(root, download, native)?
  io.writeLine("The installed Core Kit and current source inputs match the pinned download.")
  Ok(0)
}

export function install(root: string, archive: string, native: Native, capture: Capture) -> Result<int, string> {
  let download = selected(root, native)?
  let entries = readArchive(archive, download, native)?
  unchanged(root, download, native)?
  let base = cacheDirectory(root, download.target, true, native)?
  let lock = native("mkdir-new", ["{base}/.install-lock"])?
  let result = installLocked(root, base, entries, download, native, capture)
  let released = native("rmdir-empty", [lock])
  match released {
    case Ok(_) => result
    case Err(error) => match result {
      case Ok(_) => Err("installation completed but its lock could not be released: {error}\nLock retained at {lock}")
      case Err(previous) => Err("{previous}\nInstallation lock could not be released: {error}\nLock retained at {lock}")
    }
  }
}

import std.fs as files
import std.io as io
import src.contracts { Capture, Compile, Native, Process }
import src.kit_inputs { prepare }
import src.responses { completed, rustSource }
import src.toolchain { checkToolchain }

const MARKER = "topaz-core-kit.kit-build/v1\n"

function prepareOutput(output: string) -> Result<(), string> {
  let entries = files.list(output)?
  if entries.length == 0 { return Ok(()) }
  let mut managed = false
  for entry in entries {
    if entry.kind == "symlink" {
      return Err("Kit output must not contain symlinks: {entry.name}")
    }
    if entry.name == ".topaz-core-kit-kit-build" && entry.kind == "file" {
      managed = true
    }
  }
  if !managed || files.readText("{output}/.topaz-core-kit-kit-build")? != MARKER {
    return Err("Kit output must be empty or contain a previous kit build; refusing to overwrite another project")
  }
  Ok(())
}

function closedFacts(query: string) -> Result<string, string> {
  Err("CLI source facts are incomplete; update its explicit source and directory mappings")
}

export function buildKit(
  repositoryRoot: string,
  requestedOutput: string,
  compile: Compile,
  process: Process,
  native: Native,
  capture: Capture,
) -> Result<int, string> {
  let target = checkToolchain(repositoryRoot, native, capture)?
  let input = prepare(repositoryRoot)?
  let requested = if requestedOutput == "" {
    "{repositoryRoot}/out/core-kit-build"
  } else {
    requestedOutput
  }
  let output = native("mkdir", [requested])?
  prepareOutput(output)?
  files.writeText("{output}/.topaz-core-kit-kit-build", MARKER)?
  files.writeText("{output}/cli.request.json", "{input}\n")?

  io.writeLine("Compiling the local Topaz CLI")
  let response = compile(input, closedFacts)?
  files.writeText("{output}/cli.response.json", "{response}\n")?
  let generated = rustSource(completed(response, "rust-source")?)?
  let generatedPath = "{output}/generated_cli.rs"
  files.writeText(generatedPath, generated)?

  io.writeLine("Linking Core Kit with the public runtime")
  let code = process(
    "cargo",
    [
      "build", "--manifest-path", "{repositoryRoot}/compiler/Cargo.toml",
      "-p", "topaz-core-kit-native", "--bin", "topaz-core-kit",
      "--features", "native-cli", "--release", "--frozen",
      "--message-format=short", "--target", target.target,
      "--target-dir", "{repositoryRoot}/compiler/target",
    ],
    "{repositoryRoot}/compiler",
    [
      "RUSTUP_TOOLCHAIN=1.96.0", "RUSTUP_AUTO_INSTALL=0", "CARGO_NET_OFFLINE=true",
      "TOPAZ_CORE_KIT_ROOT={repositoryRoot}",
      "TOPAZ_CORE_KIT_GENERATED_CLI={generatedPath}",
    ],
  )?
  if code != 0 { return Ok(code) }
  let binary = "topaz-core-kit{target.executableSuffix}"
  native("copy-file", [
    "{repositoryRoot}/compiler/target/{target.target}/release/{binary}",
    "{output}/{binary}",
  ])?
  io.writeLine("Core Kit built at {output}/{binary}")
  io.writeLine("Keep the executable inside its checkout or set TOPAZ_CORE_KIT_ROOT to that checkout")
  Ok(0)
}

import std.fs as files
import std.json as json
import src.contracts {
  COMPILER_SOURCE_SET, CompilerRequest, HostFact, PackageFacts, StandardModule,
}
import src.requests { fromFile }

record SourceMapping derives JSON {
  logicalPath: string,
  path: string,
}

record StandardMapping derives JSON {
  identity: string,
  path: string,
  sourceFile: string,
}

record Descriptor derives JSON {
  schema: string,
  requestFile: string,
  compilerSourceSetId: string,
  sourceFiles: Array<SourceMapping>,
  standardModules: Array<StandardMapping>,
}

record CoreManifest derives JSON {
  schema: string,
  sourceSetId: string,
  generatedRustSha256: string,
}

function relativePath(path: string) -> Result<(), string> {
  if path == "" || path.byteLength() > 4096 || path.contains("\\") || path.contains(":") {
    return Err("CLI input mapping must use a relative slash-delimited path: {path}")
  }
  for segment in path.split("/") {
    if segment == "" || segment == "." || segment == ".." {
      return Err("CLI input mapping must not contain empty or traversal segments: {path}")
    }
    for byte in segment.encodeUtf8().toArray() {
      if byte < 32 || byte == 127 {
        return Err("CLI input mapping contains a control character")
      }
    }
  }
  Ok(())
}

// The selected checkout is the anchor. Every mapped component below it must
// be a regular file or directory, so input mappings cannot follow symlinks.
function repositoryFile(root: string, path: string) -> Result<string, string> {
  relativePath(path)?
  let parts = path.split("/")
  let mut parent = root
  let mut index = 0
  while index < parts.length {
    let name = parts[index]
    let expected = if index + 1 == parts.length { "file" } else { "directory" }
    let mut found = false
    for entry in files.list(parent)? {
      if entry.name != name { continue }
      if entry.kind != expected {
        return Err("CLI input must be a regular file inside the checkout: {path}")
      }
      found = true
    }
    if !found { return Err("CLI input is missing: {path}") }
    parent = "{parent}/{name}"
    index += 1
  }
  Ok(parent)
}

function readInput(root: string, path: string) -> Result<string, string> {
  let text = files.readText(repositoryFile(root, path)?)?
  // The public read API returns a full buffer. This is an admission bound,
  // not a claim that allocation was bounded before the file was read.
  if text.byteLength() > 67108864 { return Err("CLI input exceeds 64 MiB: {path}") }
  Ok(text)
}

function checkCore(root: string) -> Result<(), string> {
  let manifest = json.parseAs<CoreManifest>(readInput(root, "compiler/generated/native/compiler.json")?)?
  if manifest.schema != "topaz.native-compiler/v1" || manifest.sourceSetId != COMPILER_SOURCE_SET {
    return Err("kit build requires the canonical compiler identified by this Kit")
  }
  let path = repositoryFile(root, "compiler/generated/native/compiler.rs")?
  let bytes = files.readBytes(path)?
  if "sha256:{bytes.sha256().toHex()}" != manifest.generatedRustSha256 {
    return Err("canonical generated compiler differs from its manifest")
  }
  Ok(())
}

export function prepare(repositoryRoot: string) -> Result<string, string> {
  checkCore(repositoryRoot)?
  let descriptor = json.parseAs<Descriptor>(readInput(repositoryRoot, "core-kit/cli/REQUEST.json")?)?
  if descriptor.schema != "topaz.note.core-kit-cli-request/v2" ||
    descriptor.compilerSourceSetId != COMPILER_SOURCE_SET {
    return Err("CLI descriptor does not identify this canonical compiler")
  }
  let initial = fromFile(repositoryFile(repositoryRoot, descriptor.requestFile)?)?
  if initial.producer != "topaz-stage1" || initial.terminal != "rust-source" {
    return Err("CLI bootstrap input must be a Stage 1 rust-source request")
  }
  if descriptor.sourceFiles.length == 0 || descriptor.sourceFiles.length > initial.maxSourceFacts {
    return Err("CLI source mapping must be nonempty and fit its declared source budget")
  }

  let mut sources: Map<string, string> = map {}
  let mut mappedBytes = 0
  for mapping in descriptor.sourceFiles {
    relativePath(mapping.logicalPath)?
    if sources.containsKey(mapping.logicalPath) {
      return Err("duplicate CLI source mapping: {mapping.logicalPath}")
    }
    let source = readInput(repositoryRoot, mapping.path)?
    mappedBytes += source.byteLength()
    if mappedBytes > initial.maxTotalSourceBytes || mappedBytes > 67108864 {
      return Err("current CLI source bytes exceed the request budget")
    }
    sources.insert(mapping.logicalPath, source)
  }
  if !sources.containsKey(initial.entry) { return Err("CLI entry has no explicit source mapping") }

  let mut used: Set<string> = set {}
  let mut facts: Array<HostFact> = []
  let mut sourceCount = 0
  let mut sourceBytes = 0
  for fact in initial.facts {
    if fact.kind != "read-source" {
      facts.push(fact)
      continue
    }
    if fact.mountId != "root" || fact.status != "present" {
      return Err("initial CLI read-source facts must be present in the root mount")
    }
    if !sources.containsKey(fact.logicalPath) || used.contains(fact.logicalPath) {
      return Err("CLI read-source facts and source mappings must correspond exactly")
    }
    used.add(fact.logicalPath)
    sourceCount += 1
    let source = sources.getOr(fact.logicalPath, "")
    sourceBytes += source.byteLength()
    if sourceBytes > initial.maxTotalSourceBytes || sourceBytes > 67108864 {
      return Err("current CLI source bytes exceed the request budget")
    }
    facts.push(HostFact { ...fact, source: source })
  }
  if sourceCount != descriptor.sourceFiles.length {
    return Err("CLI source mapping contains a file with no read-source fact")
  }

  if descriptor.standardModules.length > 1024 { return Err("too many CLI standard module mappings") }
  let mut standards: Map<string, StandardModule> = map {}
  let mut standardPaths: Set<string> = set {}
  for mapping in descriptor.standardModules {
    relativePath(mapping.path)?
    if !mapping.identity.startsWith("std.") || mapping.identity == "std.lispex" {
      return Err("unsupported CLI standard module: {mapping.identity}")
    }
    if standards.containsKey(mapping.identity) || standardPaths.contains(mapping.path) {
      return Err("duplicate CLI standard module identity or path")
    }
    let source = readInput(repositoryRoot, mapping.sourceFile)?
    mappedBytes += source.byteLength()
    if mappedBytes > initial.maxTotalSourceBytes || mappedBytes > 67108864 {
      return Err("current CLI and standard module bytes exceed the request budget")
    }
    standards.insert(mapping.identity, StandardModule {
      identity: mapping.identity, path: mapping.path, source: source,
    })
    standardPaths.add(mapping.path)
  }
  let mut modules: Array<StandardModule> = []
  let mut identities: Set<string> = set {}
  for module in initial.package.generatedStdModules {
    if !standards.containsKey(module.identity) || identities.contains(module.identity) {
      return Err("CLI standard module mappings and initial modules must correspond exactly")
    }
    let mapped = standards.getOr(module.identity, module)
    if mapped.path != module.path { return Err("CLI standard module path differs: {module.identity}") }
    identities.add(module.identity)
    sourceBytes += mapped.source.byteLength()
    if sourceBytes > initial.maxTotalSourceBytes || sourceBytes > 67108864 {
      return Err("current CLI and standard module bytes exceed the request budget")
    }
    modules.push(mapped)
  }
  if modules.length != descriptor.standardModules.length {
    return Err("CLI standard mapping contains an unused module")
  }
  let request = CompilerRequest {
    ...initial,
    facts: facts,
    package: PackageFacts { ...initial.package, generatedStdModules: modules },
  }
  json.stringify(request)
}

