import std.fs as files
import std.io as io
import std.json as json
import src.contracts { Capture, Native, Process }
import src.project_manifest { ProjectConfig, validateConfiguration }
import src.toolchain { checkToolchain }

const MARKER = "topaz-core-kit.native-build/v1\n"

function prepareOutput(output: string) -> Result<(), string> {
  let entries = files.list(output)?
  if entries.length == 0 { return Ok(()) }
  let mut managed = false
  for entry in entries {
    if entry.kind == "symlink" {
      return Err("build output must not contain symlinks: {entry.name}")
    }
    if entry.name == ".topaz-core-kit-build" { managed = true }
  }
  if !managed || files.readText("{output}/.topaz-core-kit-build")? != MARKER {
    return Err("--out-dir must be empty or contain a previous Core Kit build; refusing to overwrite another project")
  }
  Ok(())
}

function cargoManifest(repositoryRoot: string) -> Result<string, string> {
  // JSON string escaping is valid for these TOML basic string path values.
  let runtime = json.stringify("{repositoryRoot}/compiler/crates/topaz_rt")?
  let host = json.stringify("{repositoryRoot}/compiler/crates/topaz_host_native")?
  let product = json.stringify("{repositoryRoot}/compiler/crates/topaz_product_runtime")?
  Ok("[package]\nname = \"topaz-core-kit-program\"\nversion = \"0.1.0\"\nedition = \"2024\"\nrust-version = \"1.96.0\"\npublish = false\n\n[workspace]\n\n[profile.release]\ncodegen-units = 1\n\n[[bin]]\nname = \"topaz-core-kit-program\"\npath = \"main.rs\"\n\n[dependencies]\ntopaz_rt = \{ path = {runtime} \}\ntopaz_host_native = \{ path = {host} \}\ntopaz_product_runtime = \{ path = {product} \}\n")
}

function rustRoots(roots: Array<string>) -> Result<string, string> {
  let mut values: Array<string> = []
  for root in roots {
    // Portable manifest paths contain no control characters. JSON quoting for
    // the remaining quote/backslash characters is also valid Rust quoting.
    values.push("String::from({json.stringify(root)?})")
  }
  Ok(values.join(", "))
}

function capabilitySource(configuration: Option<ProjectConfig>, repositoryRoot: string) -> Result<string, string> {
  match configuration {
    case None => files.readText("{repositoryRoot}/core-kit/cli/templates/capabilities.rs")
    case Some(project) => {
      validateConfiguration(project)?
      let reads = rustRoots(project.readRoots)?
      let writes = rustRoots(project.writeRoots)?
      // Grant roots are relative to the application's launch directory. No
      // build-machine path is embedded in the generated native executable.
      Ok("pub fn host() -> Result<topaz_host_native::NativeHost, String> \{\n    let root = std::env::current_dir().map_err(|e| format!(\"cannot resolve application working directory: \{e\}\"))?;\n    Ok(topaz_host_native::NativeHost::with_fs_capabilities(root, &[{reads}], &[{writes}]))\n\}\n")
    }
  }
}

export function build(
  generated: string,
  output: string,
  repositoryRoot: string,
  process: Process,
  native: Native,
  capture: Capture,
  configuration: Option<ProjectConfig>,
) -> Result<int, string> {
  let target = checkToolchain(repositoryRoot, native, capture)?
  native("mkdir", [output])?
  prepareOutput(output)?
  let manifest = cargoManifest(repositoryRoot)?
  let runner = files.readText("{repositoryRoot}/core-kit/cli/templates/program.rs")?
  let lock = files.readText("{repositoryRoot}/core-kit/cli/templates/program.lock")?
  let capabilities = capabilitySource(configuration, repositoryRoot)?
  files.writeText("{output}/.topaz-core-kit-build", MARKER)?
  files.writeText("{output}/generated.rs", generated)?
  files.writeText("{output}/main.rs", runner)?
  files.writeText("{output}/capabilities.rs", capabilities)?
  files.writeText("{output}/Cargo.toml", manifest)?
  files.writeText("{output}/Cargo.lock", lock)?
  io.writeLine("building native program in {output}")
  let code = process(
    "cargo",
    ["build", "--manifest-path", "Cargo.toml", "--release", "--frozen", "--message-format=short", "--target", target.target, "--target-dir", "target"],
    output,
    ["RUSTUP_TOOLCHAIN=1.96.0", "RUSTUP_AUTO_INSTALL=0", "CARGO_NET_OFFLINE=true"],
  )?
  if code != 0 { return Ok(code) }
  io.writeLine("native program built at {output}/target/{target.target}/release/topaz-core-kit-program{target.executableSuffix}")
  Ok(0)
}

import std.fs as files
import std.io as io
import std.json as json
import src.contracts { COMPILER_SOURCE_SET }
import src.payload_files { MANIFEST_NAME, PayloadFile, compareRecords, payloadFiles, repositoryFiles }
import src.verification { validateRecordedInputs }

const SCHEMA = "topaz.core-kit-payload/v1"
const EVIDENCE = "recorded-inputs-only"

record PayloadManifest derives JSON {
  schema: string,
  evidence: string,
  compilerSourceSetId: string,
  target: string,
  executable: string,
  files: Array<PayloadFile>,
  repositoryInputs: Array<PayloadFile>,
}

export function executableFor(target: string) -> Result<string, string> {
  if target == "x86_64-pc-windows-msvc" || target == "aarch64-pc-windows-msvc" {
    return Ok("topaz-core-kit.exe")
  }
  if target == "x86_64-unknown-linux-gnu" || target == "aarch64-unknown-linux-gnu" ||
    target == "x86_64-apple-darwin" || target == "aarch64-apple-darwin" {
    return Ok("topaz-core-kit")
  }
  Err("target is not mapped by the repository launchers: {target}")
}

function collect(repositoryRoot: string, directory: string, target: string, recorded: bool) -> Result<PayloadManifest, string> {
  let executable = executableFor(target)?
  let contents = payloadFiles(directory, executable, recorded)?
  let inputs = repositoryFiles(repositoryRoot)?
  validateRecordedInputs(repositoryRoot)?
  Ok(PayloadManifest {
    schema: SCHEMA, evidence: EVIDENCE, compilerSourceSetId: COMPILER_SOURCE_SET,
    target: target, executable: executable, files: contents, repositoryInputs: inputs,
  })
}

function encoded(manifest: PayloadManifest) -> Result<string, string> {
  Ok("{json.stringify(manifest)?}\n")
}

export function recordPayload(repositoryRoot: string, directory: string, target: string) -> Result<int, string> {
  // Never execute, copy or rebuild the candidate being recorded. In
  // particular, its filename and --target are not an ABI compatibility test.
  let manifest = collect(repositoryRoot, directory, target, false)?
  let text = encoded(manifest)?
  if text.byteLength() > 1048576 { return Err("payload manifest exceeds 1 MiB") }
  files.writeText("{directory}/{MANIFEST_NAME}", text)?
  io.writeLine("payload byte inventory written: {directory}/{MANIFEST_NAME}")
  io.writeLine("Recorded {manifest.files.length} payload files and {manifest.repositoryInputs.length} repository inputs.")
  io.writeLine("This records bytes only; it does not certify build provenance, licensing, platform support or reproducibility.")
  Ok(0)
}

export function verifyPayload(repositoryRoot: string, directory: string) -> Result<int, string> {
  // Inspect the manifest entry before reading; a symlink must not be treated
  // as a harmless excluded filename. Other paths are collected independently
  // of manifest declarations before any recorded hashes are trusted.
  let mut present = false
  for entry in files.list(directory)? {
    if entry.name == MANIFEST_NAME {
      if entry.kind != "file" { return Err("payload.json must be a regular file") }
      present = true
    }
  }
  if !present { return Err("payload.json is missing") }
  let text = files.readText("{directory}/{MANIFEST_NAME}")?
  if text.byteLength() == 0 || text.byteLength() > 1048576 {
    return Err("payload manifest must be nonempty and no larger than 1 MiB")
  }
  let manifest = json.parseAs<PayloadManifest>(text)?
  if manifest.schema != SCHEMA || manifest.evidence != EVIDENCE {
    return Err("unsupported payload schema or evidence claim")
  }
  if manifest.compilerSourceSetId != COMPILER_SOURCE_SET {
    return Err("payload manifest targets a different canonical compiler")
  }
  if manifest.executable != executableFor(manifest.target)? {
    return Err("payload executable does not match its target filename")
  }
  if manifest.files.length == 0 || manifest.files.length > 256 ||
    manifest.repositoryInputs.length == 0 || manifest.repositoryInputs.length > 1024 {
    return Err("payload manifest has an invalid file count")
  }
  // Typed JSON decoding projects known fields. Requiring the writer's exact
  // representation also rejects duplicate/extra fields and ambiguous edits.
  if text != encoded(manifest)? {
    return Err("payload.json must use the exact canonical representation written by payload-record")
  }
  let actual = collect(repositoryRoot, directory, manifest.target, true)?
  compareRecords(manifest.files, actual.files, "payload")?
  compareRecords(manifest.repositoryInputs, actual.repositoryInputs, "repository input")?
  io.writeLine("Payload inventory matches: {actual.files.length} payload files and {actual.repositoryInputs.length} repository inputs.")
  io.writeLine("This checks recorded bytes only; it does not certify build provenance, licensing, platform support or reproducibility.")
  Ok(0)
}

import std.bytes { Bytes }
import std.fs as files

export const INPUT_LIST = "core-kit/payload-inputs.data"
export const MANIFEST_NAME = "payload.json"

export record PayloadFile derives JSON {
  path: string,
  bytes: int,
  sha256: string,
}

// Payload names are a deliberately portable subset, including on Windows.
// Return an ASCII case-folded spelling so aliases cannot hide extra files.
function portableName(name: string) -> Result<string, string> {
  if name == "" || name == "." || name == ".." || name.byteLength() > 128 || name.endsWith(".") {
    return Err("invalid portable payload/input name: {name}")
  }
  let mut folded: Array<int> = []
  for byte in name.encodeUtf8().toArray() {
    let letter = (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122)
    let digit = byte >= 48 && byte <= 57
    if !letter && !digit && byte != 95 && byte != 46 && byte != 45 {
      return Err("invalid portable payload/input name: {name}")
    }
    folded.push(if byte >= 65 && byte <= 90 { byte + 32 } else { byte })
  }
  let foldedBytes = Bytes.fromArray(folded)?
  let lower = foldedBytes.decodeUtf8()?
  let base = lower.split(".")[0]
  if base == "con" || base == "prn" || base == "aux" || base == "nul" {
    return Err("reserved Windows payload/input name: {name}")
  }
  if base.byteLength() == 4 && (base.startsWith("com") || base.startsWith("lpt")) {
    let last = base.encodeUtf8().toArray()[3]
    if last >= 49 && last <= 57 { return Err("reserved Windows payload/input name: {name}") }
  }
  Ok(lower)
}

export function portablePath(path: string) -> Result<string, string> {
  if path == "" || path.byteLength() > 1024 {
    return Err("invalid payload repository input path")
  }
  let mut folded: Array<string> = []
  for segment in path.split("/") { folded.push(portableName(segment)?) }
  Ok(folded.join("/"))
}

// Inventory paths are relative to this already selected checkout. Inspect
// each component rather than following a listed symlink into another tree.
export function requireRegularInput(root: string, path: string) -> Result<(), string> {
  let parts = path.split("/")
  let mut parent = root
  let mut index = 0
  while index < parts.length {
    let name = parts[index]
    let required = if index + 1 == parts.length { "file" } else { "directory" }
    let mut found = false
    for entry in files.list(parent)? {
      if entry.name != name { continue }
      if entry.kind != required {
        return Err("repository input must use regular files/directories, without symlinks: {path}")
      }
      found = true
    }
    if !found { return Err("repository input is missing: {path}") }
    parent = "{parent}/{name}"
    index += 1
  }
  Ok(())
}

function describe(root: string, path: string) -> Result<PayloadFile, string> {
  let bytes = files.readBytes("{root}/{path}")?
  // The public API returns a complete byte buffer; this bound is checked
  // after reading and is not a streaming allocation limit.
  if bytes.length() > 536870912 { return Err("payload/input file exceeds 512 MiB: {path}") }
  Ok(PayloadFile { path: path, bytes: bytes.length(), sha256: bytes.sha256().toHex() })
}

export function requiredInputs(paths: Set<string>) -> Result<(), string> {
  // Final archive hashes are recorded only after the payload exists. Binding
  // that catalogue into payload.json would make the archive depend on itself.
  for path in paths {
    if portablePath(path)? == "core-kit/downloads.data" {
      return Err("download catalogue is transport metadata and must not be a payload repository input")
    }
  }
  for path in [
    INPUT_LIST, "core-kit/verify-core.data", "SOURCE-COMPONENTS.json",
    "compiler/Cargo.toml", "compiler/Cargo.lock", "compiler/rust-toolchain.toml",
    "compiler/generated/native/compiler.rs", "compiler/generated/native/compiler.json",
    "compiler/seed/initial/request.json", "compiler/seed/initial/REQUEST-PROVENANCE.json",
    "compiler/seed/runtime.json", "core-kit/cli/data/input.txt",
    "compiler/seed/initial/std/bytes.tpz", "compiler/seed/initial/std/fs.tpz",
    "compiler/seed/initial/std/io.tpz", "compiler/seed/initial/std/json.tpz",
    "core-kit/cli/REQUEST.json", "core-kit/cli/initial/request.json",
    "core-kit/cli/src/main.tpz", "core-kit/cli/src/arguments.tpz",
    "core-kit/cli/src/commands.tpz", "core-kit/cli/src/payload.tpz",
    "core-kit/cli/src/payload_files.tpz", "core-kit/cli/templates/program.rs",
    "core-kit/cli/templates/program.lock", "compiler/core-kit-native/Cargo.toml",
    "core-kit/native/build.rs", "core-kit/native/src/lib.rs", "core-kit/native/src/main.rs",
    "core-kit/native/src/bin/generate-cli.rs", "LICENSE", "NOTICE", "LICENSE-COMPONENTS.txt",
    "topaz", "topaz.cmd", "bootstrap", "bootstrap.cmd",
    "install-core-kit", "install-core-kit.cmd", "core-kit/install.ps1",
    "core-kit/downloads.sh", "core-kit/downloads.ps1", "core-kit/launch.ps1",
  ] {
    if !paths.contains(path) { return Err("required payload repository input is omitted: {path}") }
  }
  Ok(())
}

export function repositoryFiles(root: string) -> Result<Array<PayloadFile>, string> {
  requireRegularInput(root, INPUT_LIST)?
  let text = files.readText("{root}/{INPUT_LIST}")?
  if text.byteLength() == 0 || text.byteLength() > 1048576 {
    return Err("payload repository input list must be nonempty and no larger than 1 MiB")
  }
  let lines = text.split("\n")
  if lines[0] != "topaz.core-kit-payload-inputs/v1" {
    return Err("unsupported payload repository input list format")
  }
  let mut paths: Array<string> = []
  let mut seen: Set<string> = set {}
  let mut exact: Set<string> = set {}
  let mut index = 1
  while index < lines.length {
    let path = lines[index]
    if path == "" && index + 1 == lines.length { break }
    let folded = portablePath(path)?
    if seen.contains(folded) { return Err("duplicate/case-aliased payload repository input: {path}") }
    seen.add(folded)
    exact.add(path)
    paths.push(path)
    if paths.length > 1024 { return Err("payload repository input list exceeds 1024 files") }
    index += 1
  }
  if paths.length == 0 { return Err("payload repository input list is empty") }
  paths.sort()
  if text != "topaz.core-kit-payload-inputs/v1\n{paths.join("\n")}\n" {
    return Err("payload repository input list must be sorted, with one path per line and a final LF")
  }
  requiredInputs(exact)?
  let mut records: Array<PayloadFile> = []
  for path in paths {
    requireRegularInput(root, path)?
    records.push(describe(root, path)?)
  }
  Ok(records)
}

export function payloadFiles(directory: string, executable: string, recorded: bool) -> Result<Array<PayloadFile>, string> {
  let mut paths: Array<string> = []
  let mut seen: Set<string> = set {}
  let mut hasExecutable = false
  let mut hasManifest = false
  for entry in files.list(directory)? {
    let folded = portableName(entry.name)?
    if seen.contains(folded) { return Err("duplicate/case-aliased payload filename: {entry.name}") }
    seen.add(folded)
    if entry.kind != "file" { return Err("payload directory must contain only regular files: {entry.name}") }
    if folded == MANIFEST_NAME {
      if entry.name != MANIFEST_NAME { return Err("payload manifest must be named exactly payload.json") }
      if !recorded { return Err("payload.json already exists; refusing to replace recorded evidence") }
      hasManifest = true
      continue
    }
    if entry.name == executable { hasExecutable = true }
    paths.push(entry.name)
    if paths.length > 256 { return Err("payload directory exceeds 256 recorded files") }
  }
  if recorded && !hasManifest { return Err("payload.json is missing") }
  if !hasExecutable { return Err("payload executable is missing: {executable}") }
  paths.sort()
  let mut records: Array<PayloadFile> = []
  for path in paths {
    let record = describe(directory, path)?
    if path == executable && record.bytes == 0 { return Err("payload executable is empty") }
    records.push(record)
  }
  Ok(records)
}

function validDigest(text: string) -> bool {
  if text.byteLength() != 64 { return false }
  for byte in text.encodeUtf8().toArray() {
    if !((byte >= 48 && byte <= 57) || (byte >= 97 && byte <= 102)) { return false }
  }
  true
}

export function compareRecords(expected: Array<PayloadFile>, actual: Array<PayloadFile>, label: string) -> Result<(), string> {
  if expected.length != actual.length { return Err("{label} file count differs from payload.json") }
  let mut index = 0
  while index < actual.length {
    let before = expected[index]
    let now = actual[index]
    if before.path != now.path { return Err("{label} file list differs from payload.json at {now.path}") }
    if before.bytes < 0 || before.bytes > 536870912 || !validDigest(before.sha256) {
      return Err("invalid recorded size or SHA-256 for {label}: {before.path}")
    }
    if before.bytes != now.bytes || before.sha256 != now.sha256 {
      return Err("{label} bytes differ from payload.json: {now.path}")
    }
    index += 1
  }
  Ok(())
}

import std.fs as files
import std.json as json
import src.contracts {
  COMPILER_SOURCE_SET, EXCHANGE_SCHEMA, CompilerRequest, HostFact, PackageFacts, Provider,
}
import src.project_manifest { ProjectConfig, parseManifest, validateConfiguration }
import src.project_sources { Inspect, SourceState, inspectPath, orderedFacts, provide }
import src.requests { standardModules }

export record Project {
  request: CompilerRequest,
  provide: Provider,
  facts: Array<HostFact>,
  configuration: ProjectConfig,
  root: string,
}

export function prepare(rootPath: string, repositoryRoot: string, inspect: Inspect) -> Result<Project, string> {
  let location = inspectPath(rootPath, "", inspect)?
  if location.status != "present" || location.kind != "directory" {
    return Err("--root must identify an existing project directory")
  }
  let manifest = inspectPath(location.path, "topaz.toml", inspect)?
  if manifest.status != "present" || manifest.kind != "file" {
    return Err("project topaz.toml must be a readable file inside the project root")
  }
  let configuration = parseManifest(files.readText(manifest.path)?)?
  let modules = standardModules(repositoryRoot)?
  let mut moduleBytes = 0
  for module in modules { moduleBytes += module.source.byteLength() }
  if moduleBytes > 16777216 { return Err("bundled standard modules exceed 16 MiB") }
  let facts: Array<HostFact> = []
  let state = SourceState {
    root: location.path,
    inspect: inspect,
    facts: facts,
    indexes: map {},
    totals: [0, moduleBytes],
  }
  let request = CompilerRequest {
    schema: EXCHANGE_SCHEMA,
    producer: "topaz-stage1",
    compilerSourceSetId: COMPILER_SOURCE_SET,
    terminal: "typed",
    entry: configuration.entry, root: "", source: "", sourceId: configuration.entry,
    languageMode: "topaz-5.21", profile: "",
    facts: [],
    package: PackageFacts {
      buildRole: "standalone",
      externModules: [], externReplayModules: [], externReplayErrors: [],
      generatedStdModules: modules,
    },
    maxSourceFacts: 4096,
    maxTotalSourceBytes: 16777216,
    maxAstNodes: 1000000,
    maxAstDepth: 512,
    maxRawTokens: 2000000,
    maxLayoutTokens: 2000000,
    maxHirNodes: 1000000,
    maxLoweredNodes: 2000000,
    maxDiagnostics: 10000,
    maxGeneratedRustBytes: 134217728,
    maxFactRounds: 16384,
  }
  Ok(Project {
    request: request,
    provide: (query: string) => provide(query, state),
    facts: facts,
    configuration: configuration,
    root: location.path,
  })
}

// Call the compiler with project.provide before saving. The core discovers
// imports and requests facts, so no CLI-specific import parser is needed.
export function snapshot(project: Project) -> Result<CompilerRequest, string> {
  Ok(CompilerRequest { ...project.request, facts: orderedFacts(project.facts)? })
}

export const PROJECT_REQUEST_SCHEMA = "topaz.core-kit.project-request/v1"

export record ProjectSnapshot derives JSON {
  schema: string,
  request: CompilerRequest,
  configuration: ProjectConfig,
}

export function encodeSnapshot(project: Project) -> Result<string, string> {
  json.stringify(ProjectSnapshot {
    schema: PROJECT_REQUEST_SCHEMA,
    request: snapshot(project)?,
    configuration: project.configuration,
  })
}

export function decodeSnapshot(text: string) -> Result<ProjectSnapshot, string> {
  if text.byteLength() > 134217728 { return Err("project request exceeds 128 MiB") }
  let saved = json.parseAs<ProjectSnapshot>(text)?
  if saved.schema != PROJECT_REQUEST_SCHEMA { return Err("unsupported project request schema") }
  validateConfiguration(saved.configuration)?
  if saved.request.root != "" || saved.request.entry != saved.configuration.entry {
    return Err("project request entry does not match its saved configuration")
  }
  Ok(saved)
}

import std.json { JSONValue }
import std.toml as toml

export record ProjectConfig derives JSON {
  name: string,
  entry: string,
  readRoots: Array<string>,
  writeRoots: Array<string>,
}

function objectKeys(value: JSONValue, label: string) -> Result<Array<string>, string> {
  match value.keys() {
    case Some(keys) => Ok(keys)
    case None => Err("{label} must be a TOML table")
  }
}

function knownKeys(value: JSONValue, allowed: Array<string>, label: string) -> Result<(), string> {
  for key in objectKeys(value, label)? {
    let mut found = false
    for name in allowed { if key == name { found = true } }
    if !found { return Err("unsupported {label} field `{key}`") }
  }
  Ok(())
}

function required(value: JSONValue, key: string, label: string) -> Result<JSONValue, string> {
  match value.get(key) {
    case Some(found) => Ok(found)
    case None => Err("{label} requires `{key}`")
  }
}

function stringValue(value: JSONValue, label: string) -> Result<string, string> {
  match value.asString() {
    case Some(text) => if text == "" { Err("{label} must not be empty") } else { Ok(text) }
    case None => Err("{label} must be a string")
  }
}

// Manifest paths name portable logical locations. Physical containment is
// checked separately against the caller-selected project root.
export function relativePath(path: string, allowRoot: bool) -> Result<string, string> {
  if allowRoot && path == "." { return Ok(path) }
  if path == "" || path.byteLength() > 4096 || path.contains("\\") || path.contains(":") {
    return Err("project paths must be nonempty relative paths using forward slashes: {path}")
  }
  let parts = path.split("/")
  if parts.length > 128 { return Err("project path has too many segments") }
  for part in parts {
    if part == "" || part == "." || part == ".." {
      return Err("project paths must not contain empty, dot or parent segments: {path}")
    }
    for byte in part.encodeUtf8().toArray() {
      if byte < 32 || byte == 127 { return Err("project paths must not contain control characters") }
    }
  }
  Ok(path)
}

function capabilityRoots(table: JSONValue, key: string) -> Result<Array<string>, string> {
  let value = match table.get(key) {
    case Some(found) => found
    case None => return Ok([])
  }
  let values = match value.asArray() {
    case Some(found) => found
    case None => return Err("capabilities.fs.{key} must be an array of relative paths")
  }
  if values.length > 256 { return Err("capabilities.fs.{key} exceeds 256 roots") }
  let mut output: Array<string> = []
  let mut seen: Set<string> = set {}
  for value in values {
    let path = relativePath(stringValue(value, "capabilities.fs.{key}")?, true)?
    if seen.contains(path) { return Err("duplicate capabilities.fs.{key} path `{path}`") }
    seen.add(path)
    output.push(path)
  }
  output.sort()
  Ok(output)
}

export function parseManifest(source: string) -> Result<ProjectConfig, string> {
  if source.byteLength() > 1048576 { return Err("topaz.toml exceeds 1 MiB") }
  let document = toml.parse(source)?
  let root = document.toJson()
  knownKeys(root, ["package", "build", "dependencies", "capabilities"], "topaz.toml")?
  let package = required(root, "package", "topaz.toml")?
  knownKeys(package, ["name", "version", "language", "entry"], "package")?
  let name = stringValue(required(package, "name", "package")?, "package.name")?
  stringValue(required(package, "version", "package")?, "package.version")?
  let language = stringValue(required(package, "language", "package")?, "package.language")?
  if language != "5.21" { return Err("Core Kit requires package.language = \"5.21\"") }
  let entry = relativePath(stringValue(required(package, "entry", "package")?, "package.entry")?, false)?
  if !entry.endsWith(".tpz") { return Err("package.entry must name a .tpz source file") }

  match root.get("build") {
    case Some(build) => {
      knownKeys(build, ["target", "deterministic"], "build")?
      match build.get("target") {
        case Some(value) => if stringValue(value, "build.target")? != "native" {
          return Err("Core Kit project builds require build.target = \"native\"")
        }
        case None => ()
      }
      match build.get("deterministic") {
        case Some(value) => match value.asBool() {
          case Some(true) => ()
          case _ => return Err("Core Kit requires build.deterministic = true when specified")
        }
        case None => ()
      }
    }
    case None => ()
  }

  match root.get("dependencies") {
    case Some(dependencies) => {
      for dependency in objectKeys(dependencies, "dependencies")? {
        if dependency != "std" {
          return Err("dependency `{dependency}` requires a package resolver; Core Kit project mode accepts local modules and the bundled std dependency")
        }
        let version = stringValue(required(dependencies, dependency, "dependencies")?, "dependencies.std")?
        if version != "5.21" { return Err("Core Kit requires dependencies.std = \"5.21\"") }
      }
    }
    case None => ()
  }

  let mut readRoots: Array<string> = []
  let mut writeRoots: Array<string> = []
  match root.get("capabilities") {
    case Some(capabilities) => {
      knownKeys(capabilities, ["fs"], "capabilities")?
      match capabilities.get("fs") {
        case Some(fs) => {
          knownKeys(fs, ["read", "write"], "capabilities.fs")?
          readRoots = capabilityRoots(fs, "read")?
          writeRoots = capabilityRoots(fs, "write")?
        }
        case None => ()
      }
    }
    case None => ()
  }
  let configuration = ProjectConfig { name: name, entry: entry, readRoots: readRoots, writeRoots: writeRoots }
  validateConfiguration(configuration)?
  Ok(configuration)
}

// A saved project request carries these grants independently of a manifest
// on disk. Validate them again when that portable snapshot is replayed.
export function validateConfiguration(configuration: ProjectConfig) -> Result<(), string> {
  if configuration.name == "" || configuration.name.byteLength() > 256 {
    return Err("project package name must contain 1..256 bytes")
  }
  relativePath(configuration.entry, false)?
  if !configuration.entry.endsWith(".tpz") { return Err("project entry must name a .tpz source file") }
  for roots in [configuration.readRoots, configuration.writeRoots] {
    if roots.length > 256 { return Err("project filesystem grants exceed 256 roots") }
    let mut seen: Set<string> = set {}
    for root in roots {
      relativePath(root, true)?
      if seen.contains(root) { return Err("duplicate project filesystem grant `{root}`") }
      seen.add(root)
    }
  }
  Ok(())
}

import std.fs as files
import std.json as json
import src.contracts { DirectoryEntry, HostFact }
import src.project_manifest { relativePath }

export type Inspect = (string, string) -> Result<string, string>

record HostQuery derives JSON {
  kind: string,
  mountId: string,
  logicalPath: string,
}

export record Inspection derives JSON {
  status: string,
  path: string,
  kind: string,
  alias: string,
  reason: string,
}

export record SourceState {
  root: string,
  inspect: Inspect,
  facts: Array<HostFact>,
  indexes: Map<string, int>,
  totals: Array<int>,
}

export function inspectPath(root: string, path: string, inspect: Inspect) -> Result<Inspection, string> {
  if path != "" { relativePath(path, false)? }
  let info = json.parseAs<Inspection>(inspect(root, path)?)?
  if info.status != "present" && info.status != "missing" && info.status != "outside" && info.status != "unreadable" {
    return Err("native path inspection returned an invalid status")
  }
  if info.status == "present" && (info.path == "" || (info.kind != "file" && info.kind != "directory" && info.kind != "other")) {
    return Err("native path inspection returned incomplete metadata")
  }
  Ok(info)
}

function baseFact(query: HostQuery, status: string) -> HostFact {
  HostFact {
    kind: query.kind, mountId: query.mountId, logicalPath: query.logicalPath,
    status: status, source: "", entries: [], aliasClass: "", reasonCode: "",
  }
}

function containment(query: HostQuery, info: Inspection) -> HostFact {
  let fact = baseFact(query, if info.status == "present" { "inside" } else { info.status })
  HostFact { ...fact, aliasClass: if info.status == "present" { info.alias } else { "" }, reasonCode: info.reason }
}

function source(query: HostQuery, info: Inspection) -> HostFact {
  if info.status == "missing" || (info.status == "present" && info.kind != "file") {
    return baseFact(query, "missing")
  }
  if info.status != "present" {
    return HostFact { ...baseFact(query, "unreadable"), reasonCode: if info.status == "outside" { "source resolves outside the project root" } else { info.reason } }
  }
  let bytes = match files.readBytes(info.path) {
    case Ok(value) => value
    case Err(message) => return HostFact { ...baseFact(query, "unreadable"), reasonCode: message }
  }
  if bytes.length() > 16777216 {
    return HostFact { ...baseFact(query, "unreadable"), reasonCode: "source exceeds 16 MiB" }
  }
  match bytes.decodeUtf8() {
    case Ok(text) => HostFact { ...baseFact(query, "present"), source: text }
    case Err(_) => baseFact(query, "invalid-utf8")
  }
}

function listing(query: HostQuery, info: Inspection, state: SourceState) -> Result<HostFact, string> {
  if info.status == "missing" || (info.status == "present" && info.kind != "directory") {
    return Ok(baseFact(query, "missing"))
  }
  if info.status != "present" {
    return Ok(HostFact { ...baseFact(query, "unreadable"), reasonCode: if info.status == "outside" { "directory resolves outside the project root" } else { info.reason } })
  }
  let children = match files.list(info.path) {
    case Ok(value) => value
    case Err(message) => return Ok(HostFact { ...baseFact(query, "unreadable"), reasonCode: message })
  }
  if children.length > 65536 { return Err("project directory exceeds 65536 entries") }
  let mut names: Array<string> = []
  let mut kinds: Map<string, string> = map {}
  for child in children {
    // A directory fact preserves every spelling so the canonical resolver,
    // not the CLI, decides case and Unicode-normalization collisions.
    if child.name == "" || child.name.contains("/") || child.name.contains("\\") || child.name.contains("\n") {
      return Err("project directory contains an unrepresentable entry name")
    }
    if kinds.containsKey(child.name) { return Err("project directory returned a duplicate entry name") }
    let mut kind = child.kind
    if kind == "symlink" {
      let path = if query.logicalPath == "" { child.name } else { "{query.logicalPath}/{child.name}" }
      let target = inspectPath(state.root, path, state.inspect)?
      kind = if target.status == "present" { target.kind } else { "other" }
    }
    names.push(child.name)
    kinds.insert(child.name, kind)
  }
  names.sort()
  let mut entries: Array<DirectoryEntry> = []
  for name in names {
    let kind = match kinds.get(name) {
      case Some(value) => value
      case None => "other"
    }
    entries.push(DirectoryEntry { name: name, kind: kind })
  }
  Ok(HostFact { ...baseFact(query, "present"), entries: entries })
}

export function provide(queryText: string, state: SourceState) -> Result<string, string> {
  let query = json.parseAs<HostQuery>(queryText)?
  if query.mountId != "root" { return Err("project queries must use the root mount") }
  if query.kind != "physical-containment" && query.kind != "read-source" && query.kind != "list-directory" {
    return Err("unsupported project source query `{query.kind}`")
  }
  if query.logicalPath != "" { relativePath(query.logicalPath, false)? }
  if query.logicalPath == "" && query.kind != "list-directory" {
    return Err("source and containment queries require a file path")
  }
  let key = "{query.kind}\n{query.logicalPath}"
  match state.indexes.get(key) {
    case Some(index) => return json.stringify(state.facts[index])
    case None => ()
  }
  if state.facts.length >= 16384 { return Err("project exceeds 16384 source-query facts") }
  let fact = if query.logicalPath.startsWith("std/") {
    // Standard modules come from the checkout's explicit module inventory.
    // An unavailable standard import cannot load a project-local replacement.
    baseFact(query, "missing")
  } else {
    let info = inspectPath(state.root, query.logicalPath, state.inspect)?
    if query.kind == "physical-containment" {
      containment(query, info)
    } else if query.kind == "read-source" {
      source(query, info)
    } else {
      listing(query, info, state)?
    }
  }
  let mut current = state
  if fact.kind == "read-source" {
    current.totals[0] += 1
    current.totals[1] += fact.source.byteLength()
    if current.totals[0] > 4096 || current.totals[1] > 16777216 {
      return Err("project sources and standard modules exceed 4096 source facts or 16 MiB")
    }
  }
  current.indexes.insert(key, current.facts.length)
  current.facts.push(fact)
  json.stringify(fact)
}

export function orderedFacts(facts: Array<HostFact>) -> Result<Array<HostFact>, string> {
  let mut keys: Array<string> = []
  let mut indexes: Map<string, int> = map {}
  let mut index = 0
  for fact in facts {
    let key = "{fact.kind}\n{fact.logicalPath}"
    if indexes.containsKey(key) { return Err("duplicate project fact while saving a request") }
    keys.push(key)
    indexes.insert(key, index)
    index += 1
  }
  keys.sort()
  let mut output: Array<HostFact> = []
  for key in keys {
    let position = match indexes.get(key) {
      case Some(value) => value
      case None => return Err("missing project fact while saving a request")
    }
    output.push(facts[position])
  }
  Ok(output)
}

import std.fs as files
import std.io as io
import std.json as json
import src.contracts { COMPILER_SOURCE_SET, Compile, Native }
import src.refresh_inputs { prepareRefresh, validationRequest }
import src.refresh_inventory { RefreshFile, prepareInventories }
import src.responses { completed }
import src.verification { validateRecordedInputs }

const BACKUP_ROOT = "out/core-kit-refresh"
const MARKER = "topaz.core-kit-refresh-backups/v1\n"

record ReceiptFile derives JSON {
  path: string,
  before: string,
  after: string,
  beforeSha256: string,
  afterSha256: string,
}

record Receipt derives JSON {
  schema: string,
  compilerSourceSetId: string,
  state: string,
  files: Array<ReceiptFile>,
}

function closedFacts(query: string) -> Result<string, string> {
  Err("refreshed CLI inputs are incomplete")
}

function changedFiles(plan: Array<RefreshFile>) -> Array<RefreshFile> {
  let mut changed: Array<RefreshFile> = []
  for file in plan { if file.before != file.after { changed.push(file) } }
  changed
}

function samePlan(left: Array<RefreshFile>, right: Array<RefreshFile>) -> bool {
  if left.length != right.length { return false }
  let mut index = 0
  while index < left.length {
    if left[index].path != right[index].path ||
      left[index].before != right[index].before || left[index].after != right[index].after {
      return false
    }
    index += 1
  }
  true
}

function backupRoot(root: string, native: Native) -> Result<string, string> {
  // Refuse links in the fixed backup path before creating a missing suffix.
  let mut current = root
  let mut missing = false
  for part in BACKUP_ROOT.split("/") {
    if !missing {
      let mut found = false
      for entry in files.list(current)? {
        if entry.name == part {
          if entry.kind != "directory" { return Err("refresh backup path must use real directories") }
          found = true
        }
      }
      missing = !found
    }
    current = "{current}/{part}"
  }
  let output = native("mkdir", [current])?
  let entries = files.list(output)?
  if entries.length == 0 {
    files.writeText("{output}/.topaz-core-kit-refresh", MARKER)?
  } else {
    let mut marker = false
    for entry in entries {
      if entry.name == ".topaz-core-kit-refresh" && entry.kind == "file" { marker = true }
    }
    if !marker || files.readText("{output}/.topaz-core-kit-refresh")? != MARKER {
      return Err("refresh backup directory is not owned by Core Kit")
    }
  }
  Ok(output)
}

function newBackup(base: string, native: Native) -> Result<string, string> {
  let mut names: Set<string> = set {}
  for entry in files.list(base)? { names.add(entry.name) }
  let mut sequence = 1
  while names.contains("run-{sequence}") { sequence += 1 }
  if sequence > 10000 { return Err("refresh backup directory has too many retained runs") }
  native("mkdir-new", ["{base}/run-{sequence}"])
}

function writeReceipt(directory: string, receipt: Receipt, state: string) -> Result<(), string> {
  files.writeText("{directory}/refresh.json", "{json.stringify(Receipt { ...receipt, state: state })?}\n")
}

function stage(directory: string, changed: Array<RefreshFile>) -> Result<Receipt, string> {
  let mut records: Array<ReceiptFile> = []
  let mut index = 0
  for file in changed {
    let before = "{index}.before"
    let after = "{index}.after"
    files.writeText("{directory}/{before}", file.before)?
    files.writeText("{directory}/{after}", file.after)?
    records.push(ReceiptFile {
      path: file.path, before: before, after: after,
      beforeSha256: file.before.encodeUtf8().sha256().toHex(),
      afterSha256: file.after.encodeUtf8().sha256().toHex(),
    })
    index += 1
  }
  let receipt = Receipt {
    schema: "topaz.core-kit-refresh/v1", compilerSourceSetId: COMPILER_SOURCE_SET,
    state: "prepared", files: records,
  }
  writeReceipt(directory, receipt, "prepared")?
  Ok(receipt)
}

// Copy-file replaces one file through a private sibling. The group is not a
// crash-atomic filesystem transaction. Backups and the receipt survive an
// interruption, and a failed operation attempts to restore only its own bytes.
function restore(root: string, directory: string, attempted: Array<int>, changed: Array<RefreshFile>, native: Native) -> Result<(), string> {
  let mut failures: Array<string> = []
  let mut index = attempted.length
  while index > 0 {
    index -= 1
    let position = attempted[index]
    let file = changed[position]
    match files.readText("{root}/{file.path}") {
      case Ok(current) => {
        if current == file.before { continue }
        if current != file.after {
          failures.push("{file.path} changed outside this refresh; preserved it")
          continue
        }
        match native("copy-file", ["{directory}/{position}.before", "{root}/{file.path}"]) {
          case Ok(_) => ()
          case Err(error) => failures.push("{file.path}: {error}")
        }
      }
      case Err(error) => failures.push("{file.path}: {error}")
    }
  }
  if failures.length != 0 { return Err(failures.join("\n")) }
  Ok(())
}

record Replacement {
  attempted: Array<int>,
  failure: Option<string>,
}

function replaceFiles(root: string, directory: string, changed: Array<RefreshFile>, native: Native) -> Replacement {
  let mut attempted: Array<int> = []
  let mut index = 0
  for file in changed {
    let current = match files.readText("{root}/{file.path}") {
      case Ok(text) => text
      case Err(error) => return Replacement { attempted: attempted, failure: Some(error) }
    }
    if current != file.before {
      return Replacement { attempted: attempted, failure: Some("metadata changed while refresh was running: {file.path}") }
    }
    attempted.push(index)
    match native("copy-file", ["{directory}/{index}.after", "{root}/{file.path}"]) {
      case Ok(_) => ()
      case Err(error) => return Replacement { attempted: attempted, failure: Some(error) }
    }
    index += 1
  }
  Replacement { attempted: attempted, failure: None }
}

function applyLocked(root: string, base: string, plan: Array<RefreshFile>, changed: Array<RefreshFile>, native: Native) -> Result<int, string> {
  let fresh = prepareInventories(root, prepareRefresh(root)?)?
  if !samePlan(plan, fresh) { return Err("inputs changed while preparing refresh; no metadata was replaced") }
  let directory = newBackup(base, native)?
  let receipt = stage(directory, changed)?
  // The backup exists before any repository file is replaced.
  writeReceipt(directory, receipt, "applying")?
  let replacement = replaceFiles(root, directory, changed, native)
  let applied = match replacement.failure {
    case Some(error) => Err(error)
    case None => validateRecordedInputs(root)
  }
  match applied {
    case Ok(_) => {
      match writeReceipt(directory, receipt, "applied") {
        case Ok(_) => ()
        case Err(error) => return Err("metadata was refreshed but its completion receipt could not be saved: {error}\nBackups remain in {directory}")
      }
      io.writeLine("Refreshed {changed.length} repository metadata files.")
      io.writeLine("Previous bytes and refresh receipt retained in {directory}")
      Ok(0)
    }
    case Err(error) => {
      let restored = restore(root, directory, replacement.attempted, changed, native)
      let state = match restored {
        case Ok(_) => "rolled-back"
        case Err(_) => "recovery-required"
      }
      let saved = writeReceipt(directory, receipt, state)
      let details = match restored {
        case Ok(_) => "Replaced metadata was restored."
        case Err(message) => "Some metadata needs recovery:\n{message}"
      }
      let receiptStatus = match saved {
        case Ok(_) => ""
        case Err(message) => "\nCannot update refresh receipt: {message}"
      }
      Err("{error}\n{details}\nBackups remain in {directory}{receiptStatus}")
    }
  }
}

export function refresh(root: string, checkOnly: bool, compile: Compile, native: Native) -> Result<int, string> {
  let cli = prepareRefresh(root)?
  let plan = prepareInventories(root, cli)?
  // A source edit must pass the unchanged compiler before it becomes a new
  // recorded snapshot. This performs no Cargo build or core regeneration.
  let request = validationRequest(cli.requestText)?
  completed(compile(request, closedFacts)?, "typed")?
  let changed = changedFiles(plan)
  if changed.length == 0 {
    io.writeLine("CLI snapshot and inventories match {cli.sourceCount} source modules.")
    return Ok(0)
  }
  if checkOnly {
    let mut paths: Array<string> = []
    for file in changed { paths.push(file.path) }
    return Err("CLI snapshot or inventories need refresh:\n{paths.join("\n")}\nRun kit refresh to update these metadata files.")
  }
  let base = backupRoot(root, native)?
  let lock = "{base}/lock"
  match native("mkdir-new", [lock]) {
    case Ok(_) => ()
    case Err(message) => return Err("cannot acquire the refresh lock: {message}\nIf an earlier process was interrupted, inspect its receipt and backups before removing {lock}")
  }
  let result = applyLocked(root, base, plan, changed, native)
  let unlock = native("rmdir-empty", [lock])
  match unlock {
    case Ok(_) => result
    case Err(message) => {
      let prior = match result {
        case Ok(_) => "Metadata refresh completed."
        case Err(error) => error
      }
      Err("{prior}\nCould not release the refresh lock: {message}\nInspect {lock} before the next refresh.")
    }
  }
}

import std.fs as files
import std.json { JSONValue, parse, parseAs, stringify }
import src.contracts {
  COMPILER_SOURCE_SET, CompilerRequest, DirectoryEntry, HostFact,
  PackageFacts, StandardModule,
}
import src.payload_files as payloadFiles
import src.requests { fromText }

// Preparation is read-only. The caller admits the protected repository
// inventory and commits all refreshed artifacts together after compilation.
export record PreparedCli {
  descriptorText: string,
  requestText: string,
  sourcePaths: Array<string>,
  standardPaths: Array<string>,
  sourceCount: int,
}

record SourceMapping derives JSON {
  logicalPath: string,
  path: string,
}

record StandardMapping derives JSON {
  identity: string,
  path: string,
  sourceFile: string,
}

record Descriptor derives JSON {
  schema: string,
  requestFile: string,
  compilerSourceSetId: string,
  sourceFiles: Array<SourceMapping>,
  standardModules: Array<StandardMapping>,
  callable: JSONValue,
  generatedRust: string,
}

record SourceTree {
  paths: Array<string>,
  directories: Array<string>,
  listings: Map<string, Array<DirectoryEntry>>,
}

const MAX_SOURCES = 1024
const MAX_DIRECTORIES = 256
const MAX_STANDARD_MODULES = 256
const MAX_DEPTH = 32
const CLI_ROOT = "core-kit/cli"
const INITIAL_REQUEST = "core-kit/cli/initial/request.json"
const CONTRACT_ENTRY = "_core_kit_refresh_contract.tpz"
const CONTRACT_SOURCE = """
import src.main as cli

export type EntryContract = (
  Array<string>,
  string,
  (string, (string) -> Result<string, string>) -> Result<string, string>,
  (string, Array<string>, string, Array<string>) -> Result<int, string>,
  (string, Array<string>) -> Result<string, string>,
  (string, Array<string>, string, Array<string>) -> Result<string, string>,
) -> Result<int, string>

export function checkedEntry() -> EntryContract \{
  cli.run
\}
"""

function parseDocument(text: string, label: string) -> Result<JSONValue, string> {
  match parse(text) {
    case Ok(value) => Ok(value)
    case Err(error) => Err("invalid {label} JSON at {error.line}:{error.column}: {error.message}")
  }
}

function required(value: JSONValue, name: string, label: string) -> Result<JSONValue, string> {
  match value.get(name) {
    case Some(found) => Ok(found)
    case None => Err("{label} requires `{name}`")
  }
}

function exactKeys(value: JSONValue, allowed: Array<string>, label: string) -> Result<(), string> {
  let keys = match value.keys() {
    case Some(found) => found
    case None => return Err("{label} must be a JSON object")
  }
  for key in keys {
    let mut found = false
    for name in allowed { if name == key { found = true } }
    if !found { return Err("unsupported {label} field `{key}`") }
  }
  for name in allowed { required(value, name, label)? }
  Ok(())
}

function arrayValue(value: JSONValue, label: string, maximum: int) -> Result<Array<JSONValue>, string> {
  let values = match value.asArray() {
    case Some(found) => found
    case None => return Err("{label} must be a JSON array")
  }
  if values.length > maximum { return Err("{label} exceeds {maximum} items") }
  Ok(values)
}

function stringValue(value: JSONValue, label: string) -> Result<string, string> {
  match value.asString() {
    case Some(found) => Ok(found)
    case None => Err("{label} must be a JSON string")
  }
}

// Reject unknown nested fields before record decoding can project them away.
function descriptorShape(value: JSONValue) -> Result<(), string> {
  exactKeys(value, [
    "schema", "requestFile", "compilerSourceSetId", "sourceFiles",
    "standardModules", "callable", "generatedRust",
  ], "CLI descriptor")?
  for mapping in arrayValue(required(value, "sourceFiles", "CLI descriptor")?, "CLI source mappings", MAX_SOURCES)? {
    exactKeys(mapping, ["logicalPath", "path"], "CLI source mapping")?
  }
  for mapping in arrayValue(required(value, "standardModules", "CLI descriptor")?, "CLI standard mappings", MAX_STANDARD_MODULES)? {
    exactKeys(mapping, ["identity", "path", "sourceFile"], "CLI standard mapping")?
  }
  let callable = required(value, "callable", "CLI descriptor")?
  exactKeys(callable, ["export", "arguments", "result"], "CLI callable")?
  if stringValue(required(callable, "export", "CLI callable")?, "CLI callable export")? != "run" ||
    stringValue(required(callable, "result", "CLI callable")?, "CLI callable result")? != "Result<int, string>" {
    return Err("kit refresh requires the current public CLI run ABI")
  }
  let expected = [
    "Array<string>", "string",
    "(string, (string) -> Result<string, string>) -> Result<string, string>",
    "(string, Array<string>, string, Array<string>) -> Result<int, string>",
    "(string, Array<string>) -> Result<string, string>",
    "(string, Array<string>, string, Array<string>) -> Result<string, string>",
  ]
  let arguments = arrayValue(required(callable, "arguments", "CLI callable")?, "CLI callable arguments", 6)?
  if arguments.length != expected.length { return Err("unsupported CLI callable argument count") }
  let mut index = 0
  while index < expected.length {
    if stringValue(arguments[index], "CLI callable argument")? != expected[index] {
      return Err("unsupported CLI callable argument {index}")
    }
    index += 1
  }
  Ok(())
}

function requestShape(value: JSONValue) -> Result<(), string> {
  exactKeys(value, [
    "schema", "producer", "compilerSourceSetId", "terminal", "entry", "root",
    "source", "sourceId", "languageMode", "profile", "facts", "package",
    "maxSourceFacts", "maxTotalSourceBytes", "maxAstNodes", "maxAstDepth",
    "maxRawTokens", "maxLayoutTokens", "maxHirNodes", "maxLoweredNodes",
    "maxDiagnostics", "maxGeneratedRustBytes", "maxFactRounds",
  ], "CLI initial request")?
  let package = required(value, "package", "CLI initial request")?
  exactKeys(package, [
    "buildRole", "externModules", "externReplayModules", "externReplayErrors", "generatedStdModules",
  ], "CLI package")?
  for module in arrayValue(required(package, "generatedStdModules", "CLI package")?, "CLI initial standard modules", MAX_STANDARD_MODULES)? {
    exactKeys(module, ["identity", "path", "source"], "CLI initial standard module")?
  }
  for fact in arrayValue(required(value, "facts", "CLI initial request")?, "CLI initial facts", 65536)? {
    exactKeys(fact, [
      "kind", "mountId", "logicalPath", "status", "source", "entries", "aliasClass", "reasonCode",
    ], "CLI initial fact")?
    for entry in arrayValue(required(fact, "entries", "CLI initial fact")?, "CLI initial directory entries", MAX_SOURCES + MAX_DIRECTORIES)? {
      exactKeys(entry, ["name", "kind"], "CLI initial directory entry")?
    }
  }
  Ok(())
}

function portableName(name: string) -> Result<string, string> {
  if name.contains("/") { return Err("CLI entry must be a single portable name") }
  payloadFiles.portablePath(name)
}

function portablePath(path: string) -> Result<string, string> {
  if path == "" || path.byteLength() > 1024 { return Err("CLI input path must contain 1..1024 bytes") }
  let parts = path.split("/")
  if parts.length > MAX_DEPTH + 4 { return Err("CLI input path exceeds its depth limit") }
  payloadFiles.portablePath(path)
}

function requireDirectory(root: string, path: string) -> Result<(), string> {
  portablePath(path)?
  let mut parent = root
  for name in path.split("/") {
    let mut found = false
    for child in files.list(parent)? {
      if child.name != name { continue }
      if child.kind != "directory" { return Err("CLI input directory must not be a symlink or other file type: {path}") }
      found = true
    }
    if !found { return Err("CLI input directory is missing: {path}") }
    parent = "{parent}/{name}"
  }
  Ok(())
}

function readText(root: string, path: string, limit: int) -> Result<string, string> {
  payloadFiles.requireRegularInput(root, path)?
  let text = files.readText("{root}/{path}")?
  // std.fs reads a complete buffer. This admission check is not a streaming
  // allocation limit, and it does not make a filesystem snapshot atomic.
  if text.byteLength() > limit { return Err("CLI input exceeds {limit} bytes: {path}") }
  Ok(text)
}

function sourceTree(root: string) -> Result<SourceTree, string> {
  requireDirectory(root, "{CLI_ROOT}/src")?
  let mut paths: Array<string> = []
  let mut directories = ["src"]
  let mut listings: Map<string, Array<DirectoryEntry>> = map {}
  let mut index = 0
  while index < directories.length {
    let directory = directories[index]
    let children = files.list("{root}/{CLI_ROOT}/{directory}")?
    if children.length > MAX_SOURCES + MAX_DIRECTORIES { return Err("CLI source directory has too many entries") }
    let mut names: Array<string> = []
    let mut kinds: Map<string, string> = map {}
    let mut folded: Set<string> = set {}
    for child in children {
      let lower = portableName(child.name)?
      if folded.contains(lower) { return Err("duplicate or case-aliased CLI source name: {directory}/{child.name}") }
      folded.add(lower)
      if child.kind != "file" && child.kind != "directory" {
        return Err("CLI sources must use regular files and directories, without symlinks: {directory}/{child.name}")
      }
      if child.kind == "file" && !child.name.endsWith(".tpz") {
        return Err("unsupported file in the CLI source tree: {directory}/{child.name}")
      }
      names.push(child.name)
      kinds.insert(child.name, child.kind)
    }
    names.sort()
    let mut entries: Array<DirectoryEntry> = []
    for name in names {
      let path = "{directory}/{name}"
      portablePath("{CLI_ROOT}/{path}")?
      let kind = kinds.getOr(name, "other")
      entries.push(DirectoryEntry { name: name, kind: kind })
      if kind == "directory" {
        if path.split("/").length > MAX_DEPTH { return Err("CLI source tree exceeds {MAX_DEPTH} directory levels") }
        directories.push(path)
        if directories.length > MAX_DIRECTORIES { return Err("CLI source tree exceeds {MAX_DIRECTORIES} directories") }
      } else {
        paths.push(path)
        if paths.length > MAX_SOURCES { return Err("CLI source tree exceeds {MAX_SOURCES} sources") }
      }
    }
    listings.insert(directory, entries)
    index += 1
  }
  if paths.length == 0 { return Err("CLI source tree is empty") }
  paths.sort()
  directories.sort()
  Ok(SourceTree { paths: paths, directories: directories, listings: listings })
}

function standardName(filename: string) -> Result<string, string> {
  let folded = portableName(filename)?
  if !filename.endsWith(".tpz") { return Err("CLI standard module must be a .tpz file: {filename}") }
  let name = filename.slice(0, filename.scalars().length - 4)
  if name == "" { return Err("CLI standard module needs a name") }
  let mut index = 0
  for byte in name.encodeUtf8().toArray() {
    let letter = (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122)
    let digit = byte >= 48 && byte <= 57
    if !letter && byte != 95 && !(index > 0 && digit) {
      return Err("CLI standard module name must be an ASCII identifier: {filename}")
    }
    index += 1
  }
  if folded == "lispex.tpz" { return Err("Core Kit does not include std.lispex") }
  Ok(name)
}

function standardMappings(root: string) -> Result<Array<StandardMapping>, string> {
  let mut mappings: Array<StandardMapping> = []
  let mut identities: Set<string> = set {}
  for name in ["bytes", "fs", "io", "json"] {
    mappings.push(StandardMapping {
      identity: "std.{name}", path: "std/{name}.tpz",
      sourceFile: "compiler/seed/initial/std/{name}.tpz",
    })
    identities.add(name)
  }
  requireDirectory(root, "{CLI_ROOT}/std")?
  let children = files.list("{root}/{CLI_ROOT}/std")?
  if children.length + 4 > MAX_STANDARD_MODULES { return Err("too many CLI standard modules") }
  let mut names: Array<string> = []
  for child in children {
    if child.kind != "file" { return Err("CLI standard modules must be regular files, without subdirectories or symlinks: {child.name}") }
    let name = standardName(child.name)?
    let lower = portableName(name)?
    if identities.contains(lower) { return Err("duplicate or canonical CLI standard module name: {child.name}") }
    identities.add(lower)
    names.push(name)
  }
  names.sort()
  for name in names {
    mappings.push(StandardMapping {
      identity: "std.{name}", path: "std/{name}.tpz", sourceFile: "{CLI_ROOT}/std/{name}.tpz",
    })
  }
  Ok(mappings)
}

function validatePrevious(descriptor: Descriptor, initial: CompilerRequest) -> Result<(), string> {
  if descriptor.schema != "topaz.note.core-kit-cli-request/v2" || descriptor.compilerSourceSetId != COMPILER_SOURCE_SET {
    return Err("CLI descriptor does not identify this canonical compiler")
  }
  if descriptor.requestFile != INITIAL_REQUEST { return Err("CLI descriptor must use {INITIAL_REQUEST}") }
  portablePath(descriptor.generatedRust)?
  if !descriptor.generatedRust.startsWith("out/") || !descriptor.generatedRust.endsWith(".rs") {
    return Err("CLI generatedRust must name a portable .rs path beneath out/")
  }
  if initial.producer != "topaz-stage1" || initial.terminal != "rust-source" ||
    initial.entry != "src/main.tpz" || initial.sourceId != "src/main.tpz" || initial.root != "" ||
    initial.package.buildRole != "standalone" {
    return Err("kit refresh requires the standalone Stage 1 CLI request rooted at src/main.tpz")
  }
  if descriptor.sourceFiles.length == 0 { return Err("CLI descriptor source mapping is empty") }
  let mut sources: Set<string> = set {}
  let mut folded: Set<string> = set {}
  for mapping in descriptor.sourceFiles {
    let lower = portablePath(mapping.logicalPath)?
    portablePath(mapping.path)?
    if !mapping.logicalPath.startsWith("src/") || !mapping.logicalPath.endsWith(".tpz") ||
      mapping.path != "{CLI_ROOT}/{mapping.logicalPath}" {
      return Err("existing CLI source mapping escapes the managed source tree")
    }
    if folded.contains(lower) { return Err("duplicate or case-aliased existing CLI source mapping") }
    sources.add(mapping.logicalPath)
    folded.add(lower)
  }
  let mut usedSources: Set<string> = set {}
  let mut sourceCount = 0
  for fact in initial.facts {
    if fact.logicalPath != "" {
      portablePath(fact.logicalPath)?
      if fact.logicalPath != "src" && !fact.logicalPath.startsWith("src/") {
        return Err("initial CLI fact escapes the managed virtual source tree")
      }
    }
    if fact.reasonCode != "" { return Err("initial CLI facts must not contain unresolved host errors") }
    if fact.kind == "read-source" {
      if fact.status != "present" || !sources.contains(fact.logicalPath) || usedSources.contains(fact.logicalPath) ||
        fact.entries.length != 0 || fact.aliasClass != "" {
        return Err("initial CLI source facts must correspond to the previous descriptor")
      }
      usedSources.add(fact.logicalPath)
      sourceCount += 1
    } else if fact.kind == "physical-containment" {
      let alias = if fact.logicalPath == "" { "." } else { fact.logicalPath }
      if fact.status != "inside" || fact.source != "" || fact.entries.length != 0 || fact.aliasClass != alias {
        return Err("initial CLI containment must describe its closed virtual source tree")
      }
    } else {
      if fact.status != "present" || fact.source != "" || fact.aliasClass != "" {
        return Err("initial CLI directory facts must describe their closed virtual source tree")
      }
      let mut names: Set<string> = set {}
      for entry in fact.entries {
        let lower = portableName(entry.name)?
        if names.contains(lower) || (entry.kind != "file" && entry.kind != "directory") {
          return Err("invalid or case-aliased initial CLI directory entry")
        }
        names.add(lower)
      }
    }
  }
  if sourceCount != descriptor.sourceFiles.length { return Err("previous CLI sources and initial facts differ") }
  let mut standards: Map<string, string> = map {}
  let mut standardNames: Set<string> = set {}
  let mut fixed: Set<string> = set {}
  for mapping in descriptor.standardModules {
    let pieces = mapping.path.split("/")
    if pieces.length != 2 || pieces[0] != "std" { return Err("invalid existing CLI standard module path") }
    let name = standardName(pieces[1])?
    let lower = portableName(name)?
    if mapping.identity != "std.{name}" || standardNames.contains(lower) { return Err("invalid or duplicate existing CLI standard module identity") }
    let canonical = name == "bytes" || name == "fs" || name == "io" || name == "json"
    let sourceFile = if canonical { "compiler/seed/initial/std/{name}.tpz" } else { "{CLI_ROOT}/std/{name}.tpz" }
    if mapping.sourceFile != sourceFile { return Err("existing CLI standard mapping has an unsupported source location") }
    standardNames.add(lower)
    standards.insert(mapping.identity, mapping.path)
    if canonical { fixed.add(name) }
  }
  for name in ["bytes", "fs", "io", "json"] {
    if !fixed.contains(name) { return Err("existing CLI descriptor omits canonical standard module std.{name}") }
  }
  for module in initial.package.generatedStdModules {
    if !standards.containsKey(module.identity) || standards.getOr(module.identity, "") != module.path {
      return Err("initial CLI standard modules differ from the previous descriptor")
    }
  }
  if initial.package.generatedStdModules.length != descriptor.standardModules.length {
    return Err("previous CLI standard mappings and initial modules differ")
  }
  Ok(())
}

function containment(path: string) -> HostFact {
  HostFact {
    kind: "physical-containment", mountId: "root", logicalPath: path,
    status: "inside", source: "", entries: [],
    aliasClass: if path == "" { "." } else { path }, reasonCode: "",
  }
}

function listing(path: string, entries: Array<DirectoryEntry>) -> HostFact {
  HostFact {
    kind: "list-directory", mountId: "root", logicalPath: path,
    status: "present", source: "", entries: entries, aliasClass: "", reasonCode: "",
  }
}

export function prepareRefresh(root: string) -> Result<PreparedCli, string> {
  let descriptorText = readText(root, "{CLI_ROOT}/REQUEST.json", 1048576)?
  descriptorShape(parseDocument(descriptorText, "CLI descriptor")?)?
  let descriptor = parseAs<Descriptor>(descriptorText)?
  // Read only the fixed request location, never a path supplied by an
  // unadmitted descriptor. fromText also checks every resource budget.
  let initialText = readText(root, INITIAL_REQUEST, 134217728)?
  requestShape(parseDocument(initialText, "CLI initial request")?)?
  let initial = fromText(initialText)?
  validatePrevious(descriptor, initial)?

  let tree = sourceTree(root)?
  if tree.paths.length > initial.maxSourceFacts { return Err("refreshed CLI sources exceed the declared source budget") }
  let mut mappings: Array<SourceMapping> = []
  let mut sourcePaths: Array<string> = []
  let mut facts: Array<HostFact> = []
  let mut entryFound = false
  let mut entrySource = ""
  let mut totalBytes = 0
  for path in tree.paths {
    let physical = "{CLI_ROOT}/{path}"
    let source = readText(root, physical, initial.maxTotalSourceBytes)?
    totalBytes += source.byteLength()
    if totalBytes > initial.maxTotalSourceBytes { return Err("refreshed CLI sources exceed the declared byte budget") }
    if path == initial.entry {
      entryFound = true
      entrySource = source
    }
    mappings.push(SourceMapping { logicalPath: path, path: physical })
    sourcePaths.push(physical)
    facts.push(HostFact {
      kind: "read-source", mountId: "root", logicalPath: path,
      status: "present", source: source, entries: [], aliasClass: "", reasonCode: "",
    })
    facts.push(containment(path))
  }
  if !entryFound { return Err("CLI entry src/main.tpz is missing") }
  facts.push(containment(""))
  facts.push(listing("", [DirectoryEntry { name: "src", kind: "directory" }]))
  for directory in tree.directories {
    facts.push(containment(directory))
    facts.push(listing(directory, tree.listings.getOr(directory, [])))
  }

  let standards = standardMappings(root)?
  let mut modules: Array<StandardModule> = []
  let mut standardPaths: Array<string> = []
  for mapping in standards {
    let source = readText(root, mapping.sourceFile, initial.maxTotalSourceBytes)?
    totalBytes += source.byteLength()
    if totalBytes > initial.maxTotalSourceBytes { return Err("refreshed CLI and standard modules exceed the declared byte budget") }
    modules.push(StandardModule { identity: mapping.identity, path: mapping.path, source: source })
    standardPaths.push(mapping.sourceFile)
  }
  standardPaths.sort()
  let request = CompilerRequest {
    ...initial, source: entrySource, facts: facts,
    package: PackageFacts { ...initial.package, generatedStdModules: modules },
  }
  let requestText = stringify(request)?
  // Reuse admission on the finished candidate so the refresh path cannot
  // invent a different interpretation of the public request budgets.
  fromText(requestText)?
  let updated = Descriptor { ...descriptor, sourceFiles: mappings, standardModules: standards }
  let updatedText = stringify(updated)?
  Ok(PreparedCli {
    descriptorText: "{updatedText}\n", requestText: "{requestText}\n",
    sourcePaths: sourcePaths, standardPaths: standardPaths, sourceCount: tree.paths.length,
  })
}

// Compile this transient entry instead of trusting the descriptor's ABI text.
// Its literal function type also rejects an extra defaulted parameter, which
// a six-argument call could otherwise accept. Neither the guard nor its budget
// allowance belongs in the persisted CLI source snapshot.
export function validationRequest(text: string) -> Result<string, string> {
  let initial = fromText(text)?
  if initial.entry != "src/main.tpz" || initial.sourceId != "src/main.tpz" || initial.root != "" {
    return Err("CLI callable validation requires the prepared src/main.tpz request")
  }
  let mut facts: Array<HostFact> = []
  let mut rootListing = false
  for fact in initial.facts {
    if fact.logicalPath == CONTRACT_ENTRY {
      return Err("CLI request already contains the reserved callable validation source")
    }
    if fact.kind == "list-directory" && fact.logicalPath == "" {
      if fact.status != "present" { return Err("CLI callable validation requires a present root directory") }
      let mut entries = [DirectoryEntry { name: CONTRACT_ENTRY, kind: "file" }]
      for entry in fact.entries {
        if entry.name == CONTRACT_ENTRY { return Err("CLI root contains the reserved callable validation source") }
        entries.push(entry)
      }
      facts.push(HostFact { ...fact, entries: entries })
      rootListing = true
    } else {
      facts.push(fact)
    }
  }
  if !rootListing { return Err("CLI callable validation requires the prepared root directory listing") }
  facts.push(HostFact {
    kind: "read-source", mountId: "root", logicalPath: CONTRACT_ENTRY,
    status: "present", source: CONTRACT_SOURCE, entries: [], aliasClass: "", reasonCode: "",
  })
  facts.push(containment(CONTRACT_ENTRY))
  let sourceBudget = if initial.maxSourceFacts < 16384 { initial.maxSourceFacts + 1 } else { 16384 }
  let guardBytes = CONTRACT_SOURCE.byteLength()
  let byteBudget = if initial.maxTotalSourceBytes <= 67108864 - guardBytes {
    initial.maxTotalSourceBytes + guardBytes
  } else {
    67108864
  }
  let request = CompilerRequest {
    ...initial, terminal: "typed", entry: CONTRACT_ENTRY, sourceId: CONTRACT_ENTRY,
    source: CONTRACT_SOURCE, facts: facts,
    maxSourceFacts: sourceBudget, maxTotalSourceBytes: byteBudget,
  }
  let result = stringify(request)?
  fromText(result)?
  Ok(result)
}

import std.fs as files
import src.contracts { COMPILER_SOURCE_SET }
import src.payload_files { portablePath, requireRegularInput, requiredInputs }
import src.refresh_inputs { PreparedCli }
import src.verification { parseInventory }

export const DESCRIPTOR = "core-kit/cli/REQUEST.json"
export const INITIAL = "core-kit/cli/initial/request.json"
export const INPUT_LIST = "core-kit/payload-inputs.data"
export const INVENTORY = "core-kit/verify-core.data"

export record RefreshFile {
  path: string,
  before: string,
  after: string,
}

function readText(root: string, path: string) -> Result<string, string> {
  requireRegularInput(root, path)?
  let text = files.readText("{root}/{path}")?
  if text.byteLength() > 134217728 { return Err("maintenance input exceeds 128 MiB: {path}") }
  Ok(text)
}

function digest(root: string, path: string) -> Result<string, string> {
  requireRegularInput(root, path)?
  let bytes = files.readBytes("{root}/{path}")?
  if bytes.length() > 536870912 { return Err("maintenance input exceeds 512 MiB: {path}") }
  Ok(bytes.sha256().toHex())
}

function checkDigest(root: string, path: string, expected: string) -> Result<(), string> {
  if digest(root, path)? != expected {
    return Err("protected input differs; kit refresh cannot update its recorded hash: {path}")
  }
  Ok(())
}

function under(path: string, directory: string) -> bool {
  path.startsWith("{directory}/")
}

function mutableInput(path: string) -> bool {
  path == DESCRIPTOR || path == INITIAL || path == INPUT_LIST ||
    path == "core-kit/cli/topaz.toml" || path == "core-kit/cli/data/input.txt" ||
    under(path, "core-kit/cli/src") || under(path, "core-kit/cli/std") ||
    under(path, "core-kit/cli/templates") || under(path, "core-kit/distribution") ||
    under(path, "examples/core-kit")
}

function requireDirectory(root: string, path: string) -> Result<(), string> {
  portablePath(path)?
  let mut parent = root
  for part in path.split("/") {
    let mut found = false
    for entry in files.list(parent)? {
      if entry.name == part {
        if entry.kind != "directory" { return Err("maintenance directory must not be a symlink or another file kind: {path}") }
        found = true
      }
    }
    if !found { return Err("maintenance directory is missing: {path}") }
    parent = "{parent}/{part}"
  }
  Ok(())
}

// Only these explicitly selected trees are walked. Cargo caches, outputs and
// unrelated Git files do not become build inputs merely by existing nearby.
function walkFiles(root: string, directory: string) -> Result<Array<string>, string> {
  requireDirectory(root, directory)?
  let mut directories = [directory]
  let mut paths: Array<string> = []
  let mut aliases: Set<string> = set {}
  let mut index = 0
  while index < directories.length {
    let current = directories[index]
    if current.split("/").length > 32 { return Err("maintenance tree exceeds 32 path segments") }
    let entries = files.list("{root}/{current}")?
    if entries.length > 1024 { return Err("maintenance directory exceeds 1024 entries") }
    for entry in entries {
      if entry.name.contains("/") { return Err("maintenance directory returned an invalid entry name") }
      let path = "{current}/{entry.name}"
      let alias = portablePath(path)?
      if aliases.contains(alias) { return Err("case-aliased maintenance input: {path}") }
      aliases.add(alias)
      if entry.kind == "directory" {
        directories.push(path)
      } else if entry.kind == "file" {
        paths.push(path)
      } else {
        return Err("maintenance input must use regular files and directories: {path}")
      }
      if aliases.length > 2048 || paths.length > 1024 {
        return Err("maintenance tree exceeds its file or directory budget")
      }
    }
    index += 1
  }
  paths.sort()
  Ok(paths)
}

function sortedUnique(paths: Array<string>) -> Result<Array<string>, string> {
  let mut output: Array<string> = []
  let mut seen: Map<string, string> = map {}
  for path in paths {
    let alias = portablePath(path)?
    if seen.containsKey(alias) {
      if seen.getOr(alias, "") != path { return Err("case-aliased maintenance input: {path}") }
      continue
    }
    seen.insert(alias, path)
    output.push(path)
  }
  if output.length > 1024 { return Err("maintenance input set exceeds 1024 files") }
  output.sort()
  Ok(output)
}

function existingPayloadPaths(text: string) -> Result<Array<string>, string> {
  if text.byteLength() == 0 || text.byteLength() > 1048576 {
    return Err("payload input list must contain at most 1 MiB")
  }
  let lines = text.split("\n")
  if lines[0] != "topaz.core-kit-payload-inputs/v1" { return Err("unsupported payload input list") }
  let mut paths: Array<string> = []
  let mut index = 1
  while index < lines.length {
    if lines[index] == "" && index + 1 == lines.length { break }
    paths.push(lines[index])
    index += 1
  }
  let sorted = sortedUnique(paths)?
  if sorted.length != paths.length || text != "topaz.core-kit-payload-inputs/v1\n{sorted.join("\n")}\n" {
    return Err("payload input list must be sorted, unique and LF terminated")
  }
  let mut exact: Set<string> = set {}
  for path in paths { exact.add(path) }
  requiredInputs(exact)?
  Ok(paths)
}

export function prepareInventories(root: string, cli: PreparedCli) -> Result<Array<RefreshFile>, string> {
  let inventoryBefore = readText(root, INVENTORY)?
  let inventory = parseInventory(inventoryBefore)?
  let payloadBefore = readText(root, INPUT_LIST)?
  let payloadPaths = existingPayloadPaths(payloadBefore)?
  let mut protectedLines: Array<string> = []
  let mut inputPaths: Array<string> = []
  for file in inventory.files {
    if file.kind == "compiler_source" {
      checkDigest(root, "compiler/crates/topaz_self_frontend/topaz/{file.path}", file.digest)?
      checkDigest(root, "compiler/seed/initial/topaz/{file.path}", file.digest)?
      protectedLines.push("{file.kind}|{file.path}|{file.digest}")
    } else if file.kind == "snapshot_file" {
      checkDigest(root, file.path, file.digest)?
      protectedLines.push("{file.kind}|{file.path}|{file.digest}")
    } else if !mutableInput(file.path) {
      checkDigest(root, file.path, file.digest)?
      inputPaths.push(file.path)
    }
  }
  for path in [DESCRIPTOR, INITIAL, INPUT_LIST, "core-kit/cli/topaz.toml", "core-kit/cli/data/input.txt"] {
    inputPaths.push(path)
  }
  for path in cli.sourcePaths { inputPaths.push(path) }
  for path in cli.standardPaths { inputPaths.push(path) }
  for directory in ["core-kit/cli/templates", "core-kit/distribution", "examples/core-kit"] {
    for path in walkFiles(root, directory)? { inputPaths.push(path) }
  }
  let inputs = sortedUnique(inputPaths)?

  let dynamicTrees = [
    "core-kit/cli/src", "core-kit/cli/std", "core-kit/cli/templates",
    "core-kit/native", "core-kit/fixtures", "core-kit/distribution", "examples/core-kit",
  ]
  let mut updatedPayload: Array<string> = []
  for path in payloadPaths {
    let mut dynamic = false
    for directory in dynamicTrees { if under(path, directory) { dynamic = true } }
    if !dynamic { updatedPayload.push(path) }
  }
  for path in inputs { updatedPayload.push(path) }
  for directory in dynamicTrees {
    for path in walkFiles(root, directory)? { updatedPayload.push(path) }
  }
  let payload = sortedUnique(updatedPayload)?
  let mut exact: Set<string> = set {}
  for path in payload {
    requireRegularInput(root, path)?
    exact.add(path)
  }
  requiredInputs(exact)?
  let payloadAfter = "topaz.core-kit-payload-inputs/v1\n{payload.join("\n")}\n"

  let mut replacements: Map<string, string> = map {}
  replacements.insert(DESCRIPTOR, cli.descriptorText)
  replacements.insert(INITIAL, cli.requestText)
  replacements.insert(INPUT_LIST, payloadAfter)
  let mut rows: Array<string> = []
  for path in inputs {
    let hash = match replacements.get(path) {
      case Some(text) => text.encodeUtf8().sha256().toHex()
      case None => digest(root, path)?
    }
    rows.push("input_file|{path}|{hash}")
  }
  protectedLines.sort()
  let inventoryAfter = "# Generated by topaz-core-kit kit refresh. Canonical and snapshot hashes are preserved.\nformat|topaz.core-kit-inputs/v2\ncompiler_source_set|{COMPILER_SOURCE_SET}\ncompiler_sources|{inventory.compilerCount}\nsnapshot_files|{inventory.snapshotCount}\ninput_files|{inputs.length}\n{rows.join("\n")}\n{protectedLines.join("\n")}\n"
  parseInventory(inventoryAfter)?
  Ok([
    RefreshFile { path: DESCRIPTOR, before: readText(root, DESCRIPTOR)?, after: cli.descriptorText },
    RefreshFile { path: INITIAL, before: readText(root, INITIAL)?, after: cli.requestText },
    RefreshFile { path: INPUT_LIST, before: payloadBefore, after: payloadAfter },
    RefreshFile { path: INVENTORY, before: inventoryBefore, after: inventoryAfter },
  ])
}

import std.bytes { Bytes, ByteBuffer }
import src.payload_files { portablePath }

// A bounded flat ustar subset wrapped in the public canonical gzip codec.
// The gzip codec uses stored DEFLATE blocks. It gives stable transport bytes,
// not a compression-ratio optimization or an external archiver dependency.
export const MAX_TAR_BYTES = 268435456
export const MAX_ARCHIVE_BYTES = 536870912
const BLOCK = 512
const MAX_FILES = 256

export record ArchiveEntry {
  path: string,
  mode: string,
  bytes: Bytes,
}

function filename(path: string) -> Result<string, string> {
  let folded = portablePath(path)?
  if path.contains("/") || path.startsWith(".") || path.byteLength() > 100 {
    return Err("release archive names must be flat visible ASCII filenames of at most 100 bytes")
  }
  Ok(folded)
}

function modeNumber(mode: string) -> Result<int, string> {
  match mode {
    case "0644" => Ok(420)
    case "0755" => Ok(493)
    case _ => Err("release archive modes must be 0644 or 0755")
  }
}

function padding(length: int) -> int { (BLOCK - length % BLOCK) % BLOCK }

function zeros(length: int) -> Array<int> {
  let mut bytes: Array<int> = []
  let mut index = 0
  while index < length { bytes.push(0); index += 1 }
  bytes
}

function octal(value: int, digits: int) -> Result<Array<int>, string> {
  if value < 0 { return Err("negative tar field") }
  let mut output: Array<int> = []
  let mut index = 0
  while index < digits { output.push(48); index += 1 }
  let mut remaining = value
  index = digits
  while index > 0 {
    index -= 1
    output[index] = 48 + remaining % 8
    remaining = remaining / 8
  }
  if remaining != 0 { return Err("tar numeric field exceeds its canonical width") }
  Ok(output)
}

function header(path: string, mode: string, length: int) -> Result<Bytes, string> {
  filename(path)?
  if length <= 0 || length > MAX_TAR_BYTES { return Err("archive member size exceeds its supported range") }
  let mut output = zeros(BLOCK)
  let name = path.encodeUtf8().toArray()
  let mut index = 0
  while index < name.length { output[index] = name[index]; index += 1 }
  let modeBytes = octal(modeNumber(mode)?, 7)?
  let zero7 = octal(0, 7)?
  index = 0
  while index < 7 {
    output[100 + index] = modeBytes[index]
    output[108 + index] = zero7[index]
    output[116 + index] = zero7[index]
    output[329 + index] = zero7[index]
    output[337 + index] = zero7[index]
    index += 1
  }
  let sizeBytes = octal(length, 11)?
  let zero11 = octal(0, 11)?
  index = 0
  while index < 11 {
    output[124 + index] = sizeBytes[index]
    output[136 + index] = zero11[index]
    index += 1
  }
  index = 148
  while index < 156 { output[index] = 32; index += 1 }
  output[156] = 48
  let magic = "ustar".encodeUtf8().toArray()
  index = 0
  while index < magic.length { output[257 + index] = magic[index]; index += 1 }
  output[263] = 48
  output[264] = 48
  let mut sum = 0
  for byte in output { sum += byte }
  let checksum = octal(sum, 6)?
  index = 0
  while index < 6 { output[148 + index] = checksum[index]; index += 1 }
  output[154] = 0
  output[155] = 32
  Bytes.fromArray(output)
}

function sortedEntries(entries: Array<ArchiveEntry>) -> Result<Array<ArchiveEntry>, string> {
  if entries.length == 0 || entries.length > MAX_FILES {
    return Err("release archive must contain between 1 and 256 regular files")
  }
  let mut names: Array<string> = []
  let mut seen: Set<string> = set {}
  let mut byName: Map<string, ArchiveEntry> = map {}
  for entry in entries {
    let folded = filename(entry.path)?
    modeNumber(entry.mode)?
    if seen.contains(folded) { return Err("release archive has duplicate or case-aliased names") }
    seen.add(folded)
    names.push(entry.path)
    byName.insert(entry.path, entry)
  }
  names.sort()
  let mut ordered: Array<ArchiveEntry> = []
  for name in names {
    let entry = match byName.get(name) {
      case Some(entry) => entry
      case None => return Err("internal archive name mapping is incomplete")
    }
    ordered.push(entry)
  }
  Ok(ordered)
}

export function encode(entries: Array<ArchiveEntry>) -> Result<Bytes, string> {
  let ordered = sortedEntries(entries)?
  let mut total = BLOCK * 2
  for entry in ordered {
    let length = entry.bytes.length()
    if length <= 0 || length > MAX_TAR_BYTES { return Err("archive members must be nonempty and no larger than 256 MiB") }
    let extent = BLOCK + length + padding(length)
    if extent > MAX_TAR_BYTES - total { return Err("complete release tar exceeds 256 MiB") }
    total += extent
  }
  let mut output = ByteBuffer.allocate(total)
  let mut offset = 0
  for entry in ordered {
    let metadata = ByteBuffer.fromBytes(header(entry.path, entry.mode, entry.bytes.length())?)
    output.copy(metadata, 0, offset, BLOCK)
    offset += BLOCK
    let contents = ByteBuffer.fromBytes(entry.bytes)
    output.copy(contents, 0, offset, entry.bytes.length())
    offset += entry.bytes.length() + padding(entry.bytes.length())
  }
  let tar = output.toBytes()
  tar.gzipCompress()
}

function u16(data: Bytes, offset: int) -> int {
  (data.get(offset) ?? 0) + (data.get(offset + 1) ?? 0) * 256
}

function u32(data: Bytes, offset: int) -> int {
  u16(data, offset) + u16(data, offset + 2) * 65536
}

function preflightGzip(data: Bytes) -> Result<(), string> {
  if data.length() < 23 || data.length() > MAX_ARCHIVE_BYTES {
    return Err("release archive must be nonempty and no larger than 512 MiB")
  }
  let trailer = data.length() - 8
  let advertised = u32(data, trailer + 4)
  if advertised < BLOCK * 2 || advertised > MAX_TAR_BYTES || advertised % BLOCK != 0 {
    return Err("gzip tar size is outside the supported 256 MiB profile")
  }
  // Stored blocks cannot expand beyond their recorded body length. Count
  // their complete extents before the public codec allocates the tar buffer.
  let mut offset = 10
  let mut total = 0
  let mut lastBlock = false
  while !lastBlock {
    if offset > trailer || trailer - offset < 5 { return Err("truncated release gzip block") }
    let flags = data.get(offset) ?? 0
    if flags != 0 && flags != 1 { return Err("release gzip requires canonical stored DEFLATE blocks") }
    lastBlock = flags == 1
    let length = u16(data, offset + 1)
    if u16(data, offset + 3) != 65535 - length { return Err("invalid release gzip block length") }
    if !lastBlock && length != 65535 { return Err("nonfinal release gzip block must use the canonical length") }
    if lastBlock && length == 0 { return Err("nonempty release gzip must not add an empty final block") }
    offset += 5
    if length > trailer - offset || length > MAX_TAR_BYTES - total {
      return Err("release gzip body exceeds its declared or supported size")
    }
    total += length
    offset += length
  }
  if offset != trailer || total != advertised {
    return Err("release gzip block totals or trailing bytes differ from its declared size")
  }
  Ok(())
}

function allZero(data: Bytes, start: int, length: int) -> bool {
  let mut index = start
  while index < start + length {
    if (data.get(index) ?? -1) != 0 { return false }
    index += 1
  }
  true
}

function tarNumber(data: Bytes, start: int, digits: int) -> Result<int, string> {
  let mut value = 0
  let mut index = 0
  while index < digits {
    let byte = data.get(start + index) ?? 0
    if byte < 48 || byte > 55 { return Err("release tar fields require canonical octal digits") }
    value = value * 8 + byte - 48
    index += 1
  }
  if (data.get(start + digits) ?? -1) != 0 { return Err("release tar numeric field must end with NUL") }
  Ok(value)
}

export function decode(compressed: Bytes) -> Result<Array<ArchiveEntry>, string> {
  preflightGzip(compressed)?
  let tar = compressed.gzipDecompress()?
  if tar.length() > MAX_TAR_BYTES || tar.length() % BLOCK != 0 {
    return Err("release tar exceeds its supported size or block alignment")
  }
  let mut entries: Array<ArchiveEntry> = []
  let mut names: Array<string> = []
  let mut seen: Set<string> = set {}
  let mut offset = 0
  while offset + BLOCK <= tar.length() {
    if allZero(tar, offset, BLOCK) {
      if tar.length() - offset != BLOCK * 2 || !allZero(tar, offset, BLOCK * 2) {
        return Err("release tar must end with precisely two zero blocks")
      }
      if entries.length == 0 { return Err("release tar contains no payload files") }
      let before = names.join("\n")
      names.sort()
      if before != names.join("\n") { return Err("release tar members must be sorted") }
      return Ok(entries)
    }
    if entries.length >= MAX_FILES { return Err("release tar exceeds 256 members") }
    let mut end = offset
    while end < offset + 100 && (tar.get(end) ?? 0) != 0 { end += 1 }
    let path = tar.slice(offset, end).decodeUtf8()?
    let folded = filename(path)?
    if seen.contains(folded) { return Err("release tar repeats a name or case alias") }
    let mode = match tarNumber(tar, offset + 100, 7)? {
      case 420 => "0644"
      case 493 => "0755"
      case _ => return Err("release tar has an unsupported file mode")
    }
    let length = tarNumber(tar, offset + 124, 11)?
    if length <= 0 || length > MAX_TAR_BYTES { return Err("release tar member size exceeds its supported range") }
    let actual = tar.slice(offset, offset + BLOCK)
    if actual != header(path, mode, length)? {
      return Err("release tar header differs from the canonical regular-file contract")
    }
    offset += BLOCK
    if length > tar.length() - offset { return Err("release tar member extends beyond the archive") }
    let bytes = tar.slice(offset, offset + length)
    offset += length
    let remaining = padding(length)
    if remaining > tar.length() - offset || !allZero(tar, offset, remaining) {
      return Err("release tar file padding must be zero")
    }
    offset += remaining
    seen.add(folded)
    names.push(path)
    entries.push(ArchiveEntry { path: path, mode: mode, bytes: bytes })
  }
  Err("release tar is missing its complete end marker")
}

import std.bytes { Bytes }
import std.fs as files

// These are structural observations, not a loader, a signature verifier or a
// compatibility test. Target names select this repository's supported format
// and architecture profiles. They do not prove a producer's compiler or ABI.
// Every offset is checked before slicing. Counts, strings and tables have
// independent limits so malformed inputs cannot request unbounded traversal.
export const MAX_IMAGE_BYTES = 536870912
const MAX_TABLE_BYTES = 1048576
const MAX_SECTIONS = 64
const MAX_DEPENDENCIES = 256
const MAX_STRING_BYTES = 4096
const MAX_INT = 9223372036854775807
const PE_DEBUG_CODEVIEW = 2
const PE_DEBUG_REPRO = 16
const CODEVIEW_RSDS = 1396986706

export record Section derives JSON {
  name: string,
  offset: int,
  bytes: int,
  sha256: string,
}

export record Field derives JSON {
  name: string,
  value: string,
}

export record Image derives JSON {
  format: string,
  target: string,
  bytes: int,
  sha256: string,
  dependencies: Array<string>,
  sections: Array<Section>,
  metadata: Array<Field>,
}

record Segment {
  address: int,
  memoryBytes: int,
  offset: int,
  bytes: int,
  flags: int,
}

record Region {
  offset: int,
  bytes: int,
}

function checkedRange(data: Bytes, offset: int, size: int) -> Result<(), string> {
  if offset < 0 || size < 0 || offset > data.length() || size > data.length() - offset {
    return Err("binary contains an out-of-file range")
  }
  Ok(())
}

function checkedExtent(address: int, size: int) -> Result<(), string> {
  if address < 0 || size < 0 || size > MAX_INT - address {
    return Err("binary address extent exceeds the supported integer range")
  }
  Ok(())
}

function u16(data: Bytes, offset: int) -> Result<int, string> {
  checkedRange(data, offset, 2)?
  Ok((data.get(offset) ?? 0) + (data.get(offset + 1) ?? 0) * 256)
}

function u32(data: Bytes, offset: int) -> Result<int, string> {
  checkedRange(data, offset, 4)?
  Ok((data.get(offset) ?? 0) + (data.get(offset + 1) ?? 0) * 256 +
    (data.get(offset + 2) ?? 0) * 65536 + (data.get(offset + 3) ?? 0) * 16777216)
}

function u64(data: Bytes, offset: int) -> Result<int, string> {
  checkedRange(data, offset, 8)?
  let low = u32(data, offset)?
  let high = u32(data, offset + 4)?
  if high > 2147483647 { return Err("binary integer exceeds the supported signed 64-bit range") }
  Ok(low + high * 4294967296)
}

function flag(value: int, bit: int) -> bool { (value / bit) % 2 == 1 }

function fixedName(data: Bytes, offset: int, size: int) -> Result<string, string> {
  checkedRange(data, offset, size)?
  let mut end = offset
  while end < offset + size && (data.get(end) ?? 0) != 0 { end += 1 }
  data.slice(offset, end).decodeUtf8()
}

function cString(data: Bytes, offset: int, available: int) -> Result<string, string> {
  checkedRange(data, offset, available)?
  let mut index = 0
  while index < available && index < MAX_STRING_BYTES {
    let byte = data.get(offset + index) ?? 0
    if byte == 0 { return data.slice(offset, offset + index).decodeUtf8() }
    if byte < 32 || byte == 127 { return Err("binary string contains a control byte") }
    index += 1
  }
  Err("binary string is unterminated or exceeds 4 KiB")
}

function dependencyName(name: string, windows: bool) -> Result<string, string> {
  if name == "" { return Err("binary dependency name is empty") }
  if !windows { return Ok(name) }
  let source = name.encodeUtf8()
  let mut lower: Array<int> = []
  let mut index = 0
  while index < source.length() {
    let byte = source.get(index) ?? 0
    if byte < 33 || byte > 126 || byte == 47 || byte == 92 || byte == 58 {
      return Err("PE dependency must be an ASCII library filename")
    }
    if byte >= 65 && byte <= 90 { lower.push(byte + 32) } else { lower.push(byte) }
    index += 1
  }
  let folded = Bytes.fromArray(lower)?
  folded.decodeUtf8()
}

function uniqueDependencies(names: Array<string>) -> Result<Array<string>, string> {
  if names.length > MAX_DEPENDENCIES { return Err("binary has more than 256 dependency declarations") }
  let mut seen: Set<string> = set {}
  let mut result: Array<string> = []
  for name in names {
    if !seen.contains(name) { seen.add(name); result.push(name) }
  }
  result.sort()
  Ok(result)
}

function section(data: Bytes, previous: Array<Section>, name: string, offset: int, size: int) -> Result<Section, string> {
  if previous.length >= MAX_SECTIONS { return Err("binary has more than 64 sections") }
  checkedRange(data, offset, size)?
  // Reject overlapping raw sections before hashing. This also bounds total
  // section hashing by image length, even when all headers are adversarial.
  if size > 0 {
    for old in previous {
      if old.bytes > 0 && offset < old.offset + old.bytes && old.offset < offset + size {
        return Err("binary raw sections overlap")
      }
    }
  }
  Ok(Section { name: name, offset: offset, bytes: size, sha256: data.slice(offset, offset + size).sha256().toHex() })
}

function mapped(segments: Array<Segment>, address: int, size: int, headerBytes: int) -> Result<Region, string> {
  checkedExtent(address, size)?
  if address < headerBytes && size <= headerBytes - address {
    return Ok(Region { offset: address, bytes: headerBytes - address })
  }
  let mut found = false
  let mut result = Region { offset: 0, bytes: 0 }
  for segment in segments {
    if address >= segment.address {
      let delta = address - segment.address
      if delta < segment.bytes && size <= segment.bytes - delta {
        if found { return Err("binary address has ambiguous file mappings") }
        found = true
        result = Region { offset: segment.offset + delta, bytes: segment.bytes - delta }
      }
    }
  }
  if !found { return Err("binary address does not map to file-backed data") }
  Ok(result)
}

function executableEntry(segments: Array<Segment>, entry: int, executeFlag: int) -> bool {
  if entry == 0 { return false }
  for segment in segments {
    if flag(segment.flags, executeFlag) && entry >= segment.address && entry - segment.address < segment.bytes {
      return true
    }
  }
  false
}

function observed(format: string, target: string, data: Bytes, dependencies: Array<string>, sections: Array<Section>, metadata: Array<Field>) -> Result<Image, string> {
  Ok(Image {
    format: format, target: target, bytes: data.length(), sha256: data.sha256().toHex(),
    dependencies: uniqueDependencies(dependencies)?, sections: sections, metadata: metadata,
  })
}

function inspectElf(data: Bytes) -> Result<Image, string> {
  checkedRange(data, 0, 64)?
  if (data.get(4) ?? 0) != 2 || (data.get(5) ?? 0) != 1 || (data.get(6) ?? 0) != 1 {
    return Err("only little-endian ELF64 version 1 is supported")
  }
  let osAbi = data.get(7) ?? 0
  if osAbi != 0 && osAbi != 3 { return Err("ELF OS ABI is outside the Linux profile") }
  let kind = u16(data, 16)?
  let machine = u16(data, 18)?
  let target = if machine == 62 { "x86_64-unknown-linux-gnu" } else if machine == 183 {
    "aarch64-unknown-linux-gnu"
  } else { return Err("ELF machine is not x86_64 or aarch64") }
  if (kind != 2 && kind != 3) || u32(data, 20)? != 1 || u16(data, 52)? != 64 {
    return Err("ELF must have a supported executable header")
  }
  let entry = u64(data, 24)?
  let programOffset = u64(data, 32)?
  let sectionOffset = u64(data, 40)?
  let programCount = u16(data, 56)?
  let sectionCount = u16(data, 60)?
  let namesIndex = u16(data, 62)?
  if programCount < 1 || programCount > 64 || u16(data, 54)? != 56 {
    return Err("ELF program header count or size is unsupported")
  }
  if sectionCount > MAX_SECTIONS || (sectionCount > 0 && u16(data, 58)? != 64) || namesIndex == 65535 {
    return Err("ELF section count, size or extended indexing is unsupported")
  }
  if programOffset < 64 { return Err("ELF program headers overlap the file header") }
  checkedRange(data, programOffset, programCount * 56)?
  let mut segments: Array<Segment> = []
  let mut dynamic = Region { offset: 0, bytes: 0 }
  let mut dynamicAddress = 0
  let mut haveDynamic = false
  let mut interpreter = ""
  let mut index = 0
  while index < programCount {
    let at = programOffset + index * 56
    let kind = u32(data, at)?
    let flags = u32(data, at + 4)?
    let offset = u64(data, at + 8)?
    let address = u64(data, at + 16)?
    let fileBytes = u64(data, at + 32)?
    let memoryBytes = u64(data, at + 40)?
    checkedRange(data, offset, fileBytes)?
    checkedExtent(address, memoryBytes)?
    if kind == 1 {
      if fileBytes > memoryBytes { return Err("ELF load segment is larger than its memory extent") }
      segments.push(Segment { address: address, memoryBytes: memoryBytes, offset: offset, bytes: fileBytes, flags: flags })
    } else if kind == 2 {
      if haveDynamic || fileBytes == 0 || fileBytes > MAX_TABLE_BYTES || fileBytes % 16 != 0 {
        return Err("ELF dynamic table is duplicate, empty, misaligned or too large")
      }
      haveDynamic = true
      dynamic = Region { offset: offset, bytes: fileBytes }
      dynamicAddress = address
    } else if kind == 3 {
      if interpreter != "" || fileBytes == 0 || fileBytes > MAX_STRING_BYTES {
        return Err("ELF interpreter declaration is duplicate, empty or too large")
      }
      interpreter = cString(data, offset, fileBytes)?
      if !interpreter.startsWith("/") { return Err("ELF interpreter is not an absolute path") }
    }
    index += 1
  }
  if !executableEntry(segments, entry, 1) { return Err("ELF entry does not address an executable file-backed load segment") }
  let mut needed: Array<int> = []
  let mut stringAddress = 0
  let mut stringBytes = 0
  let mut haveStringAddress = false
  let mut haveStringBytes = false
  let mut pie = false
  let mut rpathOffset = -1
  let mut runpathOffset = -1
  if haveDynamic {
    let dynamicMapping = mapped(segments, dynamicAddress, dynamic.bytes, 0)?
    if dynamicMapping.offset != dynamic.offset { return Err("ELF dynamic table address and file offset disagree") }
    let mut terminated = false
    index = 0
    while index < dynamic.bytes / 16 {
      let at = dynamic.offset + index * 16
      let tag = u64(data, at)?
      let value = u64(data, at + 8)?
      if tag == 0 { terminated = true; break }
      if tag == 1 {
        if needed.length >= MAX_DEPENDENCIES { return Err("ELF has more than 256 dependency declarations") }
        needed.push(value)
      } else if tag == 5 {
        if haveStringAddress { return Err("ELF repeats DT_STRTAB") }
        haveStringAddress = true
        stringAddress = value
      } else if tag == 10 {
        if haveStringBytes { return Err("ELF repeats DT_STRSZ") }
        haveStringBytes = true
        stringBytes = value
      } else if tag == 15 {
        if rpathOffset >= 0 { return Err("ELF repeats DT_RPATH") }
        rpathOffset = value
      } else if tag == 29 {
        if runpathOffset >= 0 { return Err("ELF repeats DT_RUNPATH") }
        runpathOffset = value
      } else if tag == 1879048187 { pie = flag(value, 134217728) }
      index += 1
    }
    if !terminated { return Err("ELF dynamic table has no DT_NULL terminator") }
  }
  if kind == 3 && interpreter == "" && !pie { return Err("ELF shared image is not marked as a position-independent executable") }
  let mut dependencies: Array<string> = []
  let mut rpath = ""
  let mut runpath = ""
  if haveStringAddress != haveStringBytes ||
    ((needed.length > 0 || rpathOffset >= 0 || runpathOffset >= 0) && (!haveStringAddress || stringBytes == 0)) {
    return Err("ELF dependencies have no complete dynamic string table")
  }
  if haveStringAddress {
    if stringBytes == 0 { return Err("ELF dynamic string table is empty") }
    let strings = mapped(segments, stringAddress, stringBytes, 0)?
    for offset in needed {
      if offset >= stringBytes { return Err("ELF dependency offset exceeds DT_STRSZ") }
      dependencies.push(dependencyName(cString(data, strings.offset + offset, stringBytes - offset)?, false)?)
    }
    if rpathOffset >= 0 {
      if rpathOffset >= stringBytes { return Err("ELF rpath offset exceeds DT_STRSZ") }
      rpath = cString(data, strings.offset + rpathOffset, stringBytes - rpathOffset)?
    }
    if runpathOffset >= 0 {
      if runpathOffset >= stringBytes { return Err("ELF runpath offset exceeds DT_STRSZ") }
      runpath = cString(data, strings.offset + runpathOffset, stringBytes - runpathOffset)?
    }
  }
  let mut sections: Array<Section> = []
  if sectionCount == 0 {
    if sectionOffset != 0 || namesIndex != 0 { return Err("ELF extended section counts are unsupported") }
    index = 0
    for segment in segments {
      sections.push(section(data, sections, "load-{index}", segment.offset, segment.bytes)?)
      index += 1
    }
  } else {
    if sectionOffset < 64 || namesIndex == 0 || namesIndex >= sectionCount { return Err("ELF section name table index is invalid") }
    checkedRange(data, sectionOffset, sectionCount * 64)?
    let namesAt = sectionOffset + namesIndex * 64
    if u32(data, namesAt + 4)? != 3 { return Err("ELF section names do not reference a string table") }
    let nameOffset = u64(data, namesAt + 24)?
    let nameBytes = u64(data, namesAt + 32)?
    checkedRange(data, nameOffset, nameBytes)?
    if nameBytes == 0 { return Err("ELF section name table is empty") }
    index = 1
    while index < sectionCount {
      let at = sectionOffset + index * 64
      let nameAt = u32(data, at)?
      let sectionKind = u32(data, at + 4)?
      let offset = u64(data, at + 24)?
      let size = u64(data, at + 32)?
      if nameAt >= nameBytes { return Err("ELF section name exceeds its string table") }
      let name = cString(data, nameOffset + nameAt, nameBytes - nameAt)?
      if sectionKind != 0 && sectionKind != 8 {
        sections.push(section(data, sections, name, offset, size)?)
      }
      index += 1
    }
  }
  let mut metadata: Array<Field> = [
    Field { name: "targetEvidence", value: "ELF class, endianness, machine and OS ABI; runtime compatibility is not established" },
    Field { name: "elf.osAbi", value: "{osAbi}" },
    Field { name: "elf.type", value: "{kind}" },
    Field { name: "elf.machine", value: "{machine}" },
    Field { name: "elf.entry", value: "{entry}" },
  ]
  if interpreter != "" { metadata.push(Field { name: "elf.interpreter", value: interpreter }) }
  if rpathOffset >= 0 { metadata.push(Field { name: "elf.rpath", value: rpath }) }
  if runpathOffset >= 0 { metadata.push(Field { name: "elf.runpath", value: runpath }) }
  observed("elf", target, data, dependencies, sections, metadata)
}

function peDirectory(data: Bytes, optional: int, count: int, index: int) -> Result<Region, string> {
  if index >= count { return Ok(Region { offset: 0, bytes: 0 }) }
  let offset = u32(data, optional + 112 + index * 8)?
  let size = u32(data, optional + 116 + index * 8)?
  if index == 8 {
    if size != 0 { return Err("PE global pointer directory must have a zero size") }
    return Ok(Region { offset: offset, bytes: 0 })
  }
  if (offset == 0) != (size == 0) { return Err("PE directory must have both an address and a size") }
  Ok(Region { offset: offset, bytes: size })
}

function guid(data: Bytes, offset: int) -> Result<string, string> {
  checkedRange(data, offset, 16)?
  let first = data.slice(offset + 3, offset + 4).toHex() + data.slice(offset + 2, offset + 3).toHex() +
    data.slice(offset + 1, offset + 2).toHex() + data.slice(offset, offset + 1).toHex()
  let second = data.slice(offset + 5, offset + 6).toHex() + data.slice(offset + 4, offset + 5).toHex()
  let third = data.slice(offset + 7, offset + 8).toHex() + data.slice(offset + 6, offset + 7).toHex()
  let fourth = data.slice(offset + 8, offset + 10).toHex()
  let fifth = data.slice(offset + 10, offset + 16).toHex()
  Ok("{first}-{second}-{third}-{fourth}-{fifth}")
}

function peImports(data: Bytes, segments: Array<Segment>, headerBytes: int, imports: Region) -> Result<Array<string>, string> {
  let mut dependencies: Array<string> = []
  if imports.bytes == 0 { return Ok(dependencies) }
  let descriptorBytes = 20
  if imports.bytes < descriptorBytes || imports.bytes > MAX_TABLE_BYTES { return Err("PE import directory has an invalid size") }
  let region = mapped(segments, imports.offset, imports.bytes, headerBytes)?
  let mut index = 0
  while index < imports.bytes / descriptorBytes {
    let at = region.offset + index * descriptorBytes
    let lookupTable = u32(data, at)?
    let timestamp = u32(data, at + 4)?
    let forwarder = u32(data, at + 8)?
    let nameAddress = u32(data, at + 12)?
    let addressTable = u32(data, at + 16)?
    if lookupTable == 0 && timestamp == 0 && forwarder == 0 && nameAddress == 0 && addressTable == 0 {
      return Ok(dependencies)
    }
    if dependencies.length >= MAX_DEPENDENCIES || nameAddress == 0 || addressTable == 0 {
      return Err("PE import descriptor count or fields are invalid")
    }
    mapped(segments, addressTable, 8, headerBytes)?
    if lookupTable != 0 { mapped(segments, lookupTable, 8, headerBytes)? }
    let name = mapped(segments, nameAddress, 1, headerBytes)?
    dependencies.push(dependencyName(cString(data, name.offset, name.bytes)?, true)?)
    index += 1
  }
  Err("PE import directory has no terminating descriptor")
}

function peDebugFields(data: Bytes, segments: Array<Segment>, headerBytes: int, debug: Region) -> Result<Array<Field>, string> {
  let mut metadata: Array<Field> = []
  if debug.bytes == 0 { return Ok(metadata) }
  let entryBytes = 28
  if debug.bytes % entryBytes != 0 || debug.bytes / entryBytes > 64 { return Err("PE debug directory has an invalid entry count or size") }
  let region = mapped(segments, debug.offset, debug.bytes, headerBytes)?
  let mut index = 0
  while index < debug.bytes / entryBytes {
    let at = region.offset + index * entryBytes
    let stamp = u32(data, at + 4)?
    let kind = u32(data, at + 12)?
    let size = u32(data, at + 16)?
    let address = u32(data, at + 20)?
    let offset = u32(data, at + 24)?
    checkedRange(data, offset, size)?
    if size > 0 && address != 0 {
      let inImage = mapped(segments, address, size, headerBytes)?
      if inImage.offset != offset { return Err("PE debug data RVA and file offset disagree") }
    }
    metadata.push(Field { name: "pe.debug.{index}.kind", value: "{kind}" })
    metadata.push(Field { name: "pe.debug.{index}.timestamp", value: "{stamp}" })
    metadata.push(Field { name: "pe.debug.{index}.bytes", value: "{size}" })
    if kind == PE_DEBUG_CODEVIEW {
      if size < 25 || u32(data, offset)? != CODEVIEW_RSDS { return Err("PE CodeView data must contain an RSDS record") }
      let identifier = guid(data, offset + 4)?
      let age = u32(data, offset + 20)?
      let pdb = cString(data, offset + 24, size - 24)?
      metadata.push(Field { name: "pe.debug.{index}.pdbGuid", value: identifier })
      metadata.push(Field { name: "pe.debug.{index}.pdbAge", value: "{age}" })
      metadata.push(Field { name: "pe.debug.{index}.pdbPath", value: pdb })
    } else if kind == PE_DEBUG_REPRO {
      metadata.push(Field { name: "pe.debug.{index}.reproducibleMarker", value: "present; marker presence does not prove reproducibility" })
    }
    index += 1
  }
  Ok(metadata)
}

function inspectPe(data: Bytes) -> Result<Image, string> {
  checkedRange(data, 0, 64)?
  let pe = u32(data, 60)?
  if pe < 64 { return Err("PE header overlaps its DOS header") }
  checkedRange(data, pe, 24)?
  if u32(data, pe)? != 17744 { return Err("PE signature is missing") }
  let machine = u16(data, pe + 4)?
  let target = if machine == 34404 { "x86_64-pc-windows-msvc" } else if machine == 43620 {
    "aarch64-pc-windows-msvc"
  } else { return Err("PE machine is not x86_64 or aarch64") }
  let count = u16(data, pe + 6)?
  let timestamp = u32(data, pe + 8)?
  let optionalBytes = u16(data, pe + 20)?
  let characteristics = u16(data, pe + 22)?
  if count < 1 || count > MAX_SECTIONS || !flag(characteristics, 2) || flag(characteristics, 8192) {
    return Err("PE must be an executable with 1 to 64 sections and not a DLL")
  }
  let optional = pe + 24
  checkedRange(data, optional, optionalBytes)?
  if optionalBytes < 112 || u16(data, optional)? != 523 { return Err("only PE32+ optional headers are supported") }
  let entry = u32(data, optional + 16)?
  let imageBase = u64(data, optional + 24)?
  let headerBytes = u32(data, optional + 60)?
  let checksum = u32(data, optional + 64)?
  let subsystem = u16(data, optional + 68)?
  let directoryCount = u32(data, optional + 108)?
  if directoryCount > 16 || 112 + directoryCount * 8 > optionalBytes {
    return Err("PE directory count exceeds its optional header or supported directory set")
  }
  let table = optional + optionalBytes
  checkedRange(data, table, count * 40)?
  checkedRange(data, 0, headerBytes)?
  if headerBytes < table + count * 40 || headerBytes > MAX_TABLE_BYTES {
    return Err("PE SizeOfHeaders does not cover its section table or exceeds 1 MiB")
  }
  let mut sections: Array<Section> = []
  let mut segments: Array<Segment> = []
  let mut index = 0
  while index < count {
    let at = table + index * 40
    let name = fixedName(data, at, 8)?
    let memoryBytes = u32(data, at + 8)?
    let address = u32(data, at + 12)?
    let size = u32(data, at + 16)?
    let offset = u32(data, at + 20)?
    let flags = u32(data, at + 36)?
    if size > 0 && (offset < headerBytes || address < headerBytes) {
      return Err("PE section overlaps file headers")
    }
    if memoryBytes > 4294967296 - address || size > 4294967296 - address {
      return Err("PE section exceeds the RVA address space")
    }
    let extent = if memoryBytes > size { memoryBytes } else { size }
    for old in segments {
      let oldExtent = if old.memoryBytes > old.bytes { old.memoryBytes } else { old.bytes }
      if extent > 0 && oldExtent > 0 && address < old.address + oldExtent && old.address < address + extent {
        return Err("PE virtual section extents overlap")
      }
    }
    sections.push(section(data, sections, name, offset, size)?)
    segments.push(Segment { address: address, memoryBytes: memoryBytes, offset: offset, bytes: size, flags: flags })
    index += 1
  }
  if !executableEntry(segments, entry, 536870912) { return Err("PE entry does not address an executable file-backed section") }
  let mut metadata: Array<Field> = [
    Field { name: "targetEvidence", value: "PE32+ format and machine; producer ABI and runtime compatibility are not established" },
    Field { name: "pe.timestamp", value: "{timestamp}" },
    Field { name: "pe.machine", value: "{machine}" },
    Field { name: "pe.headersSha256", value: data.slice(0, headerBytes).sha256().toHex() },
    Field { name: "pe.checksum", value: "{checksum}" },
    Field { name: "pe.imageBase", value: "{imageBase}" },
    Field { name: "pe.entryRva", value: "{entry}" },
    Field { name: "pe.subsystem", value: "{subsystem}" },
  ]
  let delay = peDirectory(data, optional, directoryCount, 13)?
  if delay.bytes != 0 { return Err("PE delay imports are not supported by this dependency inspector") }
  // The security directory uses a file offset, unlike the other RVA entries.
  index = 0
  while index < directoryCount {
    let directory = peDirectory(data, optional, directoryCount, index)?
    if directory.bytes > 0 {
      if index == 4 { checkedRange(data, directory.offset, directory.bytes)? }
      else { mapped(segments, directory.offset, directory.bytes, headerBytes)? }
    } else if index == 8 && directory.offset != 0 {
      mapped(segments, directory.offset, 1, headerBytes)?
    }
    index += 1
  }
  let imports = peDirectory(data, optional, directoryCount, 1)?
  let dependencies = peImports(data, segments, headerBytes, imports)?
  let debug = peDirectory(data, optional, directoryCount, 6)?
  for field in peDebugFields(data, segments, headerBytes, debug)? { metadata.push(field) }
  observed("pe", target, data, dependencies, sections, metadata)
}

function inspectMachO(data: Bytes) -> Result<Image, string> {
  checkedRange(data, 0, 32)?
  let machine = u32(data, 4)?
  let target = if machine == 16777223 { "x86_64-apple-darwin" } else if machine == 16777228 {
    "aarch64-apple-darwin"
  } else { return Err("Mach-O CPU is not x86_64 or arm64") }
  if u32(data, 12)? != 2 { return Err("Mach-O must be an MH_EXECUTE image") }
  let count = u32(data, 16)?
  let commandBytes = u32(data, 20)?
  let subtype = u32(data, 8)?
  if count < 1 || count > 4096 || commandBytes > MAX_TABLE_BYTES || count > commandBytes / 8 {
    return Err("Mach-O load command count or table size is invalid")
  }
  checkedRange(data, 32, commandBytes)?
  let mut metadata: Array<Field> = [
    Field { name: "targetEvidence", value: "thin little-endian Mach-O CPU and executable kind; runtime compatibility is not established" },
    Field { name: "macho.cpuType", value: "{machine}" },
    Field { name: "macho.cpuSubtype", value: "{subtype}" },
  ]
  let mut dependencies: Array<string> = []
  let mut sections: Array<Section> = []
  let mut segments: Array<Segment> = []
  let mut haveMain = false
  let mut entry = 0
  let mut havePlatform = false
  let mut haveUuid = false
  let mut haveSignature = false
  let mut haveLinker = false
  let mut declaredSections = 0
  let mut paths = 0
  let mut cursor = 32
  let end = 32 + commandBytes
  let mut index = 0
  while index < count {
    if end - cursor < 8 { return Err("Mach-O load command header exceeds its table") }
    let kind = u32(data, cursor)?
    let size = u32(data, cursor + 4)?
    if size < 8 || size % 8 != 0 || size > end - cursor { return Err("Mach-O load command has an invalid extent") }
    if kind == 25 {
      if size < 72 { return Err("Mach-O LC_SEGMENT_64 is truncated") }
      let segmentName = fixedName(data, cursor + 8, 16)?
      let address = u64(data, cursor + 24)?
      let memoryBytes = u64(data, cursor + 32)?
      let offset = u64(data, cursor + 40)?
      let fileBytes = u64(data, cursor + 48)?
      let protection = u32(data, cursor + 60)?
      let sectionCount = u32(data, cursor + 64)?
      if sectionCount > MAX_SECTIONS || 72 + sectionCount * 80 != size || segments.length >= 64 {
        return Err("Mach-O segment section count or command size is invalid")
      }
      declaredSections += sectionCount
      if declaredSections > MAX_SECTIONS { return Err("Mach-O has more than 64 section declarations") }
      checkedRange(data, offset, fileBytes)?
      checkedExtent(address, memoryBytes)?
      if fileBytes > memoryBytes { return Err("Mach-O segment exceeds its memory extent") }
      segments.push(Segment { address: address, memoryBytes: memoryBytes, offset: offset, bytes: fileBytes, flags: protection })
      let mut sectionIndex = 0
      while sectionIndex < sectionCount {
        let at = cursor + 72 + sectionIndex * 80
        let name = fixedName(data, at, 16)?
        let declaredSegment = fixedName(data, at + 16, 16)?
        let sectionAddress = u64(data, at + 32)?
        let sectionBytes = u64(data, at + 40)?
        let sectionOffset = u32(data, at + 48)?
        let sectionKind = u32(data, at + 64)? % 256
        if declaredSegment != segmentName || sectionAddress < address ||
          sectionAddress - address > memoryBytes || sectionBytes > memoryBytes - (sectionAddress - address) {
          return Err("Mach-O section exceeds its declared segment")
        }
        if sectionKind != 1 && sectionKind != 12 && sectionKind != 18 {
          if sectionOffset < offset || sectionOffset - offset > fileBytes || sectionBytes > fileBytes - (sectionOffset - offset) {
            return Err("Mach-O section exceeds its segment file range")
          }
          sections.push(section(data, sections, "{segmentName}.{name}", sectionOffset, sectionBytes)?)
        }
        sectionIndex += 1
      }
    } else if kind == 12 || kind == 2147483672 || kind == 2147483679 || kind == 32 || kind == 2147483683 {
      if size < 24 || dependencies.length >= MAX_DEPENDENCIES { return Err("Mach-O dylib declaration is truncated or exceeds the dependency limit") }
      let nameOffset = u32(data, cursor + 8)?
      if nameOffset < 24 || nameOffset >= size { return Err("Mach-O dylib name is outside its load command") }
      dependencies.push(dependencyName(cString(data, cursor + nameOffset, size - nameOffset)?, false)?)
    } else if kind == 2147483676 {
      if size < 16 || paths >= 64 { return Err("Mach-O rpath declaration is truncated or exceeds its limit") }
      let pathOffset = u32(data, cursor + 8)?
      if pathOffset < 12 || pathOffset >= size { return Err("Mach-O rpath is outside its load command") }
      metadata.push(Field { name: "macho.rpath.{paths}", value: cString(data, cursor + pathOffset, size - pathOffset)? })
      paths += 1
    } else if kind == 14 {
      if size < 16 || haveLinker { return Err("Mach-O dynamic linker declaration is duplicate or truncated") }
      let nameOffset = u32(data, cursor + 8)?
      if nameOffset < 12 || nameOffset >= size { return Err("Mach-O dynamic linker name is outside its command") }
      let name = cString(data, cursor + nameOffset, size - nameOffset)?
      if !name.startsWith("/") { return Err("Mach-O dynamic linker path is not absolute") }
      haveLinker = true
      metadata.push(Field { name: "macho.dynamicLinker", value: name })
    } else if kind == 2147483688 {
      if size != 24 || haveMain { return Err("Mach-O LC_MAIN is duplicate or has an invalid size") }
      haveMain = true
      entry = u64(data, cursor + 8)?
      metadata.push(Field { name: "macho.entryFileOffset", value: "{entry}" })
    } else if kind == 27 {
      if size != 24 || haveUuid { return Err("Mach-O UUID command is duplicate or has an invalid size") }
      haveUuid = true
      metadata.push(Field { name: "macho.uuid.{index}", value: data.slice(cursor + 8, cursor + 24).toHex() })
    } else if kind == 50 {
      if size < 24 || havePlatform { return Err("Mach-O build version is duplicate or truncated") }
      let platform = u32(data, cursor + 8)?
      let tools = u32(data, cursor + 20)?
      if platform != 1 || tools > 64 || 24 + tools * 8 != size { return Err("Mach-O build version is not a supported macOS declaration") }
      havePlatform = true
      let minimum = u32(data, cursor + 12)?
      let sdk = u32(data, cursor + 16)?
      metadata.push(Field { name: "macho.declaredMinimumOsPacked", value: "{minimum}" })
      metadata.push(Field { name: "macho.declaredSdkPacked", value: "{sdk}" })
    } else if kind == 36 {
      if size != 16 || havePlatform { return Err("Mach-O minimum macOS declaration is duplicate or malformed") }
      havePlatform = true
      let minimum = u32(data, cursor + 8)?
      let sdk = u32(data, cursor + 12)?
      metadata.push(Field { name: "macho.declaredMinimumOsPacked", value: "{minimum}" })
      metadata.push(Field { name: "macho.declaredSdkPacked", value: "{sdk}" })
    } else if kind == 37 || kind == 47 || kind == 48 {
      return Err("Mach-O declares a non-macOS platform")
    } else if kind == 29 || kind == 30 || kind == 38 || kind == 41 || kind == 43 || kind == 46 || kind == 2147483699 || kind == 2147483700 {
      if size != 16 { return Err("Mach-O link-edit data command has an invalid size") }
      let offset = u32(data, cursor + 8)?
      let bytes = u32(data, cursor + 12)?
      checkedRange(data, offset, bytes)?
      if kind == 29 {
        if haveSignature { return Err("Mach-O repeats its code signature command") }
        haveSignature = true
        metadata.push(Field { name: "macho.codeSignatureBytes", value: "{bytes}" })
      }
    } else if kind == 34 || kind == 2147483682 {
      if size != 48 { return Err("Mach-O dyld info command has an invalid size") }
      let mut pair = 0
      while pair < 5 {
        checkedRange(data, u32(data, cursor + 8 + pair * 8)?, u32(data, cursor + 12 + pair * 8)?)?
        pair += 1
      }
    } else if kind == 2 {
      if size != 24 { return Err("Mach-O symbol table command has an invalid size") }
      checkedRange(data, u32(data, cursor + 8)?, u32(data, cursor + 12)? * 16)?
      checkedRange(data, u32(data, cursor + 16)?, u32(data, cursor + 20)?)?
    } else if kind == 11 {
      if size != 80 { return Err("Mach-O dynamic symbol table command has an invalid size") }
      let widths = [8, 56, 4, 4, 8, 8]
      let mut pair = 0
      while pair < 6 {
        checkedRange(data, u32(data, cursor + 32 + pair * 8)?, u32(data, cursor + 36 + pair * 8)? * widths[pair])?
        pair += 1
      }
    } else if kind == 44 {
      if size != 24 { return Err("Mach-O encryption info command has an invalid size") }
      checkedRange(data, u32(data, cursor + 8)?, u32(data, cursor + 12)?)?
      if u32(data, cursor + 16)? != 0 { return Err("encrypted Mach-O executables are unsupported") }
    } else if kind == 49 {
      if size != 40 { return Err("Mach-O note command has an invalid size") }
      checkedRange(data, u64(data, cursor + 24)?, u64(data, cursor + 32)?)?
    } else if kind == 1 || kind == 6 || kind == 16 || kind == 39 || kind >= 2147483648 {
      return Err("Mach-O has an unsupported loader command")
    }
    cursor += size
    index += 1
  }
  if cursor != end { return Err("Mach-O load commands do not fill their declared table") }
  if !havePlatform { return Err("Mach-O has no supported macOS platform declaration") }
  if !haveMain { return Err("Mach-O executable has no supported LC_MAIN entry command") }
  let mut executable = false
  for segment in segments {
    if flag(segment.flags, 4) && entry >= segment.offset && entry - segment.offset < segment.bytes { executable = true }
  }
  if !executable { return Err("Mach-O entry does not address an executable file-backed segment") }
  observed("macho", target, data, dependencies, sections, metadata)
}

export function inspectBytes(data: Bytes) -> Result<Image, string> {
  if data.length() < 4 || data.length() > MAX_IMAGE_BYTES {
    return Err("binary must be between 4 bytes and 512 MiB")
  }
  let magic = u32(data, 0)?
  if magic == 1179403647 { return inspectElf(data) }
  if (data.get(0) ?? 0) == 77 && (data.get(1) ?? 0) == 90 { return inspectPe(data) }
  if magic == 4277009103 { return inspectMachO(data) }
  Err("unsupported executable format; expected ELF64, PE32+ or a thin little-endian 64-bit Mach-O")
}

export function inspectImage(path: string) -> Result<Image, string> {
  // The public filesystem ABI reads a whole Bytes value. The 512 MiB limit is
  // enforced after that read, not advertised as a pre-allocation safeguard.
  inspectBytes(files.readBytes(path)?)
}

import std.bytes { Bytes }
import std.fs as files
import std.io as io
import std.json as json
import src.contracts { Capture, Native, fileMetadata }
import src.download_catalog { Download, encode as encodeCatalogue, inputSetId, validatePublication }
import src.payload_files { MANIFEST_NAME, PayloadFile, portablePath }
import src.release_archive { ArchiveEntry, MAX_TAR_BYTES, encode as encodeArchive }
import src.release_image { inspectImage }
import src.release_payload { Verified, approve }

record PlannedMember {
  record: PayloadFile,
  source: string,
  mode: string,
}

record PackageRecord derives JSON {
  schema: string,
  evidence: string,
  declaredSourceCommit: string,
  inputSetSha256: string,
  target: string,
  repository: string,
  tag: string,
  recipe: string,
  recipeSha256: string,
  requestSha256: string,
  generatedRustSha256: string,
  assetName: string,
  assetBytes: int,
  assetSha256: string,
  executableBytes: int,
  executableSha256: string,
}

function modeFor(verified: Verified, name: string) -> Result<string, string> {
  if name == "assembly.json" || name == MANIFEST_NAME { return Ok("0644") }
  for file in verified.assembly.files { if file.path == name { return Ok(file.mode) } }
  Err("verified release file has no recorded mode: {name}")
}

function requireFirstRunDependencies(verified: Verified, plan: PlannedMember) -> Result<(), string> {
  let image = inspectImage(plan.source)?
  if image.bytes != plan.record.bytes || image.sha256 != plan.record.sha256 {
    return Err("release executable bytes changed before the download startup check")
  }
  let mut system: Set<string> = set {}
  for name in verified.assembly.systemDependencies { system.add(name) }
  for name in image.dependencies {
    if !system.contains(name) {
      return Err("download first run cannot use bundled runtime dependency {name}; the installer starts the executable before unpacking companions")
    }
  }
  Ok(())
}

function members(verified: Verified, native: Native) -> Result<Array<ArchiveEntry>, string> {
  let mut records: Array<PayloadFile> = []
  for file in verified.contents { records.push(file) }
  records.push(verified.manifest)
  if records.length == 0 || records.length > 256 { return Err("release package exceeds its member count limit") }
  let mut plans: Array<PlannedMember> = []
  let mut total = 1024
  // Check every file's metadata and the complete tar extent before reading
  // any member into an archive buffer. No file or cumulative bound relies
  // on a claim made only inside payload.json.
  for record in records {
    portablePath(record.path)?
    if record.path.contains("/") || record.path.startsWith(".") || record.path.byteLength() > 100 {
      return Err("release archive requires flat visible filenames of at most 100 ASCII bytes")
    }
    let meta = fileMetadata("{verified.directory}/{record.path}", native)?
    if meta.bytes <= 0 || meta.bytes != record.bytes || meta.bytes > MAX_TAR_BYTES {
      return Err("release file size changed after verification: {record.path}")
    }
    let extent = 512 + meta.bytes + (512 - meta.bytes % 512) % 512
    if extent > MAX_TAR_BYTES - total { return Err("complete release tar exceeds 256 MiB") }
    total += extent
    let mode = modeFor(verified, record.path)?
    if (meta.mode == "" && mode != "0644") || (meta.mode != "" && meta.mode != mode) {
      return Err("release file mode changed after verification: {record.path}")
    }
    plans.push(PlannedMember { record: record, source: meta.path, mode: mode })
  }
  // Assembly can carry runtime companions, but the download adapter starts
  // only the executable. Inspect its imports after all size preflights and
  // before archive construction, including explicit installed-byte checking.
  for plan in plans {
    if plan.record.path == verified.assembly.executable {
      requireFirstRunDependencies(verified, plan)?
    }
  }
  let mut entries: Array<ArchiveEntry> = []
  for plan in plans {
    let bytes = files.readBytes(plan.source)?
    if bytes.length() != plan.record.bytes || bytes.sha256().toHex() != plan.record.sha256 {
      return Err("release file bytes changed after verification: {plan.record.path}")
    }
    entries.push(ArchiveEntry { path: plan.record.path, mode: plan.mode, bytes: bytes })
  }
  Ok(entries)
}

function executableRecord(verified: Verified) -> Result<PayloadFile, string> {
  for record in verified.contents {
    if record.path == verified.assembly.executable { return Ok(record) }
  }
  Err("verified payload omits its executable record")
}

export function archiveBytes(verified: Verified, native: Native) -> Result<Bytes, string> {
  encodeArchive(members(verified, native)?)
}

function writeChecked(directory: string, name: string, bytes: Bytes, native: Native) -> Result<(), string> {
  let destination = "{directory}/{name}"
  files.writeBytes(destination, bytes)?
  native("set-file-mode", [destination, "0644"])?
  let meta = fileMetadata(destination, native)?
  if meta.bytes != bytes.length() || (meta.mode != "" && meta.mode != "0644") {
    return Err("written release file has different metadata: {name}")
  }
  let actual = files.readBytes(destination)?
  if actual != bytes { return Err("written release file differs from its prepared bytes: {name}") }
  Ok(())
}

export function pack(
  root: string, first: string, second: string, output: string,
  repository: string, tag: string, sourceCommit: string, native: Native, capture: Capture,
) -> Result<int, string> {
  validatePublication(repository, tag, sourceCommit)?
  let inputSet = inputSetId(root)?
  let verified = approve(root, first, second, native, capture)?
  let packed = archiveBytes(verified, native)?
  let executable = executableRecord(verified)?
  let download = Download {
    target: verified.assembly.target, repository: repository, tag: tag,
    sourceCommit: sourceCommit, inputSetSha256: inputSet,
    assetName: "topaz-core-kit-{verified.assembly.target}.tar.gz",
    assetBytes: packed.length(), assetSha256: packed.sha256().toHex(),
    executableBytes: executable.bytes, executableSha256: executable.sha256,
  }
  let catalogueText = encodeCatalogue([download])?
  let record = PackageRecord {
    schema: "topaz.core-kit-package/v1", evidence: "equal-candidates-with-native-checks",
    declaredSourceCommit: sourceCommit, inputSetSha256: inputSet,
    target: download.target, repository: repository, tag: tag,
    recipe: verified.loaded.path, recipeSha256: verified.loaded.sha256,
    requestSha256: verified.assembly.requestSha256,
    generatedRustSha256: verified.assembly.generatedRustSha256,
    assetName: download.assetName, assetBytes: download.assetBytes,
    assetSha256: download.assetSha256,
    executableBytes: download.executableBytes, executableSha256: download.executableSha256,
  }
  let recordText = "{json.stringify(record)?}\n"
  if inputSet != inputSetId(root)? { return Err("repository input set changed during release packaging") }
  // All policy checks and archive construction precede destination creation.
  // The catalogue is emitted beside the archive and never embedded in it.
  native("mkdir-parent", [output])?
  let directory = native("mkdir-new", [output])?
  writeChecked(directory, download.assetName, packed, native)?
  writeChecked(directory, "downloads.data", catalogueText.encodeUtf8(), native)?
  writeChecked(directory, "package.json", recordText.encodeUtf8(), native)?
  io.writeLine("Verified release archive and catalogue row written to {directory}")
  io.writeLine("The source commit is a publisher declaration; the input-set digest records the checked repository bytes.")
  io.writeLine("Retain independent build records and publish these reviewed files through GitHub Releases.")
  Ok(0)
}

