record ManifestTarget derives JSON {
  target: string,
  executable: string,
}

function parentDirectory(file: FileMetadata) -> Result<string, string> {
  let mut parts = file.path.split("/")
  parts.pop()
  let directory = parts.join("/")
  if directory == "" || directory.endsWith(":") {
    return Err("a payload must use a directory below the filesystem root")
  }
  Ok(directory)
}

function regularFile(directory: string, name: string) -> Result<string, string> {
  for entry in files.list(directory)? {
    if entry.name == name {
      if entry.kind != "file" { return Err("payload/build input must be a regular file: {name}") }
      return Ok("{directory}/{name}")
    }
  }
  Err("required payload/build file is missing: {name}")
}

function readText(path: string, maximum: int, native: Native) -> Result<string, string> {
  let meta = fileMetadata(path, native)?
  if meta.bytes == 0 || meta.bytes > maximum { return Err("text input has an invalid size: {path}") }
  let text = files.readText(meta.path)?
  if text.byteLength() != meta.bytes { return Err("text input changed while being read: {path}") }
  Ok(text)
}

function fileMode(recipe: ReleaseRecipe, path: string) -> string {
  if path == recipe.executable && recipe.format != "pe" { "0755" } else { "0644" }
}

function checkMode(path: string, expected: string, native: Native) -> Result<(), string> {
  let meta = fileMetadata(path, native)?
  if meta.mode == "" {
    if expected == "0755" { return Err("this host cannot validate the required Unix executable mode") }
  } else if meta.mode != expected {
    return Err("payload mode differs from its assembly record: {path}")
  }
  Ok(())
}

function normalizedRequest(root: string) -> Result<string, string> {
  encode(fromText(kitInputs.prepare(root)?)?, "rust-source")
}

function expectedFiles(recipe: ReleaseRecipe) -> Array<AssemblyFile> {
  let mut names = [recipe.executable, GENERATED_NAME]
  for mapping in recipe.files { names.push(mapping.destination) }
  names.sort()
  let mut output: Array<AssemblyFile> = []
  for name in names {
    let mut role = if name == recipe.executable { "executable" } else { "generated-source" }
    for mapping in recipe.files { if mapping.destination == name { role = mapping.role } }
    output.push(AssemblyFile { path: name, role: role, mode: fileMode(recipe, name) })
  }
  output
}

function dependencies(recipe: ReleaseRecipe, image: Image) -> Result<Array<string>, string> {
  if image.target != recipe.target || image.format != recipe.format {
    return Err("executable format or machine differs from the platform recipe")
  }
  let mut allowed: Set<string> = set {}
  for name in recipe.allowedSystemDependencies { allowed.add(name) }
  let mut bundled: Set<string> = set {}
  for mapping in recipe.files {
    if mapping.role == "runtime" {
      bundled.add(if recipe.format == "pe" { portablePath(mapping.destination)? } else { mapping.destination })
    }
  }
  let mut system: Array<string> = []
  for name in image.dependencies {
    if allowed.contains(name) {
      system.push(name)
    } else if !bundled.contains(name) {
      return Err("executable imports an unclassified runtime dependency: {name}")
    }
  }
  for field in image.metadata {
    if field.name == "elf.interpreter" {
      let parts = field.value.split("/")
      let name = parts[parts.length - 1]
      let expected = if recipe.target == "x86_64-unknown-linux-gnu" {
        "/lib64/ld-linux-x86-64.so.2"
      } else {
        "/lib/ld-linux-aarch64.so.1"
      }
      if field.value != expected { return Err("ELF interpreter path is outside the supported release profile: {field.value}") }
      if !allowed.contains(name) { return Err("ELF interpreter is not classified by the platform recipe: {field.value}") }
    }
    if field.name == "macho.dynamicLinker" && field.value != "/usr/lib/dyld" {
      return Err("Mach-O dynamic loader is outside the supported release profile")
    }
    if field.name == "elf.rpath" || field.name == "elf.runpath" || field.name.startsWith("macho.rpath.") {
      return Err("this recipe does not admit embedded runtime search paths: {field.value}")
    }
  }
  system.sort()
  Ok(system)
}

function planned(file: AssemblyFile, source: string, limit: int, native: Native) -> Result<PlannedFile, string> {
  let meta = fileMetadata(source, native)?
  if meta.bytes == 0 || meta.bytes > limit {
    return Err("payload file must be nonempty and no larger than its limit of {limit} bytes: {file.path}")
  }
  let bytes = files.readBytes(meta.path)?
  if bytes.length() != meta.bytes { return Err("payload input changed while being read: {source}") }
  Ok(PlannedFile { file: file, source: meta.path, bytes: meta.bytes, sha256: bytes.sha256().toHex() })
}

function copyPlanned(directory: string, plan: PlannedFile, native: Native) -> Result<(), string> {
  let destination = "{directory}/{plan.file.path}"
  native("copy-file", [plan.source, destination])?
  native("set-file-mode", [destination, plan.file.mode])?
  let bytes = files.readBytes(destination)?
  if bytes.length() != plan.bytes || bytes.sha256().toHex() != plan.sha256 {
    return Err("copied payload input changed during assembly: {plan.file.path}")
  }
  checkMode(destination, plan.file.mode, native)
}

function encoded(assembly: Assembly) -> Result<string, string> {
  Ok("{json.stringify(assembly)?}\n")
}

function requireAssemblyMembership(contents: Array<PayloadFile>, expected: Array<AssemblyFile>, limit: int) -> Result<(), string> {
  if contents.length != expected.length + 1 { return Err("assembled payload file membership differs from its recipe") }
  let mut seen: Set<string> = set {}
  for file in expected { seen.add(file.path) }
  seen.add(ASSEMBLY_NAME)
  for file in contents {
    if !seen.contains(file.path) || file.bytes == 0 || file.bytes > limit {
      return Err("assembled payload contains an unexpected, empty or oversized file: {file.path}")
    }
  }
  Ok(())
}

function preflightMembers(directory: string, expected: Array<AssemblyFile>, limit: int, native: Native) -> Result<(), string> {
  let mut names: Set<string> = set {}
  for file in expected { names.add(file.path) }
  names.add(ASSEMBLY_NAME)
  names.add(MANIFEST_NAME)
  let entries = files.list(directory)?
  if entries.length != names.length { return Err("assembled payload file membership differs from its recipe") }
  let mut tarBytes = 1024
  for entry in entries {
    if entry.kind != "file" || !names.contains(entry.name) {
      return Err("assembled payload has an unexpected file or nonregular entry: {entry.name}")
    }
    let meta = fileMetadata("{directory}/{entry.name}", native)?
    let maximum = if entry.name == ASSEMBLY_NAME || entry.name == MANIFEST_NAME { 1048576 } else { limit }
    if meta.bytes == 0 || meta.bytes > maximum {
      return Err("assembled payload contains an empty or oversized file: {entry.name}")
    }
    let extent = 512 + meta.bytes + (512 - meta.bytes % 512) % 512
    if extent > MAX_TAR_BYTES - tarBytes { return Err("complete assembled payload tar would exceed 256 MiB") }
    tarBytes += extent
  }
  Ok(())
}

export function verifyAssembled(root: string, requested: string, native: Native) -> Result<Verified, string> {
  let assemblyPath = regularFile(requested, ASSEMBLY_NAME)?
  let directory = parentDirectory(fileMetadata(assemblyPath, native)?)?
  let text = readText(assemblyPath, 1048576, native)?
  let assembly = json.parseAs<Assembly>(text)?
  if assembly.schema != ASSEMBLY_SCHEMA || assembly.evidence != "assembled-candidate" ||
    assembly.compilerSourceSetId != COMPILER_SOURCE_SET || text != encoded(assembly)? {
    return Err("assembly.json has an unsupported contract or noncanonical representation")
  }
  let loaded = loadRecipe(root, assembly.recipe)?
  let recipe = loaded.recipe
  if assembly.recipeSha256 != loaded.sha256 || assembly.target != recipe.target ||
    assembly.executable != recipe.executable || assembly.format != recipe.format ||
    assembly.minimumPlatform != recipe.minimumPlatform {
    return Err("assembly record differs from its checked-in platform recipe")
  }
  let expected = expectedFiles(recipe)
  if json.stringify(assembly.files)? != json.stringify(expected)? {
    return Err("assembly file roles or modes differ from the recipe")
  }
  preflightMembers(directory, expected, recipe.fileByteLimit, native)?
  let manifestPath = regularFile(directory, MANIFEST_NAME)?
  let manifestText = readText(manifestPath, 1048576, native)?
  let manifestTarget = json.parseAs<ManifestTarget>(manifestText)?
  if manifestTarget.target != recipe.target || manifestTarget.executable != recipe.executable {
    return Err("payload manifest target differs from its assembly recipe")
  }
  let currentRequest = normalizedRequest(root)?
  if assembly.requestSha256 != currentRequest.encodeUtf8().sha256().toHex() {
    return Err("assembly compiler input differs from the current CLI sources")
  }
  let generated = regularFile(directory, GENERATED_NAME)?
  let generatedMeta = fileMetadata(generated, native)?
  if generatedMeta.bytes == 0 || generatedMeta.bytes > recipe.fileByteLimit {
    return Err("assembled generated Rust has an invalid size")
  }
  let generatedBytes = files.readBytes(generated)?
  if generatedBytes.sha256().toHex() != assembly.generatedRustSha256 {
    return Err("assembled generated CLI Rust differs from its record")
  }
  let executable = regularFile(directory, recipe.executable)?
  let meta = fileMetadata(executable, native)?
  if meta.bytes == 0 || meta.bytes > recipe.fileByteLimit {
    return Err("assembled executable exceeds its payload file limit")
  }
  let image = inspectImage(executable)?
  let system = dependencies(recipe, image)?
  if json.stringify(system)? != json.stringify(assembly.systemDependencies)? {
    return Err("assembled executable dependencies differ from its record")
  }
  verifyPayload(root, directory)?
  let contents = payloadFiles(directory, recipe.executable, true)?
  requireAssemblyMembership(contents, expected, recipe.fileByteLimit)?
  for file in expected { checkMode("{directory}/{file.path}", file.mode, native)? }
  checkMode("{directory}/{ASSEMBLY_NAME}", "0644", native)?
  checkMode("{directory}/{MANIFEST_NAME}", "0644", native)?
  for mapping in recipe.files {
    let original = files.readBytes("{root}/{mapping.source}")?
    let copied = files.readBytes("{directory}/{mapping.destination}")?
    if original != copied { return Err("assembled companion differs from its repository input: {mapping.destination}") }
  }
  if manifestText != readText(manifestPath, 1048576, native)? {
    return Err("payload manifest changed while the candidate was inspected")
  }
  let manifest = PayloadFile {
    path: MANIFEST_NAME, bytes: manifestText.byteLength(),
    sha256: manifestText.encodeUtf8().sha256().toHex(),
  }
  Ok(Verified { directory: directory, loaded: loaded, assembly: assembly, contents: contents, manifest: manifest })
}

export function assemble(root: string, build: string, recipePath: string, output: string, native: Native) -> Result<int, string> {
  let loaded = loadRecipe(root, recipePath)?
  let recipe = loaded.recipe
  validateRecordedInputs(root)?
  let requestPath = regularFile(build, "cli.request.json")?
  let request = encode(fromText(readText(requestPath, 134217728, native)?)?, "rust-source")?
  let expectedRequest = normalizedRequest(root)?
  if request != expectedRequest { return Err("build input does not describe the current CLI sources") }
  let generatedPath = regularFile(build, GENERATED_NAME)?
  let generated = readText(generatedPath, recipe.fileByteLimit, native)?
  let responsePath = regularFile(build, "cli.response.json")?
  let response = readText(responsePath, 134217728, native)?
  if rustSource(completed(response, "rust-source")?)? != generated {
    return Err("generated CLI Rust differs from the recorded successful compiler response")
  }
  let executable = regularFile(build, recipe.executable)?
  let executableMeta = fileMetadata(executable, native)?
  if executableMeta.bytes == 0 || executableMeta.bytes > recipe.fileByteLimit {
    return Err("executable is {executableMeta.bytes} bytes; this payload profile permits at most {recipe.fileByteLimit} bytes")
  }
  let image = inspectImage(executable)?
  let system = dependencies(recipe, image)?
  let expected = expectedFiles(recipe)
  let mut plan: Array<PlannedFile> = []
  for file in expected {
    let mut source = if file.path == recipe.executable { executable } else { generatedPath }
    for mapping in recipe.files { if file.path == mapping.destination { source = "{root}/{mapping.source}" } }
    plan.push(planned(file, source, recipe.fileByteLimit, native)?)
  }
  let assembly = Assembly {
    schema: ASSEMBLY_SCHEMA, evidence: "assembled-candidate", compilerSourceSetId: COMPILER_SOURCE_SET,
    target: recipe.target, executable: recipe.executable, format: recipe.format,
    recipe: loaded.path, recipeSha256: loaded.sha256,
    requestSha256: request.encodeUtf8().sha256().toHex(),
    generatedRustSha256: generated.encodeUtf8().sha256().toHex(),
    systemDependencies: system, minimumPlatform: recipe.minimumPlatform, files: expected,
  }
  // Admission completes before creating the exclusively owned destination.
  native("mkdir-parent", [output])?
  let directory = native("mkdir-new", [output])?
  for file in plan { copyPlanned(directory, file, native)? }
  files.writeText("{directory}/{ASSEMBLY_NAME}", encoded(assembly)?)?
  native("set-file-mode", ["{directory}/{ASSEMBLY_NAME}", "0644"])?
  recordPayload(root, directory, recipe.target)?
  native("set-file-mode", ["{directory}/{MANIFEST_NAME}", "0644"])?
  verifyAssembled(root, directory, native)?
  io.writeLine("Assembled complete candidate at {directory}")
  if !recipe.releaseReady {
    io.writeLine("The selected recipe is for development evidence and is not approved for release publication.")
  }
  Ok(0)
}

function compareCandidates(root: string, first: string, second: string, native: Native) -> Result<Verified, string> {
  let left = verifyAssembled(root, first, native)?
  let right = verifyAssembled(root, second, native)?
  if left.directory == right.directory { return Err("payload comparison requires two distinct directories") }
  if encoded(left.assembly)? != encoded(right.assembly)? {
    return Err("candidate assembly records differ")
  }
  if json.stringify(left.contents)? != json.stringify(right.contents)? ||
    json.stringify(left.manifest)? != json.stringify(right.manifest)? {
    return Err("candidate recorded inventories differ")
  }
  let mut records: Array<PayloadFile> = []
  for file in left.contents { records.push(file) }
  records.push(left.manifest)
  for record in records {
    let beforePath = "{left.directory}/{record.path}"
    let afterPath = "{right.directory}/{record.path}"
    let beforeMeta = fileMetadata(beforePath, native)?
    let afterMeta = fileMetadata(afterPath, native)?
    if beforeMeta.bytes != record.bytes || afterMeta.bytes != record.bytes {
      return Err("candidate size changed during comparison: {record.path}")
    }
    let before = files.readBytes(beforePath)?
    let after = files.readBytes(afterPath)?
    if before.length() != record.bytes || before.sha256().toHex() != record.sha256 || before != after {
      return Err("complete candidate bytes differ or changed: {record.path}")
    }
  }
  io.writeLine("Complete candidate files, manifests and required modes match.")
  io.writeLine("Retain the independent build and platform test records; directory names alone do not prove independent construction.")
  Ok(left)
}

export function compare(root: string, first: string, second: string, native: Native) -> Result<int, string> {
  compareCandidates(root, first, second, native)?
  Ok(0)
}

function runCheck(executable: string, arguments: Array<string>, root: string, capture: Capture) -> Result<string, string> {
  let result = json.parseAs<CapturedOutput>(capture(
    executable, arguments, root, ["TOPAZ_CORE_KIT_ROOT={root}"],
  )?)?
  if result.code != 0 {
    return Err("candidate execution check failed with exit {result.code}\n{result.stderr}")
  }
  if result.stdout.byteLength() > 1048576 || result.stderr.byteLength() > 1048576 {
    return Err("candidate execution produced excessive output")
  }
  Ok(result.stdout)
}

function sameVerified(before: Verified, after: Verified) -> Result<(), string> {
  if before.directory != after.directory || encoded(before.assembly)? != encoded(after.assembly)? ||
    json.stringify(before.contents)? != json.stringify(after.contents)? ||
    json.stringify(before.manifest)? != json.stringify(after.manifest)? {
    return Err("candidate changed after its recorded verification")
  }
  Ok(())
}

export function checkNative(root: string, verified: Verified, native: Native, capture: Capture) -> Result<Verified, string> {
  let current = verifyAssembled(root, verified.directory, native)?
  sameVerified(verified, current)?
  let recipe = current.loaded.recipe
  if !recipe.releaseReady { return Err("platform recipe is not approved for release use") }
  let target = json.parseAs<BuildTarget>(native("build-target", [])?)?
  if target.target != recipe.target { return Err("candidate execution checks require a native Kit for its target") }
  let executable = "{current.directory}/{recipe.executable}"
  let version = runCheck(executable, ["--version"], root, capture)?
  if version != "{VERSION}\n" { return Err("candidate returned a different Core Kit version") }
  runCheck(executable, ["check", "--source", "{root}/examples/core-kit/hello.tpz"], root, capture)?
  runCheck(executable, ["check", "--root", "{root}/examples/core-kit/project"], root, capture)?
  runCheck(executable, ["kit", "verify"], root, capture)?
  // Revalidate after executing the candidate. Never regenerate its inventory.
  let after = verifyAssembled(root, current.directory, native)?
  sameVerified(current, after)?
  Ok(after)
}

export function approve(root: string, first: string, second: string, native: Native, capture: Capture) -> Result<Verified, string> {
  let verified = compareCandidates(root, first, second, native)?
  let checked = checkNative(root, verified, native, capture)?
  let executable = "{checked.directory}/{checked.loaded.recipe.executable}"
  let buildId = match runCheck(executable, ["kit", "build-id"], root, capture) {
    case Ok(output) => output
    case Err(error) => return Err("cannot read the candidate's linked CLI build ID; rebuild with a Kit that supports kit build-id:\n{error}")
  }
  if buildId != "{checked.assembly.generatedRustSha256}\n" {
    return Err("the candidate executable was not linked from the recorded generated_cli.rs; rebuild in a fresh output directory and reassemble the candidates")
  }
  let after = compareCandidates(root, first, second, native)?
  sameVerified(checked, after)?
  Ok(after)
}

export function copyVerified(root: string, verified: Verified, output: string, native: Native) -> Result<Verified, string> {
  let current = verifyAssembled(root, verified.directory, native)?
  sameVerified(verified, current)?
  let recipe = current.loaded.recipe
  let mut plans: Array<PlannedFile> = []
  for file in current.contents {
    let role = if file.path == recipe.executable { "executable" } else { "companion" }
    let plan = planned(
      AssemblyFile { path: file.path, role: role, mode: fileMode(recipe, file.path) },
      "{current.directory}/{file.path}", recipe.fileByteLimit, native,
    )?
    if plan.bytes != file.bytes || plan.sha256 != file.sha256 {
      return Err("candidate changed before staging: {file.path}")
    }
    plans.push(plan)
  }
  let manifestPlan = planned(
    AssemblyFile { path: MANIFEST_NAME, role: "manifest", mode: "0644" },
    "{current.directory}/{MANIFEST_NAME}", recipe.fileByteLimit, native,
  )?
  if manifestPlan.bytes != current.manifest.bytes || manifestPlan.sha256 != current.manifest.sha256 {
    return Err("candidate manifest changed before staging")
  }
  plans.push(manifestPlan)
  // Complete all reads before creating an exclusively owned destination.
  native("mkdir-parent", [output])?
  let destination = native("mkdir-new", [output])?
  // A failed copy leaves the owned directory for inspection. No earlier
  // installed version or release candidate is overwritten.
  for plan in plans { if plan.file.path != recipe.executable { copyPlanned(destination, plan, native)? } }
  for plan in plans { if plan.file.path == recipe.executable { copyPlanned(destination, plan, native)? } }
  let compared = compareCandidates(root, current.directory, destination, native)?
  sameVerified(current, compared)?
  verifyAssembled(root, destination, native)
}

export function promote(root: string, first: string, second: string, output: string, native: Native, capture: Capture) -> Result<int, string> {
  let approved = approve(root, first, second, native, capture)?
  let staged = copyVerified(root, approved, output, native)?
  io.writeLine("Verified candidate bytes staged unchanged at {staged.directory}")
  io.writeLine("Keep release artifacts outside Git and publish the reviewed package through GitHub Releases.")
  Ok(0)
}

import std.bytes { Bytes }
import std.fs as files
import std.json as json
import src.payload_files { portablePath, repositoryFiles, requireRegularInput }

export const RECIPE_SCHEMA = "topaz.core-kit-release-recipe/v2"
export const PAYLOAD_FILE_BYTE_LIMIT = 268435456

export record ReleaseFile derives JSON {
  source: string,
  destination: string,
  role: string,
}

export record ReleaseRecipe derives JSON {
  schema: string,
  target: string,
  executable: string,
  format: string,
  minimumPlatform: string,
  allowedSystemDependencies: Array<string>,
  files: Array<ReleaseFile>,
  fileByteLimit: int,
  releaseReady: bool,
}

export record LoadedRecipe {
  path: string,
  text: string,
  sha256: string,
  recipe: ReleaseRecipe,
}

// These existing texts retain their own scope and terms. The component and
// notice-scope records describe the distinction from the website distribution;
// this mapping does not assign licenses to newly added implementation files.
function requiredFiles() -> Array<ReleaseFile> {
  [
    ReleaseFile { source: "BINARY-LICENSE.txt", destination: "BINARY-LICENSE.txt", role: "notice" },
    ReleaseFile { source: "LICENSE", destination: "LICENSE", role: "notice" },
    ReleaseFile { source: "LICENSE-COMPONENTS.txt", destination: "LICENSE-COMPONENTS.txt", role: "notice" },
    ReleaseFile { source: "NOTICE", destination: "NOTICE", role: "notice" },
    ReleaseFile { source: "SOURCE-COMPONENTS.json", destination: "SOURCE-COMPONENTS.json", role: "component" },
    ReleaseFile { source: "THIRD-PARTY-LICENSES.txt", destination: "THIRD-PARTY-LICENSES.txt", role: "notice" },
    ReleaseFile { source: "THIRD-PARTY-NOTICES.md", destination: "THIRD-PARTY-NOTICES.md", role: "notice" },
    ReleaseFile { source: "compiler/seed/runtime.json", destination: "SEED-RUNTIME.json", role: "component" },
    ReleaseFile { source: "core-kit/UPSTREAM-PORT.md", destination: "UPSTREAM-PORT.md", role: "component" },
    ReleaseFile { source: "core-kit/distribution/COMPONENTS.json", destination: "COMPONENTS.json", role: "component" },
    ReleaseFile { source: "core-kit/distribution/NOTICE-SCOPE.md", destination: "NOTICE-SCOPE.md", role: "component" },
    ReleaseFile { source: "core-kit/distribution/RUST-STDLIB-NOTICES.html", destination: "RUST-STDLIB-NOTICES.html", role: "notice" },
    ReleaseFile { source: "core-kit/distribution/RUST-STDLIB-PROVENANCE.json", destination: "RUST-STDLIB-PROVENANCE.json", role: "component" },
  ]
}

function targetContract(recipe: ReleaseRecipe) -> Result<(), string> {
  let format = match recipe.target {
    case "x86_64-unknown-linux-gnu" | "aarch64-unknown-linux-gnu" => "elf"
    case "x86_64-pc-windows-msvc" | "aarch64-pc-windows-msvc" => "pe"
    case "x86_64-apple-darwin" | "aarch64-apple-darwin" => "macho"
    case _ => return Err("release recipe target is not mapped by the repository launchers")
  }
  let executable = if format == "pe" { "topaz-core-kit.exe" } else { "topaz-core-kit" }
  if recipe.format != format || recipe.executable != executable {
    return Err("release recipe target, format and executable do not agree")
  }
  if recipe.fileByteLimit != PAYLOAD_FILE_BYTE_LIMIT {
    return Err("release recipe must enforce the 256 MiB payload file limit")
  }
  if recipe.minimumPlatform.byteLength() == 0 || recipe.minimumPlatform.byteLength() > 2048 {
    return Err("release recipe requires a bounded platform description")
  }
  for byte in recipe.minimumPlatform.encodeUtf8().toArray() {
    if byte < 32 || byte == 127 { return Err("release platform description must be one plain-text line") }
  }
  Ok(())
}

function dependencyKey(name: string, format: string) -> Result<string, string> {
  if name.byteLength() == 0 || name.byteLength() > 512 {
    return Err("release system dependency name is empty or too long")
  }
  if format == "macho" {
    if !name.startsWith("/usr/lib/") && !name.startsWith("/System/Library/") {
      return Err("Mach-O system dependencies must use absolute /usr/lib/ or /System/Library/ install names")
    }
    return portablePath(name.slice(1, name.scalars().length))
  }
  if name == "." || name == ".." || name.endsWith(".") {
    return Err("invalid release system dependency name")
  }
  let mut folded: Array<int> = []
  for byte in name.encodeUtf8().toArray() {
    let letter = (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122)
    let digit = byte >= 48 && byte <= 57
    if !letter && !digit && byte != 95 && byte != 46 && byte != 45 && byte != 43 {
      return Err("release system dependencies require flat loader names")
    }
    if format == "pe" && byte >= 65 && byte <= 90 {
      return Err("PE system dependency names must use lowercase ASCII")
    }
    folded.push(if byte >= 65 && byte <= 90 { byte + 32 } else { byte })
  }
  // PE inputs are already lowercase. Other systems retain exact dependency
  // identity, while admission also rejects aliases differing only by case.
  if format == "pe" { return Ok(name) }
  let bytes = Bytes.fromArray(folded)?
  bytes.decodeUtf8()
}

function systemDependencies(recipe: ReleaseRecipe) -> Result<(), string> {
  if recipe.allowedSystemDependencies.length > 128 {
    return Err("release recipe exceeds 128 system dependencies")
  }
  let mut seen: Set<string> = set {}
  let mut ordered: Array<string> = []
  for name in recipe.allowedSystemDependencies {
    let key = dependencyKey(name, recipe.format)?
    if seen.contains(key) { return Err("duplicate or case-aliased release system dependency: {name}") }
    seen.add(key)
    ordered.push(name)
  }
  ordered.sort()
  if ordered.join("\n") != recipe.allowedSystemDependencies.join("\n") {
    return Err("release system dependencies must be sorted")
  }
  Ok(())
}

function admittedSource(file: ReleaseFile, recipe: ReleaseRecipe) -> Result<(), string> {
  if file.role == "runtime" {
    if !file.source.startsWith("core-kit/distribution/runtime/{recipe.target}/") {
      return Err("release runtime files must be checked in under their distribution target")
    }
    return Ok(())
  }
  if file.role != "notice" && file.role != "component" {
    return Err("release file role must be notice, component or runtime")
  }
  if file.source.startsWith("core-kit/distribution/") { return Ok(()) }
  for required in requiredFiles() {
    if file.source == required.source { return Ok(()) }
  }
  Err("release notice/component source is outside the declared distribution inputs: {file.source}")
}

function fileMappings(recipe: ReleaseRecipe) -> Result<(), string> {
  if recipe.files.length == 0 || recipe.files.length > 128 {
    return Err("release recipe must contain between 1 and 128 file mappings")
  }
  let mut destinations: Set<string> = set {}
  let mut sources: Set<string> = set {}
  let mut ordered: Array<string> = []
  let mut byName: Map<string, ReleaseFile> = map {}
  for file in recipe.files {
    let source = portablePath(file.source)?
    let destination = portablePath(file.destination)?
    if file.destination.contains("/") || file.destination.startsWith(".") || file.destination.byteLength() > 100 {
      return Err("release payload destinations must be flat visible filenames of at most 100 ASCII bytes")
    }
    if destination == "assembly.json" || destination == "payload.json" || destination == "generated_cli.rs" ||
      destination == "topaz-core-kit" || destination == "topaz-core-kit.exe" {
      return Err("release file mapping uses a reserved destination: {file.destination}")
    }
    if sources.contains(source) || destinations.contains(destination) {
      return Err("duplicate or case-aliased release source/destination")
    }
    admittedSource(file, recipe)?
    sources.add(source)
    destinations.add(destination)
    ordered.push(file.destination)
    byName.insert(file.destination, file)
  }
  let original = ordered.join("\n")
  ordered.sort()
  if original != ordered.join("\n") { return Err("release file mappings must be sorted by destination") }
  for required in requiredFiles() {
    let file = match byName.get(required.destination) {
      case Some(found) => found
      case None => return Err("required release notice/component mapping is missing: {required.destination}")
    }
    if file.source != required.source || file.role != required.role {
      return Err("required release notice/component mapping was substituted: {required.destination}")
    }
  }
  Ok(())
}

export function admitRecipe(text: string) -> Result<ReleaseRecipe, string> {
  if text.byteLength() == 0 || text.byteLength() > 1048576 {
    return Err("release recipe must be nonempty and no larger than 1 MiB")
  }
  let recipe = json.parseAs<ReleaseRecipe>(text)?
  if recipe.schema != RECIPE_SCHEMA { return Err("unsupported release recipe schema") }
  if text != "{json.stringify(recipe)?}\n" {
    return Err("release recipe must use canonical JSON with one final LF")
  }
  targetContract(recipe)?
  systemDependencies(recipe)?
  fileMappings(recipe)?
  Ok(recipe)
}

export function loadRecipe(root: string, path: string) -> Result<LoadedRecipe, string> {
  portablePath(path)?
  if !path.startsWith("core-kit/distribution/") || !path.endsWith(".json") {
    return Err("release recipe must be a repository-relative JSON file under core-kit/distribution")
  }
  let records = repositoryFiles(root)?
  let mut covered: Set<string> = set {}
  let mut byteCounts: Map<string, int> = map {}
  let mut hashes: Map<string, string> = map {}
  for record in records {
    covered.add(record.path)
    byteCounts.insert(record.path, record.bytes)
    hashes.insert(record.path, record.sha256)
  }
  if !covered.contains(path) { return Err("release recipe is absent from the repository input inventory") }
  requireRegularInput(root, path)?
  let text = files.readText("{root}/{path}")?
  let digest = text.encodeUtf8().sha256().toHex()
  if digest != hashes.getOr(path, "") { return Err("release recipe changed while its inputs were inspected") }
  let recipe = admitRecipe(text)?
  for file in recipe.files {
    if file.source == path { return Err("release recipe cannot copy itself through a file mapping") }
    if !covered.contains(file.source) {
      return Err("release source is absent from the repository input inventory: {file.source}")
    }
    requireRegularInput(root, file.source)?
    let size = byteCounts.getOr(file.source, 0)
    if size == 0 || size > recipe.fileByteLimit {
      return Err("release source must be nonempty and within the payload file limit: {file.source}")
    }
  }
  Ok(LoadedRecipe { path: path, text: text, sha256: digest, recipe: recipe })
}

import std.fs as files
import std.json as json
import src.contracts {
  COMPILER_SOURCE_SET, EXCHANGE_SCHEMA,
  CompilerRequest, HostFact, PackageFacts, StandardModule,
}

function sourceFact(path: string, source: string) -> HostFact {
  HostFact {
    kind: "read-source", mountId: "root", logicalPath: path,
    status: "present", source: source, entries: [], aliasClass: "", reasonCode: "",
  }
}

function virtualEntryContainment() -> HostFact {
  HostFact {
    kind: "physical-containment", mountId: "root", logicalPath: "main.tpz",
    status: "inside", source: "", entries: [], aliasClass: "main.tpz", reasonCode: "",
  }
}

function budget(value: int, maximum: int, name: string) -> Result<(), string> {
  if value < 1 || value > maximum {
    Err("closed request budget {name} must be in 1..{maximum}")
  } else {
    Ok(())
  }
}

function validateBudgets(request: CompilerRequest) -> Result<(), string> {
  budget(request.maxSourceFacts, 16384, "maxSourceFacts")?
  budget(request.maxTotalSourceBytes, 67108864, "maxTotalSourceBytes")?
  budget(request.maxAstNodes, 2000000, "maxAstNodes")?
  budget(request.maxAstDepth, 1024, "maxAstDepth")?
  budget(request.maxRawTokens, 4000000, "maxRawTokens")?
  budget(request.maxLayoutTokens, 4000000, "maxLayoutTokens")?
  budget(request.maxHirNodes, 2000000, "maxHirNodes")?
  budget(request.maxLoweredNodes, 4000000, "maxLoweredNodes")?
  budget(request.maxDiagnostics, 100000, "maxDiagnostics")?
  budget(request.maxGeneratedRustBytes, 536870912, "maxGeneratedRustBytes")?
  budget(request.maxFactRounds, 49156, "maxFactRounds")?
  Ok(())
}

export function standardModules(repositoryRoot: string) -> Result<Array<StandardModule>, string> {
  let mut modules: Array<StandardModule> = []
  for name in ["bytes", "fs", "io", "json"] {
    let path = "std/{name}.tpz"
    let source = files.readText("{repositoryRoot}/compiler/seed/initial/{path}")?
    modules.push(StandardModule { identity: "std.{name}", path: path, source: source })
  }
  modules.push(StandardModule {
    identity: "std.toml", path: "std/toml.tpz",
    source: files.readText("{repositoryRoot}/core-kit/cli/std/toml.tpz")?,
  })
  Ok(modules)
}

export function fromSource(path: string, repositoryRoot: string) -> Result<CompilerRequest, string> {
  let source = files.readText(path)?
  if source.byteLength() > 16777216 {
    return Err("source exceeds the Core Kit single-file limit of 16 MiB")
  }
  let modules = standardModules(repositoryRoot)?
  let mut sourceBytes = source.byteLength()
  for module in modules { sourceBytes += module.source.byteLength() }
  if sourceBytes > 16777216 {
    return Err("source and bundled standard modules together exceed 16 MiB")
  }
  // Containment describes this virtual one-file mount, which is inside by
  // construction. It makes no claim about the caller's filesystem root.
  Ok(CompilerRequest {
    schema: EXCHANGE_SCHEMA,
    producer: "topaz-stage1",
    compilerSourceSetId: COMPILER_SOURCE_SET,
    terminal: "typed",
    entry: "main.tpz", root: "", source: "", sourceId: "main.tpz",
    languageMode: "topaz-5.21", profile: "",
    facts: [sourceFact("main.tpz", source), virtualEntryContainment()],
    package: PackageFacts {
      buildRole: "standalone",
      externModules: [], externReplayModules: [], externReplayErrors: [],
      generatedStdModules: modules,
    },
    maxSourceFacts: 1024,
    maxTotalSourceBytes: 16777216,
    maxAstNodes: 1000000,
    maxAstDepth: 512,
    maxRawTokens: 2000000,
    maxLayoutTokens: 2000000,
    maxHirNodes: 1000000,
    maxLoweredNodes: 2000000,
    maxDiagnostics: 10000,
    maxGeneratedRustBytes: 134217728,
    maxFactRounds: 4096,
  })
}

export function fromFile(path: string) -> Result<CompilerRequest, string> {
  let text = files.readText(path)?
  fromText(text)
}

export function fromText(text: string) -> Result<CompilerRequest, string> {
  if text.byteLength() > 134217728 { return Err("closed request exceeds 128 MiB") }
  let request = json.parseAs<CompilerRequest>(text)?
  if request.schema != EXCHANGE_SCHEMA || request.languageMode != "topaz-5.21" {
    return Err("Core Kit requires the Stage 1 v2 exchange and topaz-5.21 language mode")
  }
  if request.compilerSourceSetId != COMPILER_SOURCE_SET {
    return Err("closed request targets a different canonical compiler source set")
  }
  if request.producer != "topaz-stage1" && request.producer != "topaz-stage2" {
    return Err("closed request has an unsupported producer")
  }
  if request.package.externModules.length != 0 ||
    request.package.externReplayModules.length != 0 ||
    request.package.externReplayErrors.length != 0 {
    return Err("Core Kit does not provide extern replay or private evaluator packages")
  }
  validateBudgets(request)?
  if request.facts.length > 65536 { return Err("closed request has too many facts") }
  let mut keys: Set<string> = set {}
  let mut entries = 0
  let mut containment = 0
  let mut sourceCount = 0
  let mut sourceBytes = 0
  for fact in request.facts {
    if fact.mountId != "root" { return Err("closed request facts must use the root mount") }
    if fact.kind != "read-source" && fact.kind != "physical-containment" && fact.kind != "list-directory" {
      return Err("unsupported fact kind: {fact.kind}")
    }
    let key = "{fact.kind}\n{fact.mountId}\n{fact.logicalPath}"
    if keys.contains(key) { return Err("duplicate source fact: {fact.kind} {fact.logicalPath}") }
    keys.add(key)
    if fact.kind == "read-source" && fact.logicalPath == request.entry && fact.status == "present" {
      entries += 1
    }
    if fact.kind == "physical-containment" && fact.logicalPath == request.entry {
      containment += 1
    }
    if fact.kind == "read-source" {
      sourceCount += 1
      if fact.status == "present" { sourceBytes += fact.source.byteLength() }
    }
  }
  if entries != 1 { return Err("closed request must contain exactly one present entry source fact") }
  if containment != 1 { return Err("closed request must contain the entry containment fact") }
  if sourceCount > request.maxSourceFacts || sourceBytes > request.maxTotalSourceBytes {
    return Err("closed request source facts exceed its declared budgets")
  }
  let mut identities: Set<string> = set {}
  let mut paths: Set<string> = set {}
  for module in request.package.generatedStdModules {
    if !module.identity.startsWith("std.") || module.identity == "std.lispex" {
      return Err("unsupported generated standard module: {module.identity}")
    }
    if identities.contains(module.identity) || paths.contains(module.path) {
      return Err("duplicate generated standard module: {module.identity}")
    }
    identities.add(module.identity)
    paths.add(module.path)
    sourceBytes += module.source.byteLength()
  }
  if sourceBytes > 67108864 { return Err("closed request including standard modules exceeds 64 MiB") }
  Ok(request)
}

export function encode(request: CompilerRequest, terminal: string) -> Result<string, string> {
  json.stringify(CompilerRequest { ...request, terminal: terminal })
}

import std.json as json
import src.contracts { CompilerResponse, Diagnostic }

function diagnosticLines(diagnostics: Array<Diagnostic>) -> Array<string> {
  let mut lines: Array<string> = []
  for diagnostic in diagnostics {
    lines.push("{diagnostic.code}: module {diagnostic.moduleIndex}, bytes {diagnostic.lo}..{diagnostic.hi}: {diagnostic.message}")
    for note in diagnostic.notes { lines.push("  {note}") }
  }
  lines
}

export function completed(text: string, terminal: string) -> Result<CompilerResponse, string> {
  let response = json.parseAs<CompilerResponse>(text)?
  if response.status != "completed" {
    let mut lines = diagnosticLines(response.diagnostics)
    for line in diagnosticLines(response.checkerDiagnostics) { lines.push(line) }
    if lines.length == 0 { lines.push("compiler status: {response.status}") }
    return Err(lines.join("\n"))
  }
  if response.kind != terminal {
    return Err("compiler returned `{response.kind}` for requested `{terminal}`")
  }
  Ok(response)
}

export function rustSource(response: CompilerResponse) -> Result<string, string> {
  match response.generatedRust {
    case Some(source) => if source == "" {
      Err("compiler completed without generated Rust")
    } else {
      Ok(source)
    }
    case None => Err("compiler completed without generated Rust")
  }
}

import std.json as json
import src.contracts { Capture, CapturedOutput, Native }

export record BuildTarget derives JSON {
  target: string,
  executableSuffix: string,
}

function targetInfo(native: Native) -> Result<BuildTarget, string> {
  let info = json.parseAs<BuildTarget>(native("build-target", [])?)?
  if info.target == "" || info.target.byteLength() > 128 {
    return Err("native build target is missing or invalid")
  }
  for byte in info.target.encodeUtf8().toArray() {
    let letter = (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122)
    let digit = byte >= 48 && byte <= 57
    if !letter && !digit && byte != 95 && byte != 45 {
      return Err("native build target contains invalid characters")
    }
  }
  let suffix = if info.target.contains("-windows-") { ".exe" } else { "" }
  if info.executableSuffix != suffix { return Err("native executable suffix differs from its target") }
  Ok(info)
}

function toolOutput(
  capture: Capture,
  executable: string,
  arguments: Array<string>,
  repositoryRoot: string,
) -> Result<string, string> {
  let response = json.parseAs<CapturedOutput>(capture(
    executable, arguments, "{repositoryRoot}/compiler",
    ["RUSTUP_TOOLCHAIN=1.96.0", "RUSTUP_AUTO_INSTALL=0", "CARGO_NET_OFFLINE=true"],
  )?)?
  if response.code != 0 {
    return Err("{executable} toolchain check failed with exit {response.code}\n{response.stderr}")
  }
  if response.stdout.byteLength() > 65536 { return Err("unexpectedly large {executable} version output") }
  Ok(response.stdout.replace("\r\n", "\n"))
}

export function checkToolchain(repositoryRoot: string, native: Native, capture: Capture) -> Result<BuildTarget, string> {
  let target = targetInfo(native)?
  let rust = toolOutput(capture, "rustc", ["-vV"], repositoryRoot)?
  let mut release = ""
  let mut host = ""
  for line in rust.split("\n") {
    let parts = line.split(": ")
    if parts.length != 2 { continue }
    if parts[0] == "release" {
      if release != "" { return Err("Rust version output contains duplicate release fields") }
      release = parts[1]
    }
    if parts[0] == "host" {
      if host != "" { return Err("Rust version output contains duplicate host fields") }
      host = parts[1]
    }
  }
  if release != "1.96.0" { return Err("native builds require installed Rust 1.96.0, found `{release}`") }
  if host != target.target {
    return Err("Rust host `{host}` differs from this Kit's native target `{target.target}`")
  }
  let cargo = toolOutput(capture, "cargo", ["--version"], repositoryRoot)?
  if !cargo.startsWith("cargo 1.96.0 ") {
    return Err("native builds require installed Cargo 1.96.0")
  }
  Ok(target)
}

import std.fs as files
import std.io as io
import src.contracts { COMPILER_SOURCE_SET }
import src.payload_files { portablePath }

export record FileRecord {
  kind: string,
  path: string,
  digest: string,
}

export record Inventory {
  files: Array<FileRecord>,
  compilerCount: int,
  snapshotCount: int,
  inputCount: int,
}

function validDigest(text: string) -> bool {
  let bytes = text.encodeUtf8()
  if bytes.length() != 64 { return false }
  for byte in bytes.toArray() {
    if !((byte >= 48 && byte <= 57) || (byte >= 97 && byte <= 102)) { return false }
  }
  true
}

function validPath(text: string) -> bool {
  if text == "" || text.startsWith("/") || text.endsWith("/") || text.contains("//") {
    return false
  }
  for segment in text.split("/") {
    if segment == "." || segment == ".." { return false }
  }
  for byte in text.encodeUtf8().toArray() {
    let letter = (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122)
    let digit = byte >= 48 && byte <= 57
    if !letter && !digit && byte != 95 && byte != 46 && byte != 47 && byte != 45 {
      return false
    }
  }
  true
}

function expectedCount(metadata: Map<string, string>, key: string, observed: int) -> Result<(), string> {
  let text = metadata.getOr(key, "")
  if text == "" || text.startsWith("0") { return Err("invalid inventory count: {key}") }
  for byte in text.encodeUtf8().toArray() {
    if byte < 48 || byte > 57 { return Err("invalid inventory count: {key}") }
  }
  match text.toInt() {
    case Some(expected) => if expected == observed && expected > 0 {
      Ok(())
    } else {
      Err("inventory count mismatch: {key}")
    }
    case None => Err("inventory count is outside the integer range: {key}")
  }
}

export function parseInventory(text: string) -> Result<Inventory, string> {
  if text.byteLength() == 0 || text.byteLength() > 1048576 {
    return Err("verifier inventory must be nonempty and no larger than 1 MiB")
  }
  let mut metadata: Map<string, string> = map {}
  let mut records: Array<FileRecord> = []
  let mut seen: Set<string> = set {}
  let mut inputs: Set<string> = set {}
  let mut compilerCount = 0
  let mut snapshotCount = 0
  let mut inputCount = 0
  let mut lineNumber = 0
  for line in text.split("\n") {
    lineNumber += 1
    if line == "" || line.startsWith("#") { continue }
    let fields = line.split("|")
    let kind = fields[0]
    if kind == "format" || kind == "compiler_source_set" ||
      kind == "compiler_sources" || kind == "snapshot_files" || kind == "input_files" {
      if fields.length != 2 || metadata.containsKey(kind) {
        return Err("invalid or duplicate inventory metadata at line {lineNumber}")
      }
      metadata.insert(kind, fields[1])
      continue
    }
    if kind != "compiler_source" && kind != "snapshot_file" && kind != "input_file" {
      return Err("unknown inventory record at line {lineNumber}")
    }
    if fields.length != 3 {
      return Err("inventory file record needs three fields at line {lineNumber}")
    }
    let path = fields[1]
    let digest = fields[2]
    if !validPath(path) || !validDigest(digest) {
      return Err("invalid inventory path or digest at line {lineNumber}")
    }
    if kind != "compiler_source" && portablePath(path)? == "core-kit/downloads.data" {
      return Err("download catalogue must remain outside the recorded build inputs")
    }
    let key = "{kind}|{path}"
    if seen.contains(key) { return Err("duplicate inventory file record: {key}") }
    seen.add(key)
    records.push(FileRecord { kind: kind, path: path, digest: digest })
    if kind == "compiler_source" {
      compilerCount += 1
    } else if kind == "snapshot_file" {
      snapshotCount += 1
    } else {
      inputCount += 1
      inputs.add(path)
    }
  }
  if metadata.getOr("format", "") != "topaz.core-kit-inputs/v2" {
    return Err("unsupported verifier inventory format")
  }
  if metadata.getOr("compiler_source_set", "") != COMPILER_SOURCE_SET {
    return Err("verifier inventory targets a different canonical compiler")
  }
  expectedCount(metadata, "compiler_sources", compilerCount)?
  expectedCount(metadata, "snapshot_files", snapshotCount)?
  expectedCount(metadata, "input_files", inputCount)?
  for path in [
    "SOURCE-COMPONENTS.json",
    "compiler/generated/native/compiler.json",
    "compiler/generated/native/compiler.rs",
    "compiler/seed/initial/request.json",
    "compiler/seed/initial/REQUEST-PROVENANCE.json",
    "compiler/seed/initial/std/bytes.tpz",
    "compiler/seed/initial/std/fs.tpz",
    "compiler/seed/initial/std/io.tpz",
    "compiler/seed/initial/std/json.tpz",
    "core-kit/cli/REQUEST.json",
    "core-kit/cli/initial/request.json",
  ] {
    if !inputs.contains(path) { return Err("required verifier input is missing: {path}") }
  }
  Ok(Inventory {
    files: records,
    compilerCount: compilerCount,
    snapshotCount: snapshotCount,
    inputCount: inputCount,
  })
}

function checkHash(repositoryRoot: string, path: string, expected: string) -> Result<(), string> {
  let bytes = files.readBytes("{repositoryRoot}/{path}")?
  if bytes.sha256().toHex() != expected { return Err("hash mismatch: {path}") }
  Ok(())
}

function checkedInventory(repositoryRoot: string) -> Result<Inventory, string> {
  // Parse and validate the complete inventory before using any of its paths.
  // JSON manifests/requests are covered by their exact recorded byte hashes.
  let inventory = parseInventory(files.readText("{repositoryRoot}/core-kit/verify-core.data")?)?
  for file in inventory.files {
    if file.kind == "compiler_source" {
      checkHash(repositoryRoot, "compiler/crates/topaz_self_frontend/topaz/{file.path}", file.digest)?
      checkHash(repositoryRoot, "compiler/seed/initial/topaz/{file.path}", file.digest)?
    } else {
      checkHash(repositoryRoot, file.path, file.digest)?
    }
  }
  Ok(inventory)
}

export function validateRecordedInputs(repositoryRoot: string) -> Result<(), string> {
  checkedInventory(repositoryRoot)?
  Ok(())
}

export function verify(repositoryRoot: string) -> Result<int, string> {
  let inventory = checkedInventory(repositoryRoot)?
  io.writeLine("Core Kit input hashes match: {inventory.compilerCount} compiler source pairs, {inventory.snapshotCount} snapshot files, {inventory.inputCount} input files")
  io.writeLine("This checks recorded input bytes. It does not rebuild the compiler or prove reproducibility.")
  Ok(0)
}

